      tooltipKey={tooltipKey}
      tooltips={tooltips}
      style={{
        width: labelWidth,
        flexShrink: 0,
        textAlign: "left",
        whiteSpace: "nowrap",
        display: "inline-block",
      }}
    >
      {label}
    </PcmSharedFieldLabel>
    <div style={{ flex: 1, minWidth: 0, width: fieldWidth }}>{children}</div>
  </div>
);

