const extractCallerFromChannel = (ch) => {
  if (!ch?.channel) return "";
  const match = ch.channel.match(/DAHDI\/[^/]+\/(\d+)/);
  return match ? match[1] : "";
};

const extractCalledFromAppdata = (ch) => {
  if (!ch?.appdata) return "";
  const match = ch.appdata.match(/Dial\([^/]+\/(\d+)@/);
  return match ? match[1] : "";
};

