          <Btn
            onClick={handleCloseModal}
            variant="cancel"
            disabled={loading.save}
            style={sipToSipModalCancelBtnStyle}
          >
            {SIP_TO_SIP_ACCOUNT_BTN_CLOSE}
          </Btn>
        </DialogActions>
      </Dialog>
    </div>
    </>
  );
};

