const DATA_COLUMNS = DIALING_RULE_TABLE_COLUMNS.filter(
  (c) => c.key !== "check" && c.key !== "modify",
);

const DialingRulePage = () => {
  const vm = useDialingRulePage();
  const {
    isModalOpen,
    formData,
    rules,
    selected,
    page,
    itemsPerPage,
    totalPages,
    pagedRules,
    editIndex,
    indexSelect,
    toast,
    clearToast,
    getAvailableIndices,
    handleOpenModal,
    handleCloseModal,
    handleIndexSelectChange,
    handleInputChange,
    handleSave,
    handleSelectRow,
    handleCheckAll,
    handleUncheckAll,
    handleInverse,
    handleDelete,
    handleClearAll,
    handlePageChange,
    pagedSelectedCount,
    allPagedChecked,
  } = vm;

  return (
    <DialingRulePageShell>
      {toast.msg && (
        <Alert
          severity={toast.type}
          onClose={clearToast}
          sx={dialingRuleFixedAlertSx}
