          </Btn>
          <Btn
            variant="cancel"
            onClick={handleCloseModal}
            style={dialingRuleAddNewModalFooterCancelBtnStyle}
          >
            Close
          </Btn>
        </DialogActions>
      </Dialog>
    </DialingRulePageShell>
  );
};

