          )}
          {prohibitLimitCount > 1 && (
            <Btn
              variant="cancel"
              onClick={() => handlePeriodCountChange("minus")}
              style={fxsToolbarBtnStyle}
            >
              - Remove Period
            </Btn>
          )}
        </div>
      </div>
    </>
  );
};

