export const PortFxsBatchModifyFormBody = ({
  formId,
  form,
  portOptions,
  inDialog,
  message,
  setMessage,
  handleSave,
  handleCancel,
  handleChange,
  handleCheckbox,
  shouldShowField,
}) => {
  const fieldStyle = portFxsBatchDialogFieldStyle;
  const wideFieldStyle = { ...portFxsBatchDialogFieldStyle, width: "200px" };

  return (
    <>
      {message.text && (
        <Alert
          severity={
            message.type === "error"
              ? "error"
              : message.type === "success"
                ? "success"
                : "info"
          }
          onClose={() => setMessage({ type: "", text: "" })}
          sx={{
            position: "fixed",
            top: 20,
            right: 20,
            zIndex: 9999,
            minWidth: 300,
            boxShadow: 3,
          }}
        >
          {message.text}
        </Alert>
      )}

      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 16,
          width: "100%",
        }}
      >
        <form id={formId} onSubmit={handleSave} style={fxsBatchModifyFormShellStyle}>
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 14,
              background: "#f8fafc",
              border: `1px solid ${C.cardBorder}`,
              borderRadius: 8,
              padding: 20,
              width: "100%",
              boxSizing: "border-box",
            }}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "center",
                width: "100%",
              }}
            >
              <table
                cellSpacing="0"
                cellPadding="0"
                style={{
                  width: BATCH_FORM_TABLE_WIDTH,
                  maxWidth: "100%",
                  tableLayout: "fixed",
                  textAlign: "left",
                }}
              >
                <colgroup>
                  <col style={{ width: BATCH_LABEL_WIDTH }} />
                  <col />
                </colgroup>
                <tbody>
                  {PORT_FXS_BATCH_MODIFY_FIELDS.map((field, idx) => {
                    if (!shouldShowField(field)) return null;

                    const prevField =
                      idx > 0 ? PORT_FXS_BATCH_MODIFY_FIELDS[idx - 1] : null;
                    const needsSpacer = getPortFxsBatchSpacerBeforeField(
                      prevField,
                      shouldShowField,
                    );

                    return (
                      <React.Fragment key={field.key}>
                        {needsSpacer && (
                          <tr>
                            <td colSpan={2} style={{ height: 10 }} />
                          </tr>
                        )}

                        <tr>
                          <td style={batchLabelCellStyle}>
                            <PortFxsBatchFieldLabel
                              tooltipKey={field.key}
                              tooltips={PORT_FXS_BATCH_MODIFY_FIELD_TOOLTIPS}
                            >
                              {field.label}
                            </PortFxsBatchFieldLabel>
                          </td>
                          <td style={batchValueCellStyle}>
                            {field.type === "checkbox" ? (
                              <label
                                style={{
                                  display: "inline-flex",
                                  alignItems: "center",
                                  gap: 4,
                                  fontSize: 13,
                                  color: C.valueText,
                                  cursor:
                                    field.key === "dnd" && form.callForward
                                      ? "not-allowed"
                                      : field.key === "callForward" && form.dnd
                                        ? "not-allowed"
                                        : "pointer",
                                }}
                              >
                                <Checkbox
                                  size="small"
                                  checked={!!form[field.key]}
                                  onChange={() => handleCheckbox(field.key)}
                                  disabled={
                                    field.key === "dnd"
                                      ? !!form.callForward
                                      : field.key === "callForward"
                                        ? !!form.dnd
                                        : false
                                  }
                                  sx={portFxsBatchCheckboxSx}
                                />
                                Enable
                              </label>
                            ) : field.type === "text" ? (
                              <input
                                type="text"
                                value={form[field.key]}
                                onChange={(e) =>
                                  handleChange(field.key, e.target.value)
                                }
                                style={fieldStyle}
                                {...portFxsBatchNativeFieldInteraction}
                                maxLength={field.maxLength || 31}
                                onKeyDown={getPortFxsBatchFieldKeyDown(field)}
                              />
                            ) : field.type === "password" ? (
                              <input
                                type="password"
                                value={form[field.key]}
                                onChange={(e) =>
                                  handleChange(field.key, e.target.value)
                                }
                                style={fieldStyle}
                                {...portFxsBatchNativeFieldInteraction}
                                maxLength={field.maxLength || 63}
                              />
                            ) : field.type === "select" ? (
                              <select
                                value={form[field.key]}
                                onChange={(e) =>
                                  handleChange(field.key, e.target.value)
                                }
                                style={
                                  field.key.includes("Parameter")
                                    ? wideFieldStyle
                                    : fieldStyle
                                }
                                {...portFxsBatchNativeFieldInteraction}
                              >
                                {(field.key === "startingPort" ||
                                field.key === "endingPort"
                                  ? portOptions
                                  : field.options
                                ).map((opt) => (
                                  <option key={opt} value={opt}>
                                    {opt}
                                  </option>
                                ))}
                              </select>
                            ) : null}
                          </td>
                        </tr>
                      </React.Fragment>
                    );
                  })}

                  <tr>
                    <td colSpan={2} style={{ height: 8 }} />
                  </tr>
                </tbody>
              </table>
            </div>
          </div>

          {!inDialog && (
            <div style={pageFooterStyle}>
              <Btn
                variant="primary"
                type="button"
                onClick={handleSave}
                style={addNewModalFooterBtnStyle}
              >
                Save
              </Btn>
              <Btn
                variant="cancel"
                type="button"
                onClick={handleCancel}
                style={addNewModalFooterCancelBtnStyle}
              >
                Close
              </Btn>
            </div>
          )}
        </form>

        <div
          style={{
            textAlign: "center",
            fontSize: 12,
            color: "#dc2626",
            width: "100%",
            whiteSpace: "nowrap",
            overflowX: "auto",
          }}
        >
          {PORT_FXS_BATCH_MODIFY_NOTE}
        </div>
      </div>
    </>
  );
};

