export const PortFxsModifyFormBody = ({
  formId,
  form,
  portOptions,
  inDialog,
  saving,
  message,
  setMessage,
  handleSave,
  handleReset,
  handleCancel,
  handleChange,
  handleCheckbox,
  shouldShowField,
}) => {
  const dialogFieldStyle = {
    ...nativeFieldInputStyle,
    height: 32,
    width: "180px",
  };
  const legacyFieldStyle = {
    height: "22px",
    width: "180px",
    fontSize: "12px",
  };
  const fieldStyle = inDialog
    ? dialogFieldStyle
    : { ...dialogFieldStyle, ...legacyFieldStyle };
  const wideFieldStyle = inDialog
    ? { ...dialogFieldStyle, width: "200px" }
    : { ...dialogFieldStyle, ...legacyFieldStyle, width: "200px" };
  const fieldClassName = inDialog
    ? undefined
    : "border border-gray-400 rounded-sm px-1 bg-white";

  return (
    <>
      {message.text && (
        <Alert
          severity={
            message.type === "error"
              ? "error"
              : message.type === "success"
                ? "success"
                : "info"
          }
          onClose={() => setMessage({ type: "", text: "" })}
          sx={{
            position: "fixed",
            top: 20,
            right: 20,
            zIndex: 9999,
            minWidth: 300,
            boxShadow: 3,
          }}
        >
          {message.text}
        </Alert>
      )}

      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 16,
          width: "100%",
        }}
      >
        <form id={formId} onSubmit={handleSave} style={fxsModifyFormShellStyle}>
          <div
            style={
              inDialog
                ? {
                    display: "flex",
                    flexDirection: "column",
                    gap: 14,
                    background: "#f8fafc",
                    border: `1px solid ${MODIFY_C.cardBorder}`,
                    borderRadius: 8,
                    padding: 20,
                    width: "100%",
                    boxSizing: "border-box",
                  }
                : undefined
            }
            className={
              inDialog
                ? undefined
                : "bg-[#dde0e4] border-2 rounded-b-lg border-gray-400 border-t-0 shadow-sm py-2 text-xs w-full"
            }
          >
            <div
              style={{
                display: "flex",
                justifyContent: "center",
                width: "100%",
              }}
            >
              <table
                cellSpacing="0"
                cellPadding="0"
                style={{
                  width: FORM_TABLE_WIDTH,
                  maxWidth: "100%",
                  tableLayout: "fixed",
                  textAlign: "left",
                }}
              >
                <colgroup>
                  <col style={{ width: FORM_LABEL_WIDTH }} />
                  <col />
                </colgroup>
                <tbody>
                  {PORT_FXS_MODIFY_FIELDS.map((field, idx) => {
                    if (!shouldShowField(field)) return null;

                    const prevField =
                      idx > 0
                        ? PORT_FXS_MODIFY_FIELDS.slice(0, idx)
                            .reverse()
                            .find((f) => shouldShowField(f))
                        : null;
                    const needsSpacer = getPortFxsModifySpacerBeforeField(prevField);

                    return (
                      <React.Fragment key={field.key}>
                        {needsSpacer && (
                          <tr>
                            <td colSpan={2} style={{ height: 10 }} />
                          </tr>
                        )}

                        <tr>
                          <td style={labelCellStyle}>
                            <PortFxsModifyFieldLabel
                              tooltipKey={field.key}
                              tooltips={PORT_FXS_MODIFY_FIELD_TOOLTIPS}
                            >
                              {field.label}
                            </PortFxsModifyFieldLabel>
                          </td>
                          <td style={valueCellStyle}>
                            {field.type === "checkbox" ? (
                              <label
                                style={{
                                  display: "inline-flex",
                                  alignItems: "center",
                                  gap: 4,
                                  fontSize: 13,
                                  color: MODIFY_C.valueText,
                                  cursor:
                                    field.key === "dnd" && form.callForward
                                      ? "not-allowed"
                                      : field.key === "callForward" && form.dnd
                                        ? "not-allowed"
                                        : "pointer",
                                }}
                              >
                                <Checkbox
                                  size="small"
                                  checked={!!form[field.key]}
                                  onChange={() => handleCheckbox(field.key)}
                                  disabled={
                                    field.key === "dnd"
                                      ? !!form.callForward
                                      : field.key === "callForward"
                                        ? !!form.dnd
                                        : false
                                  }
                                  sx={portFxsModifyCheckboxSx}
                                />
                                Enable
                              </label>
                            ) : field.type === "text" ? (
                              <input
                                type="text"
                                value={form[field.key]}
                                onChange={(e) =>
                                  handleChange(field.key, e.target.value)
                                }
                                className={fieldClassName}
                                style={fieldStyle}
                                {...portFxsModifyNativeFieldInteraction}
                                maxLength={field.maxLength || 31}
                                onKeyDown={getPortFxsModifyFieldKeyDown(field)}
                              />
                            ) : field.type === "password" ? (
                              <input
                                type="password"
                                value={form[field.key]}
                                onChange={(e) =>
                                  handleChange(field.key, e.target.value)
                                }
                                className={fieldClassName}
                                style={fieldStyle}
                                {...portFxsModifyNativeFieldInteraction}
                                maxLength={field.maxLength || 63}
                              />
                            ) : field.type === "select" ? (
                              <select
                                value={form[field.key]}
                                onChange={(e) =>
                                  handleChange(field.key, e.target.value)
                                }
                                className={fieldClassName}
                                style={
                                  field.key.includes("Parameter")
                                    ? wideFieldStyle
                                    : fieldStyle
                                }
                                {...portFxsModifyNativeFieldInteraction}
                              >
                                {(field.key === "startingPort"
                                  ? portOptions
                                  : field.options
                                ).map((opt) => (
                                  <option key={opt} value={opt}>
                                    {opt}
                                  </option>
                                ))}
                              </select>
                            ) : null}
                          </td>
                        </tr>

                        {field.key === "startingPort" && (
                          <tr>
                            <td style={labelCellStyle}>
                              <PortFxsModifyFieldLabel
                                tooltipKey="type"
                                tooltips={PORT_FXS_MODIFY_FIELD_TOOLTIPS}
                              >
                                Type
                              </PortFxsModifyFieldLabel>
                            </td>
                            <td style={valueCellStyle}>
                              <input
                                type="text"
                                value="FXS"
                                readOnly
                                className={fieldClassName}
                                style={fieldStyle}
                                {...portFxsModifyNativeFieldInteraction}
                              />
                            </td>
                          </tr>
                        )}
                      </React.Fragment>
                    );
                  })}
                  <tr>
                    <td colSpan={2} style={{ height: 8 }} />
                  </tr>
                </tbody>
              </table>
            </div>
          </div>

          {!inDialog && (
            <div style={pageFooterStyle}>
              <Btn
                variant="primary"
                type="submit"
                disabled={saving}
                style={addNewModalFooterBtnStyle}
              >
                {saving ? "Saving..." : "Modify"}
              </Btn>
              <Btn
                variant="cancel"
                type="button"
                onClick={handleReset}
                style={addNewModalFooterCancelBtnStyle}
              >
                Reset
              </Btn>
              <Btn
                variant="cancel"
                type="button"
                onClick={handleCancel}
                style={addNewModalFooterCancelBtnStyle}
              >
                Close
              </Btn>
            </div>
          )}
        </form>

        <div
          style={{
            textAlign: "center",
            fontSize: 12,
            color: "#dc2626",
            width: "100%",
            whiteSpace: "nowrap",
            overflowX: "auto",
          }}
        >
          {PORT_FXS_BATCH_MODIFY_NOTE}
        </div>
      </div>
    </>
  );
};

