  justifyContent: "flex-start",
};

export const FxsVoipSipFieldControl = ({
  field,
  form,
  registrationMode,
  saving,
  onChange,
  onCheckbox,
}) => {
  if (!shouldShowFxsVoipSipField(form, field)) return null;

  const fieldInputStyle = { ...nativeFieldInputStyle, width: "100%" };
  const fieldSelectStyle = { ...nativeFieldSelectStyle, width: "100%" };
  const sipFieldInteraction = getFxsVoipSipNativeFieldInteraction(saving);
  const fieldReadonlyStyle = {
    ...fieldInputStyle,
    backgroundColor: "#f1f5f9",
    lineHeight: "36px",
    height: 36,
    whiteSpace: "normal",
    wordBreak: "break-word",
  };

  return (
    <FxsVoipSipFieldRow key={field.key} label={field.label} tooltipKey={field.key}>
      <div style={valueColStyle}>
        {field.type === "readonly" && (
          <div style={controlSlotStyle}>
            <div
              style={{
                ...fieldReadonlyStyle,
                width: "100%",
                ...(field.key === "registerStatus"
                  ? {
                      whiteSpace: "nowrap",
                      textAlign: "center",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                    }
                  : {}),
              }}
            >
              {field.key === "registerStatus"
                ? getFxsVoipSipRegisterStatusDisplay(
                    registrationMode,
                    form.registerStatus,
                  )
                : form[field.key]}
            </div>
          </div>
        )}

        {field.type === "text" && (
          <div style={controlSlotStyle}>
            <input
              type="text"
              value={form[field.key] || ""}
              onChange={(e) => onChange(field.key, e.target.value)}
              style={fieldInputStyle}
              disabled={saving}
              {...sipFieldInteraction}
            />
          </div>
        )}

        {field.type === "select" && (
          <div style={controlSlotStyle}>
            <select
              value={form[field.key] || ""}
              onChange={(e) => onChange(field.key, e.target.value)}
              style={fieldSelectStyle}
              disabled={saving}
              {...sipFieldInteraction}
            >
              {field.options.map((opt) => (
                <option key={opt} value={opt}>
                  {opt}
                </option>
              ))}
            </select>
          </div>
        )}

        {field.type === "checkbox" && (
          <div style={controlSlotStyle}>
            <Checkbox
              size="small"
              checked={!!form[field.key]}
              onChange={() => onCheckbox(field.key)}
              disabled={saving}
              sx={fxsVoipSipCheckboxSx}
            />
          </div>
        )}

        {field.helper && (
          <div
            style={{
              width: 220,
              maxWidth: "100%",
              color: C.amber,
              fontSize: 11,
              marginTop: 4,
              wordWrap: "break-word",
              textAlign: "left",
            }}
          >
            {field.helper}
          </div>
        )}
      </div>
    </FxsVoipSipFieldRow>
  );
};

