const CertificateFieldLabel = ({ tooltipKey, children }) => {
  const tooltip = CERTIFICATE_TOOLTIPS[tooltipKey];
  const labelNode = (
    <span
      style={{
        ...labelStyle,
        display: "inline-flex",
        width: "fit-content",
        cursor: tooltip ? "help" : "default",
      }}
    >
      {children}
    </span>
  );

  if (!tooltip) return labelNode;

  return (
    <Tooltip title={tooltip} {...tooltipProps}>
      {labelNode}
    </Tooltip>
  );
};


const CertificateManage = () => {
  const [form, setForm] = useState({});
  const [toast, setToast] = useState(CERTIFICATE_TOAST_DEFAULT);

  const showToast = (msg, type = "success") => {
    setToast({ msg, type });
    setTimeout(() => setToast(CERTIFICATE_TOAST_DEFAULT), CERTIFICATE_TOAST_DURATION_MS);
  };

  const handleChange = (e) => {
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleAction = (btnName) => {
    showToast(
      CERTIFICATE_MESSAGES.ACTION_SUCCESS(btnName),
      "success"
    );
  };

  return (
    <div
      style={CertificateManagePageWrapStyle} data-native-scroll>
      <div style={CertificateManagePageInnerStyle}>
    
      {/* ── Alerts ── */}
      {toast.msg && (
        <Alert
          severity={toast.type}
          onClose={() => setToast(CERTIFICATE_TOAST_DEFAULT)}
          sx={{
            position: "fixed",
            top: 20,
            right: 20,
            zIndex: 9999,
            minWidth: 300,
            boxShadow: 3,
          }}
        >
          {toast.msg}
        </Alert>
      )}

      {/* ── Breadcrumb ── */}

        <div
          style={{
            fontSize: 12,
            color: C.mutedText,
            marginBottom: 16,
            fontWeight: 400,
            display: "flex",
            alignItems: "center",
            gap: 4,
            flexWrap: "wrap",
          }}
        >
          {CERTIFICATE_BREADCRUMB.map((crumb, index) => (
            <React.Fragment key={index}>
              <span
                style={
                  index === CERTIFICATE_BREADCRUMB.length - 1
                    ? { color: "#1e293b", fontWeight: 600 }
                    : undefined
                }
              >
                {crumb}
              </span>
              {index < CERTIFICATE_BREADCRUMB.length - 1 && <span>&gt;</span>}
            </React.Fragment>
          ))}
        </div>

        <div style={{ ...tableContainerStyle, }}>
          <div style={blueBarStyle}>
            <span>{CERTIFICATE_CARD_TITLE}</span>
          </div>

          <div
            className="w-full px-5 pt-3 pb-0 flex flex-col items-center"
            style={{ borderBottomLeftRadius: 10, borderBottomRightRadius: 10 }}
          >
            <form
              className="w-full max-w-2xl grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-4 items-center"
              style={{ marginBottom: 12 }}
            >
              {CERTIFICATE_FIELDS.map((field) => (
                <React.Fragment key={field.name}>
                  <div style={{ justifySelf: "start", width: "fit-content" }}>
                    <CertificateFieldLabel tooltipKey={field.name}>
                      {field.label}:
                    </CertificateFieldLabel>
                  </div>
                  <div className="flex items-center min-w-0 w-full">
                    <input
                      type="text"
                      name={field.name}
                      value={form[field.name] || ""}
                      onChange={handleChange}
                      style={{ ...inputStyle, textAlign: "center" }}
                      {...inputInteraction}
                    />
                  </div>
                </React.Fragment>
              ))}
            </form>
          </div>

          <div
            style={{
              ...advancedFormInlineFooterStyle,
              width: "100%",
              marginLeft: 0,
              marginRight: 0,
            }}
          >
            {CERTIFICATE_BUTTON_CONFIG.map((btn) => (
              <Btn
                key={btn.name}
                type="button"
                variant={btn.variant}
                onClick={() => handleAction(btn.label)}
                style={
                  btn.variant === CERTIFICATE_BUTTON_VARIANTS.PRIMARY
                    ? CERTIFICATE_BUTTON_STYLE
                    : CERTIFICATE_CANCEL_BUTTON_STYLE
                }
              >
                {btn.label}
              </Btn>
            ))}
          </div>
        </div>
        {/* Note */}
        <p
          style={{
            margin: "16px 0 0",
            textAlign: "center",
            fontSize: 12,
            color: C.accent,
            width: "100%",
            whiteSpace: "nowrap",
            overflowX: "auto",
            lineHeight: 1.45,
          }}
        >
          {CERTIFICATE_NOTE}
        </p>
      </div>
    </div>
  );
};

