const DeviceLock = () => {
  const [selectedOptions, setSelectedOptions] = useState({});
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");

  const [error, setError] = useState("");
  const [toast, setToast] = useState(DEVICE_LOCK_DEFAULT_TOAST);

  const showToast = (msg, type = "success") => {
    setToast({ msg, type });
    setTimeout(
      () => setToast(DEVICE_LOCK_DEFAULT_TOAST),
      DEVICE_LOCK_TOAST_DURATION_MS,
    );
  };

  // Auto-hide error after 5 seconds
  useEffect(() => {
    if (error) {
      const timer = setTimeout(() => setError(""), DEVICE_LOCK_ERROR_HIDE_MS);
      return () => clearTimeout(timer);
    }
  }, [error]);

  const handleOptionChange = (option) => {
    setSelectedOptions((prev) => ({ ...prev, [option]: !prev[option] }));
  };

  const handleReset = () => {
    setSelectedOptions({});
    setPassword("");
    setConfirmPassword("");
    setError("");
  };

  const handleLock = (e) => {
    e.preventDefault();
    if (!password || !confirmPassword) {
      setError(DEVICE_LOCK_MESSAGES.passwordRequired);
      return;
    }
    if (password !== confirmPassword) {
      setError(DEVICE_LOCK_MESSAGES.passwordMismatch);
      return;
    }

    // Add lock logic here
    showToast(DEVICE_LOCK_MESSAGES.lockSuccess);
  };

  return (
    <div style={DeviceLockPageWrapStyle} data-native-scroll>
      <div style={DeviceLockPageInnerStyle}>
        {/* Breadcrumb */}
        <div
          style={{
            fontSize: 12,
            color: C.mutedText,
            marginBottom: 16,
            fontWeight: 400,
            display: "flex",
            alignItems: "center",
            gap: 4,
            flexWrap: "wrap",
          }}
        >
          <span>{DEVICE_LOCK_BREADCRUMB[0]}</span>
          <span>&gt;</span>
          <span>{DEVICE_LOCK_BREADCRUMB[1]}</span>
          <span>&gt;</span>
          <span style={{ color: C.strongText, fontWeight: 600 }}>
            {DEVICE_LOCK_BREADCRUMB[2]}
          </span>
        </div>

        {/* Global Toast */}
        {toast.msg && (
          <Alert
            severity={toast.type}
            onClose={() => setToast(DEVICE_LOCK_DEFAULT_TOAST)}
            sx={{
              position: "fixed",
              top: 16,
              right: 16,
              zIndex: 9999,
              boxShadow: C.cardShadow,
            }}
          >
            {toast.msg}
          </Alert>
        )}

        {/* Global Error Alert */}
        {error && (
          <Alert
            severity="error"
            onClose={() => setError("")}
            sx={{
              position: "fixed",
              top: 16,
              right: 16,
              zIndex: 9999,
              boxShadow: C.cardShadow,
            }}
          >
            {error}
          </Alert>
        )}

        <div style={tableContainerStyle}>
          {/* Header */}
          <div style={blueBarStyle}>{DEVICE_LOCK_PAGE_TITLE}</div>

          <form onSubmit={handleLock}>
            <div
              style={{
                padding: "10px 24px 0",
                maxWidth: 600,
                width: "100%",
                margin: "0 auto",
              }}
            >
              <div className="space-y-6">
                <div
                  style={{
                    fontSize: 14,
                    color: C.valueText,
                    textAlign: "center",
                    lineHeight: 1.6,
                    fontWeight: 500,
                    marginBottom: "32px",
                  }}
                >
                  {DEVICE_LOCK_LABELS.instruction}
                </div>

                {/* Checkbox Options */}
                <div className="flex justify-center gap-8 mb-8 flex-wrap">
                  {DEVICE_LOCK_OPTIONS.map((opt) => (
                    <label
                      key={opt.value}
                      className="flex items-center cursor-pointer select-none"
                      style={{
                        fontSize: 13,
                        fontWeight: 600,
                        color: C.labelText,
                        transition: "color 0.2s",
                      }}
                      onMouseOver={(e) =>
                        (e.currentTarget.style.color = C.strongText)
                      }
                      onMouseOut={(e) =>
                        (e.currentTarget.style.color = C.labelText)
                      }
                    >
                      <Checkbox
                        size="small"
                        checked={!!selectedOptions[opt.value]}
                        onChange={() => handleOptionChange(opt.value)}
                        sx={deviceLockCheckboxSx}
                      />
                      {opt.label}
                    </label>
                  ))}
                </div>

                {/* Password Fields — grid aligns both input boxes */}
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "max-content minmax(0, 280px)",
                    columnGap: 16,
                    rowGap: 16,
                    alignItems: "center",
                    margin: "0 auto",
                    width: "fit-content",
                    marginBottom: 12,
                  }}
                >
                  <label style={{ ...labelBaseStyle, textAlign: "left" }}>
                    {DEVICE_LOCK_LABELS.password}:
                  </label>
                  <input
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    style={deviceLockPasswordInputStyle}
                    {...inputInteraction}
                    autoComplete="new-password"
                  />
                  <label style={{ ...labelBaseStyle, textAlign: "right" }}>
                    {DEVICE_LOCK_LABELS.confirmPassword}:
                  </label>
                  <input
                    type="password"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    style={deviceLockPasswordInputStyle}
                    {...inputInteraction}
                    autoComplete="new-password"
                  />
                </div>
              </div>
            </div>

            <div style={advancedFormInlineFooterStyle}>
              <Btn
                variant={DEVICE_LOCK_BUTTON_VARIANTS.LOCK}
                onClick={handleLock}
                type="submit"
                style={DEVICE_LOCK_BUTTON_STYLE}
              >
                {DEVICE_LOCK_BUTTON_LABELS.LOCK}
              </Btn>
              <Btn
                variant={DEVICE_LOCK_BUTTON_VARIANTS.RESET}
                onClick={handleReset}
                type="button"
                style={DEVICE_LOCK_BUTTON_STYLE}
              >
                {DEVICE_LOCK_BUTTON_LABELS.RESET}
              </Btn>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

