    const f = e.target.files[0];
    setFile(f);
    setFileName(f ? f.name : SIP_ACCOUNT_UPLOAD.noFile);
  };

  const handleSave = (e) => {
    e.preventDefault();
    showToast(SIP_ACCOUNT_MESSAGES.SAVE_SUCCESS, "success");
