            <div className="p-6">
              <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
                {/* Inputs Row */}
            {/* Inputs Row */}
<div className="flex flex-col md:flex-row flex-wrap gap-6 flex-1">
