/** Standalone action footer — not attached to any table/card */
const signalingCaptureFooterStyle = {
  display: "flex",
  flexWrap: "wrap",
  alignItems: "center",
  justifyContent: "center",
  gap: 12,
  width: "100%",
  marginTop: 20,
  padding: "10px 20px",
  border: `1.5px solid ${C.cardBorder}`,
  borderRadius: 4,
  boxSizing: "border-box",
  background: C.cardBg,
  boxShadow: C.cardShadow,
};

const extractCmdOutput = (res) =>
  String(res?.responseData ?? res?.data ?? "").trim();

const getDateStr = () =>
  new Date().toISOString().split("T")[0].replace(/-/g, "_");

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const parsePcmIndex = (pcm) => {
  const n = parseInt(String(pcm).replace(/\D/g, ""), 10);
  return Number.isFinite(n) ? n : 0;
};

const parseTsNumber = (ts) => {
  const n = parseInt(String(ts).replace(/\D/g, ""), 10);
  return Number.isFinite(n) ? n : 16;
};

const dahdiChannelFromPcmTs = (pcm, ts) =>
  parsePcmIndex(pcm) * 32 + parseTsNumber(ts);

const emptySlotSessions = () => ({ ts: [null, null], e1: [null, null] });

const SignalingCapture = () => {
  // Data Capture state
  const [network, setNetwork] = useState(SIGNALING_CAPTURE_DEFAULTS.NETWORK);
  const [syslogEnabled, setSyslogEnabled] = useState(false);
  const [syslogDest, setSyslogDest] = useState(SIGNALING_CAPTURE_DEFAULTS.SYSLOG_DESTINATION);

  // Network interfaces state
  const [networkOptions, setNetworkOptions] = useState([]);
  const [loading, setLoading] = useState(true);

  // Data capture state
  const [isCapturing, setIsCapturing] = useState(false);
  const [isStopping, setIsStopping] = useState(false);
  const [captureProcessId, setCaptureProcessId] = useState(null);
  const [captureFileName, setCaptureFileName] = useState("");
  const [captureStatus, setCaptureStatus] = useState("");
  const [toast, setToast] = useState(SIGNALING_CAPTURE_TOAST_DEFAULT);

  const slotSessionRef = useRef(emptySlotSessions());
  const [slotRecording, setSlotRecording] = useState({
    ts: [false, false],
    e1: [false, false],
  });
  const [slotStopping, setSlotStopping] = useState({
    ts: [false, false],
    e1: [false, false],
  });

  const showToast = (msg, type = "success") => {
    setToast({ msg, type });
    setTimeout(() => setToast(SIGNALING_CAPTURE_TOAST_DEFAULT), SIGNALING_CAPTURE_TOAST_DURATION_MS);
  };

  const isAnySlotRecording = () =>
    slotRecording.ts.some(Boolean) || slotRecording.e1.some(Boolean);

  const setSlotRecordingFlag = (section, row, value) => {
    setSlotRecording((prev) => {
      const next = { ...prev, [section]: [...prev[section]] };
      next[section][row] = value;
      return next;
    });
  };

  const setSlotStoppingFlag = (section, row, value) => {
    setSlotStopping((prev) => {
      const next = { ...prev, [section]: [...prev[section]] };
      next[section][row] = value;
      return next;
    });
  };

  const downloadGzFileFromDevice = async (captureFileName, downloadName) => {
    const gzFile = `${captureFileName}.gz`;

    const checkRes = await postLinuxCmd({
      cmd: `ls -la '${captureFileName}' 2>/dev/null || echo FILE_NOT_FOUND`,
    });
    if (extractCmdOutput(checkRes).includes("FILE_NOT_FOUND")) {
      throw new Error("Capture file not found on server.");
    }

    const sizeCheckRes = await postLinuxCmd({
      cmd: `wc -c < '${captureFileName}' 2>/dev/null || echo 0`,
    });
    const rawSize = parseInt(extractCmdOutput(sizeCheckRes), 10) || 0;
    if (rawSize === 0) {
      throw new Error("Capture file is empty. Generate traffic and try again.");
    }

    const gzRes = await postLinuxCmd({
      cmd: `gzip -c '${captureFileName}' > '${gzFile}' 2>/dev/null && echo OK || echo FAILED`,
    });
    if (!extractCmdOutput(gzRes).includes("OK")) {
      throw new Error("Failed to compress capture file.");
    }

    const sizeRes = await postLinuxCmd({
      cmd: `wc -c < '${gzFile}' 2>/dev/null || echo 0`,
    });
    const fileSize = parseInt(extractCmdOutput(sizeRes), 10) || 0;
    if (fileSize === 0) {
      throw new Error("Compressed file is empty.");
    }

    const CHUNK_BYTES = 200 * 1024;
    const numChunks = Math.ceil(fileSize / CHUNK_BYTES);
    const binaryParts = [];

    for (let i = 0; i < numChunks; i++) {
      setCaptureStatus(
        `Downloading… ${Math.round(((i + 1) / numChunks) * 100)}%`,
      );
      const chunkRes = await postLinuxCmd({
        cmd: `dd if='${gzFile}' bs=${CHUNK_BYTES} skip=${i} count=1 2>/dev/null | base64`,
      });
      const chunkB64 = extractCmdOutput(chunkRes).replace(/\s+/g, "");
      if (!chunkB64) {
        if (i === numChunks - 1) break;
        throw new Error(
          `Download interrupted at chunk ${i + 1}/${numChunks}.`,
        );
      }
      const raw = atob(chunkB64);
      const bytes = new Uint8Array(raw.length);
      for (let j = 0; j < raw.length; j++) bytes[j] = raw.charCodeAt(j);
      binaryParts.push(bytes);
    }

    if (binaryParts.length === 0) {
      throw new Error("No data received from device during download.");
    }

    const totalSize = binaryParts.reduce((sum, part) => sum + part.length, 0);
    const byteArray = new Uint8Array(totalSize);
    let offset = 0;
    for (const part of binaryParts) {
      byteArray.set(part, offset);
      offset += part.length;
    }

    const blob = new Blob([byteArray], { type: "application/gzip" });
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = downloadName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.URL.revokeObjectURL(url);

    await postLinuxCmd({
      cmd: `rm -f '${captureFileName}' '${gzFile}' 2>/dev/null || true`,
    });
  };

  const downloadTextFromDevice = async (cmd, downloadName) => {
    const res = await postLinuxCmd({ cmd });
    const text = extractCmdOutput(res);
    if (!text.trim()) {
      throw new Error("No log data found on server.");
    }
    const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = downloadName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.URL.revokeObjectURL(url);
  };

  const startSlotRecording = async (section, row, pcm, ts, filePrefix) => {
    if (isCapturing || isStopping || isAnySlotRecording()) return;

    const channel = dahdiChannelFromPcmTs(pcm, ts);
    const dateStr = getDateStr();
    const fileName = `${SIGNALING_CAPTURE_DATA_DIR}/${filePrefix}_${pcm}_${ts}_${dateStr}.dat`;
    const logPath = `${SIGNALING_CAPTURE_DATA_DIR}/${filePrefix}.log`;

    try {
      await postLinuxCmd({
        cmd: `pkill -f '${filePrefix}' 2>/dev/null || true`,
      });
      await delay(500);

      const cmd = `sh -c "mkdir -p ${SIGNALING_CAPTURE_DATA_DIR}; rm -f '${fileName}'; touch '${fileName}'; chmod 666 '${fileName}' || true; dahdi_monitor ${channel} -f '${fileName}' > /dev/null 2> '${logPath}' < /dev/null & echo \\$!"`;
      const response = await postLinuxCmd({ cmd });

      if (response?.response === false) {
        const logTailRes = await postLinuxCmd({
          cmd: `tail -n 5 '${logPath}' 2>/dev/null || true`,
        });
        const logTail = extractCmdOutput(logTailRes);
        throw new Error(
          `${response?.message || "Failed to start recording."}${logTail ? ` Log: ${logTail}` : ""}`,
        );
      }

      const pid = extractCmdOutput(response);
      if (!pid || !/^\d+$/.test(pid)) {
        throw new Error(`Failed to start recording. Response: ${pid || "(no output)"}`);
      }

      await delay(400);
      const health = await postLinuxCmd({
        cmd: `ps -p ${pid} >/dev/null 2>&1 && echo RUNNING || echo NOT_RUNNING`,
      });
      if (extractCmdOutput(health) !== "RUNNING") {
        const logTailRes = await postLinuxCmd({
          cmd: `tail -n 3 '${logPath}' 2>/dev/null || true`,
        });
        throw new Error(
          `Recording process not running.${extractCmdOutput(logTailRes) ? ` Log: ${extractCmdOutput(logTailRes)}` : ""}`,
        );
      }

      slotSessionRef.current[section][row] = { pid, fileName, filePrefix };
      setSlotRecordingFlag(section, row, true);
      showToast(
        `${section === "ts" ? "TS" : "E1"} recording started (PCM ${pcm}, TS ${parseTsNumber(ts)}).`,
        "success",
      );
    } catch (error) {
      console.error("Start slot recording error:", error);
      showToast(error.message || "Failed to start recording.", "error");
    }
  };

  const stopSlotRecording = async (section, row) => {
    const session = slotSessionRef.current[section][row];
    if (!session || slotStopping[section][row]) return;

    setSlotStoppingFlag(section, row, true);
    const { pid, fileName, filePrefix } = session;

    try {
      setCaptureStatus("Stopping recording…");
      await postLinuxCmd({
        cmd: `kill -TERM ${pid} 2>/dev/null; pkill -TERM -f '${filePrefix}' 2>/dev/null; sleep 2; kill -KILL ${pid} 2>/dev/null; pkill -KILL -f '${filePrefix}' 2>/dev/null; sync`,
      });

      const downloadName = `${filePrefix}_${getDateStr()}.dat.gz`;
      await downloadGzFileFromDevice(fileName, downloadName);
      setCaptureStatus("");
      showToast("Recording downloaded.", "success");
    } catch (error) {
      console.error("Stop slot recording error:", error);
      setCaptureStatus("");
      showToast(error.message || "Failed to stop/download recording.", "error");
      try {
        await postLinuxCmd({
          cmd: `pkill -KILL -f '${filePrefix}' 2>/dev/null || true`,
        });
      } catch (_) {}
    } finally {
      slotSessionRef.current[section][row] = null;
      setSlotRecordingFlag(section, row, false);
      setSlotStoppingFlag(section, row, false);
    }
  };

  // TS Recording state
  const [ts1Pcm, setTs1Pcm] = useState(SIGNALING_CAPTURE_PCM_OPTIONS[0].value);
  const [ts1Slot, setTs1Slot] = useState(SIGNALING_CAPTURE_TS_OPTIONS[0].value);
  const [ts2Pcm, setTs2Pcm] = useState(SIGNALING_CAPTURE_PCM_OPTIONS[0].value);
  const [ts2Slot, setTs2Slot] = useState(SIGNALING_CAPTURE_TS_OPTIONS[1].value);

  // E1 Two-way Recording state
  const [e1aPcm, setE1aPcm] = useState(SIGNALING_CAPTURE_PCM_OPTIONS[0].value);
  const [e1aSlot, setE1aSlot] = useState(SIGNALING_CAPTURE_TS_OPTIONS[2].value);
  const [e1bPcm, setE1bPcm] = useState(SIGNALING_CAPTURE_PCM_OPTIONS[0].value);
  const [e1bSlot, setE1bSlot] = useState(SIGNALING_CAPTURE_TS_OPTIONS[3].value);

  // Network interfaces state
  useEffect(() => {
    const fetchNetworkInterfaces = async () => {
      try {
        setLoading(true);
        const data = await fetchSystemInfo();

        if (data.success && data.details) {
          const details = data.details;
          let rawInterfaces = [];

          // Extract interfaces from system info
          if (Array.isArray(details.LAN_INTERFACES)) {
            rawInterfaces = details.LAN_INTERFACES;
          } else if (
            details.LAN_INTERFACES &&
            typeof details.LAN_INTERFACES === "object"
          ) {
            rawInterfaces = Object.entries(details.LAN_INTERFACES).map(
              ([name, data]) => ({ name, data }),
            );
          }

          // Filter and process interfaces
          const filteredInterfaces = (rawInterfaces || [])
            .filter((iface) => {
              const name = iface && iface.name ? String(iface.name) : "";
              const lower = name.toLowerCase();
              if (lower === "lo") return false;
              if (lower.startsWith("tap")) return false;
              if (lower.startsWith("tun")) return false;
              if (lower.includes("vpn")) return false;
              return true;
            })
            .map((iface) => {
              const name = iface.name;
              let displayName = name;
              let ipAddress = "";

              // Get IP address from interface data
              if (iface.data) {
                const data = iface.data;
                if (
                  Array.isArray(data["IP Address"]) &&
                  data["IP Address"][0]
                ) {
                  ipAddress = data["IP Address"][0];
                } else if (
                  Array.isArray(data["Ip Address"]) &&
                  data["Ip Address"][0]
                ) {
                  ipAddress = data["Ip Address"][0];
                } else if (
                  Array.isArray(data["ip_address"]) &&
                  data["ip_address"][0]
                ) {
                  ipAddress = data["ip_address"][0];
                }
              }

              // Normalize names
              if (name === "eth0") {
                displayName = "LAN 1";
              } else if (name === "eth1") {
                displayName = "LAN 2";
              }

              return {
                value: name,
                label: `${displayName}${ipAddress ? `(${ipAddress})` : ""}`,
                ip: ipAddress,
              };
            })
            .sort((a, b) => {
              const order = { eth0: 1, eth1: 2 };
              const aOrder = order[a.value] || 99;
              const bOrder = order[b.value] || 99;
              return aOrder - bOrder;
            });

          const options = [
            SIGNALING_CAPTURE_FALLBACK_NETWORK_OPTIONS[0],
            ...filteredInterfaces,
          ];

          setNetworkOptions(options);
        }
      } catch (error) {
        console.error("Error fetching network interfaces:", error);
        // Fallback to default options
        setNetworkOptions(SIGNALING_CAPTURE_FALLBACK_NETWORK_OPTIONS);
      } finally {
        setLoading(false);
      }
    };

    fetchNetworkInterfaces();
  }, []);

  // Handle start data capture
  const handleStartCapture = async () => {
    if (isCapturing || isStopping || isAnySlotRecording()) return;

    try {
      let interfaceName = "";
      if (network === SIGNALING_CAPTURE_DEFAULTS.NETWORK) {
        interfaceName = "any";
      } else if (network === "eth0") {
        interfaceName = "eth0";
      } else if (network === "eth1") {
        interfaceName = "eth1";
      } else {
        interfaceName = network;
      }

      const dateStr = getDateStr();
      const fileName = `${SIGNALING_CAPTURE_DATA_DIR}/${SIGNALING_CAPTURE_DATA_CAPTURE_PATTERN}_${dateStr}.pcap`;
      setCaptureFileName(fileName);

      const dest = syslogDest.trim();
      const filterExpr =
        syslogEnabled && dest
          ? `host ${dest} and (udp port 514 or tcp port 514)`
          : "";
      const tcpdumpCmd = `tcpdump -U -i ${interfaceName} -s 0 -w '${fileName}' ${filterExpr ? `'${filterExpr}'` : ""}`;

      await postLinuxCmd({
        cmd: `pkill -f 'tcpdump.*${SIGNALING_CAPTURE_DATA_CAPTURE_PATTERN}' 2>/dev/null || true`,
      });
      await delay(800);

      const cmd = `sh -c "mkdir -p ${SIGNALING_CAPTURE_DATA_DIR}; rm -f '${fileName}'; touch '${fileName}'; chmod 666 '${fileName}' || true; ${tcpdumpCmd} > /dev/null 2> '${SIGNALING_CAPTURE_LOG_PATH}' < /dev/null & echo \\$!"`;
      const response = await postLinuxCmd({ cmd });

      if (response?.response === false) {
        const logTailRes = await postLinuxCmd({
          cmd: `tail -n 5 ${SIGNALING_CAPTURE_LOG_PATH} 2>/dev/null || true`,
        });
        const logTail = extractCmdOutput(logTailRes);
        showToast(
          `Failed to start capture: ${response?.message || "Unknown error"}${logTail ? ` — ${logTail}` : ""}`,
          "error",
        );
        return;
      }

      const pid = extractCmdOutput(response);
      if (pid && /^\d+$/.test(pid)) {
        await delay(400);
        const health = await postLinuxCmd({
          cmd: `ps -p ${pid} >/dev/null 2>&1 && echo RUNNING || echo NOT_RUNNING`,
        });
        const status = extractCmdOutput(health);
        const logTailRes = await postLinuxCmd({
          cmd: `tail -n 3 ${SIGNALING_CAPTURE_LOG_PATH} 2>/dev/null || true`,
        });
        const logTail = extractCmdOutput(logTailRes);
        if (status !== "RUNNING") {
          showToast(
            `Failed to start capture. tcpdump not running.${logTail ? ` ${logTail}` : ""}`,
            "error",
          );
          return;
        }
        setCaptureProcessId(pid);
        setIsCapturing(true);
        const lanDisplay =
          network === SIGNALING_CAPTURE_DEFAULTS.NETWORK
            ? SIGNALING_CAPTURE_FALLBACK_NETWORK_OPTIONS[0].label
            : network === "eth0"
              ? "LAN 1"
              : network === "eth1"
                ? "LAN 2"
                : network;
        showToast(`Data capture started on ${lanDisplay}.`, "success");
      } else {
        showToast(
          `Failed to start data capture. Response: ${pid || "(no output)"}`,
          "error",
        );
      }
    } catch (error) {
      console.error("Error starting data capture:", error);
      showToast("Error starting data capture. Please try again.", "error");
    }
  };

  // Handle stop data capture
  const handleStopCapture = async () => {
    if (isStopping) return;
    setIsStopping(true);

    try {
      setCaptureStatus("Stopping capture…");
      const pidTerm = captureProcessId
        ? `kill -TERM ${captureProcessId} 2>/dev/null; `
        : "";
      const pidKill = captureProcessId
        ? `kill -KILL ${captureProcessId} 2>/dev/null; `
        : "";
      await postLinuxCmd({
        cmd: `${pidTerm}pkill -TERM -f 'tcpdump.*${SIGNALING_CAPTURE_DATA_CAPTURE_PATTERN}' 2>/dev/null; sleep 2; ${pidKill}pkill -KILL -f 'tcpdump.*${SIGNALING_CAPTURE_DATA_CAPTURE_PATTERN}' 2>/dev/null; sync`,
      });

      const pktRes = await postLinuxCmd({
        cmd: `tcpdump -n -q -r '${captureFileName}' -c 1 2>/dev/null | wc -l`,
      });
      const pktCount = parseInt(extractCmdOutput(pktRes), 10) || 0;
      if (pktCount === 0) {
        showToast(
          "Capture stopped but no packets were recorded. Try All LAN, disable Syslog filter, generate traffic, then capture again.",
          "warning",
        );
        await postLinuxCmd({
          cmd: `rm -f '${captureFileName}' '${captureFileName}.gz' '${SIGNALING_CAPTURE_LOG_PATH}' 2>/dev/null || true`,
        });
        return;
      }

      await downloadGzFileFromDevice(
        captureFileName,
        `${SIGNALING_CAPTURE_DATA_CAPTURE_PATTERN}_${getDateStr()}.pcap.gz`,
      );
      await postLinuxCmd({
        cmd: `rm -f '${SIGNALING_CAPTURE_LOG_PATH}' 2>/dev/null || true`,
      });
      setCaptureStatus("");
      showToast(
        "Download complete. Open the .pcap.gz file in Wireshark.",
        "success",
      );
    } catch (error) {
      console.error("Error stopping data capture:", error);
      setCaptureStatus("");
      try {
        await postLinuxCmd({
          cmd: `pkill -KILL -f 'tcpdump.*${SIGNALING_CAPTURE_DATA_CAPTURE_PATTERN}' 2>/dev/null || true`,
        });
        await postLinuxCmd({
          cmd: `rm -f '${captureFileName}' '${captureFileName}.gz' '${SIGNALING_CAPTURE_LOG_PATH}' 2>/dev/null || true`,
        });
      } catch (_) {}
      showToast(
        error.message || "Error during stop/download. Please try again.",
        "error",
      );
    } finally {
      setIsStopping(false);
      setIsCapturing(false);
      setCaptureProcessId(null);
      setCaptureFileName("");
    }
  };

  const handleCleanData = async () => {
    if (
      isStopping ||
      slotStopping.ts.some(Boolean) ||
      slotStopping.e1.some(Boolean)
    ) {
      return;
    }

    try {
      await postLinuxCmd({
        cmd: `pkill -f 'tcpdump.*${SIGNALING_CAPTURE_DATA_CAPTURE_PATTERN}' 2>/dev/null; pkill -f '${SIGNALING_CAPTURE_TS_RECORD_PREFIX}' 2>/dev/null; pkill -f '${SIGNALING_CAPTURE_E1_RECORD_PREFIX}' 2>/dev/null; pkill -f 'dahdi_monitor' 2>/dev/null; rm -f ${SIGNALING_CAPTURE_DATA_DIR}/${SIGNALING_CAPTURE_DATA_CAPTURE_PATTERN}_* ${SIGNALING_CAPTURE_DATA_DIR}/${SIGNALING_CAPTURE_TS_RECORD_PREFIX}_* ${SIGNALING_CAPTURE_DATA_DIR}/${SIGNALING_CAPTURE_E1_RECORD_PREFIX}_* ${SIGNALING_CAPTURE_DATA_DIR}/${SIGNALING_CAPTURE_TS_RECORD_PREFIX}.log ${SIGNALING_CAPTURE_DATA_DIR}/${SIGNALING_CAPTURE_E1_RECORD_PREFIX}.log ${SIGNALING_CAPTURE_LOG_PATH} 2>/dev/null; sync`,
      });
      setIsCapturing(false);
      setCaptureProcessId(null);
      setCaptureFileName("");
      setCaptureStatus("");
      slotSessionRef.current = emptySlotSessions();
      setSlotRecording({ ts: [false, false], e1: [false, false] });
      showToast("Capture data cleaned.", "success");
    } catch (error) {
      console.error("Clean data error:", error);
      showToast(error.message || "Failed to clean capture data.", "error");
    }
  };

  const handleDownloadLog = async () => {
    try {
      await downloadTextFromDevice(
        `sh -c "for f in ${SIGNALING_CAPTURE_LOG_PATH} ${SIGNALING_CAPTURE_DATA_DIR}/${SIGNALING_CAPTURE_TS_RECORD_PREFIX}.log ${SIGNALING_CAPTURE_DATA_DIR}/${SIGNALING_CAPTURE_E1_RECORD_PREFIX}.log; do if [ -f \\\"\\$f\\\" ]; then echo \\\"=== \\$f ===\\\"; cat \\\"\\$f\\\"; echo; fi; done"`,
        `signaling_capture_log_${getDateStr()}.txt`,
      );
      showToast("Log downloaded.", "success");
    } catch (error) {
      console.error("Download log error:", error);
      showToast(error.message || "No log data found to download.", "warning");
    }
  };

  const dataCaptureLocked =
    isCapturing || isStopping || isAnySlotRecording();

  return (
  <div style={SignalingCapturePageWrapStyle} data-native-scroll>
    <div style={SignalingCapturePageInnerStyle}>
      {toast.msg && (
        <Alert
          severity={toast.type}
          onClose={() => setToast(SIGNALING_CAPTURE_TOAST_DEFAULT)}
          sx={{
            position: "fixed",
            top: 20,
            right: 20,
            zIndex: 9999,
            minWidth: 300,
            boxShadow: 3,
          }}
        >
          {toast.msg}
        </Alert>
      )}

        <div
          style={{
            fontSize: 12,
            color: C.mutedText,
            marginBottom: 16,
            fontWeight: 400,
            display: "flex",
            alignItems: "center",
            gap: 4,
            flexWrap: "wrap",
          }}
        >
          <span>{SIGNALING_CAPTURE_BREADCRUMB[0]}</span>
          <span>&gt;</span>
          <span>{SIGNALING_CAPTURE_BREADCRUMB[1]}</span>
          <span>&gt;</span>
          <span style={{ color: "#1e293b", fontWeight: 600 }}>
            {SIGNALING_CAPTURE_BREADCRUMB[2]}
          </span>
        </div>

        <div style={tableContainerStyle}>
          <div style={blueBarStyle}>
            <span>{SIGNALING_CAPTURE_SECTIONS[0]}</span>
          </div>
          <div className="flex flex-col p-6 gap-6">
            <div className="flex flex-col gap-6">
              <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
                <div className="flex flex-col sm:flex-row sm:items-center gap-4 flex-1">
                  <FieldLabel
                    tooltipKey="networkInterface"
                    className="sm:w-[280px] whitespace-nowrap"
                    style={labelStyle}
                  >
                    {SIGNALING_CAPTURE_LABELS.networkInterface}
                  </FieldLabel>
                  <div className="flex flex-col sm:flex-row gap-4">
                    <select
                      style={{ ...inputStyle, width: "100%", minWidth: 220 }}
                      value={network}
                      onChange={(e) => setNetwork(e.target.value)}
                      disabled={loading || dataCaptureLocked}
                      {...inputInteraction}
                    >
                      {loading ? (
                        <option value="">Loading...</option>
                      ) : (
                        networkOptions.map((opt) => (
                          <option key={opt.value} value={opt.value}>
                            {opt.label}
                          </option>
                        ))
                      )}
                    </select>
                  </div>
                </div>
                <div className="flex flex-col items-end gap-2 lg:ml-4">
                  <div className="flex flex-row flex-wrap gap-4 justify-start lg:justify-end">
                    <Btn
                      variant={SIGNALING_CAPTURE_BUTTON_VARIANTS.PRIMARY}
                      onClick={handleStartCapture}
                      disabled={dataCaptureLocked}
                      style={SIGNALING_CAPTURE_PRIMARY_BUTTON_STYLE}
                    >
                      {SIGNALING_CAPTURE_BUTTON_LABELS.START}
                    </Btn>
                    <Btn
                      variant={SIGNALING_CAPTURE_BUTTON_VARIANTS.CANCEL}
                      onClick={handleStopCapture}
                      disabled={!isCapturing || isStopping}
                      style={SIGNALING_CAPTURE_CANCEL_BUTTON_STYLE}
                    >
                      {isStopping ? SIGNALING_CAPTURE_BUTTON_LABELS.PLEASE_WAIT : SIGNALING_CAPTURE_BUTTON_LABELS.STOP}
                    </Btn>
                  </div>
                  {captureStatus && (
                    <div
                      style={{
                        fontSize: 12,
                        color: "#1d4ed8",
                        fontWeight: 600,
                        background: "#eff6ff",
                        border: "1px solid #bfdbfe",
                        borderRadius: 6,
                        padding: "4px 12px",
                        whiteSpace: "nowrap",
                      }}
                    >
                      {captureStatus}
                    </div>
                  )}
                  {isCapturing && !isStopping && (
                    <div
                      style={{
                        fontSize: 11,
                        color: "#15803d",
                        fontWeight: 600,
                        background: "#f0fdf4",
                        border: "1px solid #bbf7d0",
                        borderRadius: 6,
                        padding: "3px 10px",
                      }}
                    >
                      ● Capturing…
                    </div>
                  )}
                </div>
              </div>

              <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                <FieldLabel
                  tooltipKey="captureSyslog"
                  className="sm:w-[280px] whitespace-nowrap"
                  style={labelStyle}
                >
                  {SIGNALING_CAPTURE_LABELS.captureSyslog}
                </FieldLabel>
                <div className="flex items-center gap-2">
                  <Checkbox
                    size="small"
                    checked={syslogEnabled}
                    onChange={(e) => setSyslogEnabled(e.target.checked)}
                    id="syslog-enable"
                    disabled={dataCaptureLocked || isAnySlotRecording()}
                    sx={{
                      padding: "4px",
                      color: "#64748b",
                      "&.Mui-checked": { color: C.accent },
                      cursor:
                        dataCaptureLocked || isAnySlotRecording()
                          ? "not-allowed"
                          : "pointer",
                    }}
                  />
                  <label
                    htmlFor="syslog-enable"
                    style={{
                      fontSize: 14,
                      color: C.valueText,
                      cursor:
                        dataCaptureLocked || isAnySlotRecording()
                          ? "not-allowed"
                          : "pointer",
                    }}
                  >
                    {SIGNALING_CAPTURE_LABELS.enable}
                  </label>
                </div>
              </div>

              <div className="flex flex-col sm:flex-row sm:items-center gap-4">
                <FieldLabel
                  tooltipKey="syslogDest"
                  className="sm:w-[280px] whitespace-nowrap"
                  style={labelStyle}
                >
                  {SIGNALING_CAPTURE_LABELS.syslogDest}
                </FieldLabel>
                <input
                  type="text"
                  value={syslogDest}
                  onChange={(e) => setSyslogDest(e.target.value)}
                  disabled={!syslogEnabled || dataCaptureLocked || isAnySlotRecording()}
                  style={{
                    ...inputStyle,
                    width: "100%",
                    maxWidth: 220,
                    backgroundColor:
                      !syslogEnabled || dataCaptureLocked || isAnySlotRecording()
                        ? SYSTEM_TOOLS_FILL_BG_READ_ONLY
                        : SYSTEM_TOOLS_FILL_BG_EDITABLE,
                    opacity:
                      !syslogEnabled || dataCaptureLocked || isAnySlotRecording() ? 0.6 : 1,
                    cursor:
                      !syslogEnabled || dataCaptureLocked || isAnySlotRecording()
                        ? "not-allowed"
                        : "text",
                  }}
                  {...inputInteraction}
                />
              </div>

              <p
                style={{
                  margin: "16px 0 0",
                  textAlign: "center",
                  fontSize: 12,
                  color: C.accent,
                  width: "100%",
                  whiteSpace: "nowrap",
                  overflowX: "auto",
                  lineHeight: 1.45,
                }}
              >
                {SIGNALING_CAPTURE_NOTE}
              </p>
            </div>
          </div>
        </div>

        <div style={{ ...tableContainerStyle, marginTop: 20 }}>
          <div style={blueBarStyle}>
            <span>{SIGNALING_CAPTURE_SECTIONS[1]}</span>
          </div>
          <div className="p-6 flex flex-col gap-6">
            {[0, 1].map((i) => (
              <div
                key={i}
                className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 pb-6 last:pb-0"
                style={{
                  borderBottom: i === 0 ? `1px solid ${C.divider}` : "none",
                }}
              >
                <div className="flex flex-col sm:flex-row sm:items-center gap-4 flex-1">
                  <FieldLabel
                    tooltipKey="pcmTs"
                    className="sm:w-[280px] whitespace-nowrap"
                    style={labelStyle}
                  >
                    {SIGNALING_CAPTURE_LABELS.pcmTs}
                  </FieldLabel>
                  <div className="flex flex-col sm:flex-row gap-4">
                    <select
                      style={{ ...inputStyle, minWidth: 100 }}
                      value={i === 0 ? ts1Pcm : ts2Pcm}
                      onChange={(e) =>
                        i === 0
                          ? setTs1Pcm(e.target.value)
                          : setTs2Pcm(e.target.value)
                      }
                      disabled={
                        dataCaptureLocked ||
                        slotRecording.ts[i] ||
                        slotStopping.ts[i]
                      }
                      {...inputInteraction}
                    >
                      {SIGNALING_CAPTURE_PCM_OPTIONS.map((opt) => (
                        <option key={opt.value} value={opt.value}>
                          {opt.label}
                        </option>
                      ))}
                    </select>
                    <select
                      style={{ ...inputStyle, minWidth: 180 }}
                      value={i === 0 ? ts1Slot : ts2Slot}
                      onChange={(e) =>
                        i === 0
                          ? setTs1Slot(e.target.value)
                          : setTs2Slot(e.target.value)
                      }
                      disabled={
                        dataCaptureLocked ||
                        slotRecording.ts[i] ||
                        slotStopping.ts[i]
                      }
                      {...inputInteraction}
                    >
                      {SIGNALING_CAPTURE_TS_OPTIONS.map((opt) => (
                        <option key={opt.value} value={opt.value}>
                          {opt.label}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>
                <div className="flex flex-row flex-wrap gap-4 justify-start lg:justify-end mt-2 lg:mt-0">
                  <Btn
                    variant={SIGNALING_CAPTURE_BUTTON_VARIANTS.PRIMARY}
                    type="button"
                    onClick={() =>
                      startSlotRecording(
                        "ts",
                        i,
                        i === 0 ? ts1Pcm : ts2Pcm,
                        i === 0 ? ts1Slot : ts2Slot,
                        SIGNALING_CAPTURE_TS_RECORD_PREFIX,
                      )
                    }
                    disabled={dataCaptureLocked || isAnySlotRecording()}
                    style={SIGNALING_CAPTURE_PRIMARY_BUTTON_STYLE}
                  >
                    {SIGNALING_CAPTURE_BUTTON_LABELS.START}
                  </Btn>
                  <Btn
                    variant={SIGNALING_CAPTURE_BUTTON_VARIANTS.CANCEL}
                    type="button"
                    onClick={() => stopSlotRecording("ts", i)}
                    disabled={!slotRecording.ts[i] || slotStopping.ts[i]}
                    style={SIGNALING_CAPTURE_CANCEL_BUTTON_STYLE}
                  >
                    {slotStopping.ts[i] ? SIGNALING_CAPTURE_BUTTON_LABELS.PLEASE_WAIT : SIGNALING_CAPTURE_BUTTON_LABELS.STOP}
                  </Btn>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div style={{ ...tableContainerStyle, marginTop: 20 }}>
          <div style={blueBarStyle}>
            <span>{SIGNALING_CAPTURE_SECTIONS[2]}</span>
          </div>
          <div className="p-6 flex flex-col gap-6">
            {[0, 1].map((i) => (
              <div
                key={i}
                className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4 pb-6 last:pb-0"
                style={{
                  borderBottom: i === 0 ? `1px solid ${C.divider}` : "none",
                }}
              >
                <div className="flex flex-col sm:flex-row sm:items-center gap-4 flex-1">
                  <FieldLabel
                    tooltipKey="e1PcmTs"
                    className="sm:w-[280px] whitespace-nowrap"
                    style={labelStyle}
                  >
                    {SIGNALING_CAPTURE_LABELS.pcmTs}
                  </FieldLabel>
                  <div className="flex flex-col sm:flex-row gap-4">
                    <select
                      style={{ ...inputStyle, minWidth: 100 }}
                      value={i === 0 ? e1aPcm : e1bPcm}
                      onChange={(e) =>
                        i === 0
                          ? setE1aPcm(e.target.value)
                          : setE1bPcm(e.target.value)
                      }
                      disabled={
                        dataCaptureLocked ||
                        slotRecording.e1[i] ||
                        slotStopping.e1[i]
                      }
                      {...inputInteraction}
                    >
                      {SIGNALING_CAPTURE_PCM_OPTIONS.map((opt) => (
                        <option key={opt.value} value={opt.value}>
                          {opt.label}
                        </option>
                      ))}
                    </select>
                    <select
                      style={{ ...inputStyle, minWidth: 180 }}
                      value={i === 0 ? e1aSlot : e1bSlot}
                      onChange={(e) =>
                        i === 0
                          ? setE1aSlot(e.target.value)
                          : setE1bSlot(e.target.value)
                      }
                      disabled={
                        dataCaptureLocked ||
                        slotRecording.e1[i] ||
                        slotStopping.e1[i]
                      }
                      {...inputInteraction}
                    >
                      {SIGNALING_CAPTURE_TS_OPTIONS.map((opt) => (
                        <option key={opt.value} value={opt.value}>
                          {opt.label}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>
                <div className="flex flex-row flex-wrap gap-4 justify-start lg:justify-end mt-2 lg:mt-0">
                  <Btn
                    variant={SIGNALING_CAPTURE_BUTTON_VARIANTS.PRIMARY}
                    type="button"
                    onClick={() =>
                      startSlotRecording(
                        "e1",
                        i,
                        i === 0 ? e1aPcm : e1bPcm,
                        i === 0 ? e1aSlot : e1bSlot,
                        SIGNALING_CAPTURE_E1_RECORD_PREFIX,
                      )
                    }
                    disabled={dataCaptureLocked || isAnySlotRecording()}
                    style={SIGNALING_CAPTURE_PRIMARY_BUTTON_STYLE}
                  >
                    {SIGNALING_CAPTURE_BUTTON_LABELS.START}
                  </Btn>
                  <Btn
                    variant={SIGNALING_CAPTURE_BUTTON_VARIANTS.CANCEL}
                    type="button"
                    onClick={() => stopSlotRecording("e1", i)}
                    disabled={!slotRecording.e1[i] || slotStopping.e1[i]}
                    style={SIGNALING_CAPTURE_CANCEL_BUTTON_STYLE}
                  >
                    {slotStopping.e1[i] ? SIGNALING_CAPTURE_BUTTON_LABELS.PLEASE_WAIT : SIGNALING_CAPTURE_BUTTON_LABELS.STOP}
                  </Btn>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div style={signalingCaptureFooterStyle}>
          <Btn
            variant={SIGNALING_CAPTURE_BUTTON_VARIANTS.PRIMARY}
            type="button"
            onClick={handleCleanData}
            disabled={isStopping || slotStopping.ts.some(Boolean) || slotStopping.e1.some(Boolean)}
            style={SIGNALING_CAPTURE_FOOTER_BUTTON_STYLE}
          >
            {SIGNALING_CAPTURE_BUTTON_LABELS.CLEAN}
          </Btn>
          <Btn
            variant={SIGNALING_CAPTURE_BUTTON_VARIANTS.CANCEL}
            type="button"
            onClick={handleDownloadLog}
            style={SIGNALING_CAPTURE_FOOTER_BUTTON_STYLE}
          >
            {SIGNALING_CAPTURE_BUTTON_LABELS.DOWNLOAD}
          </Btn>
        </div>
      </div>
    </div>
  );
};

export default SignalingCapture;

import React, { useEffect, useRef, useState } from "react";
import Tooltip from "@mui/material/Tooltip";
import { InfoOutlined } from "@mui/icons-material"; 
import {
  UPGRADE_TABLE_HEADERS,
  UPGRADE_LABELS,
  UPGRADE_BUTTON_LABELS,
  UPGRADE_BUTTON_VARIANTS,
  UPGRADE_BUTTON_STYLE,
  UPGRADE_BREADCRUMB,
  UPGRADE_STATUS,
  UPGRADE_BUTTON_STATUS,
  UPGRADE_TOOLTIPS,
  UPGRADE_MESSAGES,
  UPGRADE_TIMINGS,
  UPGRADE_FILE,
  UPGRADE_COMMANDS,
  UPGRADE_ROUTES,
  UPGRADE_API,
} from "../../../constants/UpgradeConstants";
import { Alert, CircularProgress } from "@mui/material";
import {
  uploadSoftwareUpdate,
  postLinuxCmd,
  fetchSystemInfo,
} from "../../../api/apiService";
import axiosInstance from "../../../api/axiosInstance";

// ── Color palette (same as UserManage) ────────────────────────────────────────
const C = {
  pageBg: "#f8fafc",
  cardBg: "#ffffff",
  cardBorder: "#d8dde5",
  cardShadow:
  "0 0 14px rgba(0, 0, 0, 0.18), 0 0 5px rgba(0, 0, 0, 0.10)",
  divider: "#e2e6ec",
  labelText: "#3E5475",
  valueText: "#1f2937",
  mutedText: "#94a3b8",
  strongText: "#1e293b",
  accent: "#4A5D75",
  accentDark: "#3a4a5e",
  amber: "#dc2626",
  errorRed: "#dc2626",
  gridHeaderBg: "#F8FAFC",
};

const CARD_RADIUS = 4;
const FIELD_RADIUS = 6;

// ── Local field UI (matches Network.jsx design language) ──
const OUTLINED_BORDER = "#d1d5db";
const OUTLINED_HOVER = "#9ca3af";
const OUTLINED_FOCUS = "#3E5475";
const FOCUS_RING_SHADOW = () => `0 0 0 2px rgba(62, 84, 117, 0.15)`;  


// ── Button Component (same as UserManage) ────────────────────────────────────
const Btn = ({
  children,
  onClick,
  disabled,
  variant = "default",
  style: extraStyle,
  type,
  component,
  startIcon,
}) => {
  const styles = {
    default: {
      background: C.cardBg,
      color: C.valueText,
      border: "1px solid #9ca3af",
    },
    primary: {
      background:
        "linear-gradient(to bottom, #5A6F8F 0%, #3E5475 60%, #2C3E57 100%)",
      color: "#fff",
      border: "1px solid #5A6F8F",
    },
    cancel: {
      background: "#cbd5e1",
      color: "#374151",
      border: "1px solid #cbd5e1",
      boxShadow: "0 1px 2px rgba(15, 23, 42, 0.08)",
    },
    edit: {
      background: "#dcfce7",
      color: "#166534",
      border: "1px solid #bbf7d0",
    },
    delete: {
      background: "#fee2e2",
      color: "#991b1b",
      border: "1px solid #fecaca",
    },
    danger: {
      background: C.errorRed,
      color: C.cardBg,
      border: `0.5px solid ${C.errorRed}`,
    },
  };

  const s = styles[variant] || styles.default;
  const hoverBg =
    {
      primary: "linear-gradient(to bottom, #3E5475 0%, #5A6F8F 100%)",
      cancel: "#b6c2d3",
      danger: "#fca5a5",
      outline: "#e2e8f0",
      error: "#b91c1c",
      default: "#e2e8f0",
    }[variant] || "#e2e8f0";
  const activeBg =
    {
      primary: "linear-gradient(to bottom, #2C3E57 0%, #3E5475 100%)",
      cancel: "#a3b1c2",
      danger: "#f87171",
      outline: "#d1d9e6",
      error: "#991b1b",
      default: "#d1d5db",
    }[variant] || "#d1d5db";
  const baseBg = extraStyle?.background ?? s.background;
  const baseShadow = extraStyle?.boxShadow ?? s.boxShadow ?? "none";

  const clearPressStyle = (el) => {
    el.style.transform = "";
    el.style.boxShadow = baseShadow;
  };

  const applyPressStyle = (el) => {
    el.style.background = activeBg;
    el.style.transform = "translateY(1px) scale(0.98)";
    el.style.boxShadow =
      variant === "primary"
        ? "inset 0 2px 4px rgba(0, 0, 0, 0.25)"
        : variant === "cancel"
          ? "inset 0 2px 4px rgba(15, 23, 42, 0.15)"
          : "inset 0 1px 3px rgba(15, 23, 42, 0.12)";
  };

  const Component = component || "button";
  return (
    <Component
      type={type}
      onClick={onClick}
      disabled={disabled}
      style={{
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        padding: "6px 14px",
        borderRadius: 10,
        fontSize: 13,
        fontWeight: 600,
        cursor: disabled ? "not-allowed" : "pointer",
        opacity: disabled ? 0.6 : 1,
        transition:
          "background 0.15s ease, transform 0.1s ease, box-shadow 0.1s ease",
        height: 36,
        gap: 6,
        whiteSpace: "nowrap",
        ...s,
        ...extraStyle,
      }}
      onMouseEnter={(e) => {
        if (disabled) return;
        e.currentTarget.style.background = hoverBg;
      }}
      onMouseLeave={(e) => {
        if (disabled) return;
        e.currentTarget.style.background = baseBg;
        clearPressStyle(e.currentTarget);
      }}
      onMouseDown={(e) => {
        if (disabled) return;
        applyPressStyle(e.currentTarget);
      }}
      onMouseUp={(e) => {
        if (disabled) return;
        e.currentTarget.style.background = hoverBg;
        clearPressStyle(e.currentTarget);
      }}
    >
      {startIcon && (
        <span style={{ display: "inline-flex" }}>
          {startIcon}
        </span>
      )}
      {children}
    </Component>
  );
};







