      <FormControlLabel
        control={
          <Checkbox
            size="small"
            checked={allChecked}
            indeterminate={someChecked}
            onChange={() => onChange("__ALL__")}
            sx={timeConditionTableCheckboxSx}
          />
        }
        label="All"
        sx={timeConditionModalCheckboxAllLabelSx}
      />
    </div>
  );
};

