import { useEffect, useMemo, useRef, useState } from "react";
import { useMediaQuery } from "@mui/material";
import {
  createCCRoute,
  deleteCCRoute,
  fetchCCRouteExtensions,
  fetchCCRoutes,
  updateCCRoute,
} from "../../../../api/apiService";
import {
  buildCcRoutePayload,
  normalizeCcRoute,
  normalizeCcRouteExtensionsList,
  normalizeCcRouteList,
} from "../utils/CCRouteTransformers";
import { validateCcRouteForm } from "../utils/CCRouteValidators";

const CC_ROUTE_COMPACT_MQ = "(max-width: 768px)";

export function useCCRoutePage() {
  const isCompact = useMediaQuery(CC_ROUTE_COMPACT_MQ);
  const [rows, setRows] = useState([]);
  const [selected, setSelected] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [loading, setLoading] = useState({
    fetch: false,
    save: false,
    delete: false,
    extensions: false,
  });
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const hasLoadedExtensionsRef = useRef(false);

  const [editId, setEditId] = useState(null);
  const [ccIntervalTime, setCcIntervalTime] = useState("10");
  const [through, setThrough] = useState("Auto");
  const [recordKeepTime, setRecordKeepTime] = useState("8 hours");
  const [enabled, setEnabled] = useState("No");
  const [availableExtensions, setAvailableExtensions] = useState([]);
  const [selectedExtensions, setSelectedExtensions] = useState([]);

  const itemsPerPage = 20;
  const [page, setPage] = useState(1);
  const totalPages = Math.max(1, Math.ceil(rows.length / itemsPerPage));
  const pagedRows = rows.slice((page - 1) * itemsPerPage, page * itemsPerPage);

  const [message, setMessage] = useState({ type: "", text: "" });

  const showMessage = (type, text) => {
    setMessage({ type, text });
    setTimeout(() => setMessage({ type: "", text: "" }), 5000);
  };

  const showAlert = (text) => showMessage("error", text);

  const resetForm = () => {
    setEditId(null);
    setCcIntervalTime("10");
    setThrough("Auto");
    setRecordKeepTime("8 hours");
    setEnabled("No");
    setSelectedExtensions([]);
  };

  const loadRows = async () => {
    setLoading((prev) => ({ ...prev, fetch: true }));
    try {
      const res = await fetchCCRoutes();
      setRows(normalizeCcRouteList(res).map(normalizeCcRoute));
    } catch (err) {
      showAlert(err?.message || "Failed to load CC routes.");
      setRows([]);
    } finally {
      setLoading((prev) => ({ ...prev, fetch: false }));
      setIsInitialLoad(false);
    }
  };

  const loadExtensions = async () => {
    setLoading((prev) => ({ ...prev, extensions: true }));
    try {
      const res = await fetchCCRouteExtensions();
      setAvailableExtensions(normalizeCcRouteExtensionsList(res));
      hasLoadedExtensionsRef.current = true;
    } catch (err) {
      showAlert(err?.message || "Failed to load extensions.");
    } finally {
      setLoading((prev) => ({ ...prev, extensions: false }));
    }
  };

  useEffect(() => {
    loadRows();
  }, []);

  const extensionLabelMap = useMemo(() => {
    const map = new Map();
    availableExtensions.forEach((item) =>
      map.set(item.extension, item.label || item.extension),
    );
    return map;
  }, [availableExtensions]);

  const getExtensionLabel = (ext) => extensionLabelMap.get(ext) || ext;

  const allExtensionOptions = useMemo(
    () =>
      availableExtensions.map(({ extension, label }) => ({
        value: extension,
        label,
      })),
    [availableExtensions],
  );

  const handleOpenAddModal = async () => {
    resetForm();
    setShowModal(true);
    if (!hasLoadedExtensionsRef.current) await loadExtensions();
  };

  const handleOpenEditModal = async (row) => {
    setEditId(row.id);
    setCcIntervalTime(row.ccIntervalTime);
    setThrough(row.through);
    setRecordKeepTime(row.recordKeepTime);
    setEnabled(row.enabled);
    setSelectedExtensions(
      Array.isArray(row.memberExtensions) ? row.memberExtensions : [],
    );
    setShowModal(true);
    if (!hasLoadedExtensionsRef.current) await loadExtensions();
  };

  const handleCloseModal = () => {
    if (!loading.save) setShowModal(false);
  };

  const handleSelectRow = (idx) => {
    setSelected((prev) =>
      prev.includes(idx) ? prev.filter((i) => i !== idx) : [...prev, idx],
    );
  };

  const pageIndices = pagedRows.map((_, i) => (page - 1) * itemsPerPage + i);
  const allPageSelected =
    pageIndices.length > 0 && pageIndices.every((i) => selected.includes(i));
  const somePageSelected =
    pageIndices.some((i) => selected.includes(i)) && !allPageSelected;

  const handleToggleAll = () => {
    if (allPageSelected)
      setSelected((prev) => prev.filter((i) => !pageIndices.includes(i)));
    else setSelected((prev) => Array.from(new Set([...prev, ...pageIndices])));
  };

  const handleDelete = async () => {
    if (selected.length === 0) return;
    if (
      !window.confirm(
        `Are you sure you want to delete ${selected.length} record(s)?`,
      )
    )
      return;
    setLoading((prev) => ({ ...prev, delete: true }));
    try {
      const ids = selected.map((i) => rows[i]?.id).filter(Boolean);
      await Promise.all(ids.map((id) => deleteCCRoute(id)));
      setSelected([]);
      await loadRows();
      showMessage("success", `Deleted ${ids.length} item(s).`);
    } catch (err) {
      showAlert(err?.message || "Failed to delete CC route.");
    } finally {
      setLoading((prev) => ({ ...prev, delete: false }));
    }
  };

  const handleSave = async () => {
    const validationError = validateCcRouteForm({ selectedExtensions });
    if (validationError) {
      showAlert(validationError);
      return;
    }
    const apiPayload = buildCcRoutePayload({
      ccIntervalTime,
      through,
      recordKeepTime,
      enabled,
      selectedExtensions,
    });
    setLoading((prev) => ({ ...prev, save: true }));
    try {
      if (editId != null) {
        await updateCCRoute({ id: editId, ...apiPayload });
        showMessage("success", "CC route updated.");
      } else {
        await createCCRoute(apiPayload);
        showMessage("success", "CC route created.");
      }
      await loadRows();
      handleCloseModal();
    } catch (err) {
      showAlert(err?.message || "Failed to save CC route.");
    } finally {
      setLoading((prev) => ({ ...prev, save: false }));
    }
  };

  return {
    isCompact,
    rows,
    selected,
    showModal,
    loading,
    isInitialLoad,
    editId,
    ccIntervalTime,
    setCcIntervalTime,
    through,
    setThrough,
    recordKeepTime,
    setRecordKeepTime,
    enabled,
    setEnabled,
    selectedExtensions,
    setSelectedExtensions,
    itemsPerPage,
    page,
    setPage,
    totalPages,
    pagedRows,
    message,
    setMessage,
    allExtensionOptions,
    allPageSelected,
    somePageSelected,
    getExtensionLabel,
    handleOpenAddModal,
    handleOpenEditModal,
    handleCloseModal,
    handleSelectRow,
    handleToggleAll,
    handleDelete,
    handleSave,
  };
}

import { useEffect, useMemo, useRef, useState } from "react";
import { useMediaQuery } from "@mui/material";
import {
  createInboundRoute,
  deleteInboundRoute,
  listInboundRoutes,
  listIvrDestinations,
  listSipRegistrations,
  updateInboundRoute,
} from "../../../../api/apiService";
import {
  buildInboundRouteApiPayload,
  getInboundDestinationChoices,
  mapInboundRouteFromApi,
  mapSipRegistrationsToTrunkOptions,
  normalizeInboundRouteList,
} from "../utils/InboundRoutesTransformers";
import {
  inboundRouteNeedsDestinationTarget,
  validateInboundRouteForm,
} from "../utils/InboundRoutesValidators";

const INBOUND_ROUTE_COMPACT_MQ = "(max-width: 768px)";

export function useInboundRoutesPage() {
  const isCompact = useMediaQuery(INBOUND_ROUTE_COMPACT_MQ);
  const [rows, setRows] = useState([]);
  const [selected, setSelected] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [loading, setLoading] = useState({
    list: false,
    save: false,
    delete: false,
    trunks: false,
  });
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const hasLoadedTrunksRef = useRef(false);

  const [editId, setEditId] = useState(null);
  const [name, setName] = useState("");
  const [didPattern, setDidPattern] = useState("");
  const [callerIdPattern, setCallerIdPattern] = useState("");
  const [distinctiveRingTone, setDistinctiveRingTone] = useState("");
  const [enableT38, setEnableT38] = useState("No");
  const [enableTimeCondition, setEnableTimeCondition] = useState("No");
  const [destination, setDestination] = useState("");
  const [enabled, setEnabled] = useState("Yes");
  const [priority, setPriority] = useState("102");
  const [enableMobilityExtension, setEnableMobilityExtension] = useState("No");
  const [sendRingTone, setSendRingTone] = useState("Remote");
  const [destinationTarget, setDestinationTarget] = useState("");
  const [extensionRange, setExtensionRange] = useState("");

  const [destinations, setDestinations] = useState({});
  const hasLoadedDestinationDataRef = useRef(false);

  const [availableTrunks, setAvailableTrunks] = useState([]);
  const [selectedTrunks, setSelectedTrunks] = useState([]);

  const itemsPerPage = 20;
  const [page, setPage] = useState(1);
  const totalPages = Math.max(1, Math.ceil(rows.length / itemsPerPage));
  const pagedRows = rows.slice((page - 1) * itemsPerPage, page * itemsPerPage);

  useEffect(() => {
    setPage((current) =>
      Math.min(
        Math.max(1, current),
        Math.max(1, Math.ceil(rows.length / itemsPerPage)),
      ),
    );
  }, [rows]);

  const [message, setMessage] = useState({ type: "", text: "" });
  const showMessage = (type, text) => {
    setMessage({ type, text });
    setTimeout(() => setMessage({ type: "", text: "" }), 5000);
  };
  const showAlert = (text) => showMessage("error", text);

  const fetchInboundRoutes = async () => {
    setLoading((prev) => ({ ...prev, list: true }));
    try {
      const res = await listInboundRoutes();
      if (!res?.response) {
        showAlert(res?.message || "Failed to load inbound routes.");
        setRows([]);
        return;
      }
      setRows(
        normalizeInboundRouteList(res).map((row) =>
          mapInboundRouteFromApi(row, []),
        ),
      );
    } catch (err) {
      showAlert(err?.message || "Failed to load inbound routes.");
      setRows([]);
    } finally {
      setLoading((prev) => ({ ...prev, list: false }));
      setIsInitialLoad(false);
    }
  };

  useEffect(() => {
    fetchInboundRoutes();
  }, []);

  const loadTrunks = async () => {
    setLoading((prev) => ({ ...prev, trunks: true }));
    try {
      const res = await listSipRegistrations();
      setAvailableTrunks(mapSipRegistrationsToTrunkOptions(res));
      hasLoadedTrunksRef.current = true;
    } catch (err) {
      showAlert(err?.message || "Failed to load trunks.");
      setAvailableTrunks([]);
    } finally {
      setLoading((prev) => ({ ...prev, trunks: false }));
    }
  };

  const loadDestinationData = async () => {
    try {
      const res = await listIvrDestinations();
      if (res?.response && res?.message && typeof res.message === "object") {
        setDestinations(res.message);
      }
      hasLoadedDestinationDataRef.current = true;
    } catch {
      setDestinations({});
    }
  };

  const destinationChoices = getInboundDestinationChoices(
    destination,
    destinations,
  );
  const needsDestinationTarget =
    inboundRouteNeedsDestinationTarget(destination);

  const resetForm = () => {
    setEditId(null);
    setName("");
    setDidPattern("");
    setCallerIdPattern("");
    setDistinctiveRingTone("");
    setEnableT38("No");
    setEnableTimeCondition("No");
    setDestination("");
    setEnabled("Yes");
    setPriority("102");
    setEnableMobilityExtension("No");
    setSendRingTone("Remote");
    setDestinationTarget("");
    setExtensionRange("");
    setSelectedTrunks([]);
  };

  const handleOpenAddModal = async () => {
    resetForm();
    setShowModal(true);
    const loaders = [];
    if (!hasLoadedTrunksRef.current) loaders.push(loadTrunks());
    if (!hasLoadedDestinationDataRef.current)
      loaders.push(loadDestinationData());
    if (loaders.length > 0) await Promise.allSettled(loaders);
  };

  const handleOpenEditModal = async (row) => {
    setEditId(row.id);
    setName(row.name || "");
    setDidPattern(row.didPattern || "");
    setCallerIdPattern(row.callerIdPattern || "");
    setDistinctiveRingTone(row.distinctiveRingTone || "");
    setEnableT38(row.enableT38 || "No");
    setEnableTimeCondition(row.enableTimeCondition || "No");
    setDestination(row.destination || "Call Queue");
    setEnabled(row.enabled || "Yes");
    setPriority(row.priority || "102");
    setEnableMobilityExtension(row.enableMobilityExtension || "No");
    setSendRingTone(row.sendRingTone || "Remote");
    setDestinationTarget(row.destinationTarget || "");
    setExtensionRange(row.extensionRange || "");
    setSelectedTrunks(Array.isArray(row.memberTrunks) ? row.memberTrunks : []);
    setShowModal(true);
    const loaders = [];
    if (!hasLoadedTrunksRef.current) loaders.push(loadTrunks());
    if (!hasLoadedDestinationDataRef.current)
      loaders.push(loadDestinationData());
    if (loaders.length > 0) await Promise.allSettled(loaders);
  };

  const handleCloseModal = () => {
    if (loading.save) return;
    setShowModal(false);
    resetForm();
  };

  const trunkLabelMap = useMemo(() => {
    const map = new Map();
    availableTrunks.forEach((t) => {
      map.set(t.id, t.label);
    });
    return map;
  }, [availableTrunks]);

  const getTrunkLabel = (id) => trunkLabelMap.get(id) || id;

  const allTrunkOptions = useMemo(
    () =>
      availableTrunks.map(({ id, label }) => ({
        value: id,
        label: label || id,
      })),
    [availableTrunks],
  );

  const handleSelectRow = (idx) => {
    setSelected((prev) =>
      prev.includes(idx) ? prev.filter((i) => i !== idx) : [...prev, idx],
    );
  };

  const pageIndices = pagedRows.map((_, i) => (page - 1) * itemsPerPage + i);
  const allPageSelected =
    pageIndices.length > 0 && pageIndices.every((i) => selected.includes(i));
  const somePageSelected =
    pageIndices.some((i) => selected.includes(i)) && !allPageSelected;
  const handleToggleAll = () => {
    if (allPageSelected) {
      setSelected((prev) => prev.filter((i) => !pageIndices.includes(i)));
    } else {
      setSelected((prev) => Array.from(new Set([...prev, ...pageIndices])));
    }
  };

  const handleDelete = async () => {
    if (selected.length === 0) {
      showAlert("Please select at least one row to delete.");
      return;
    }
    if (
      !window.confirm(
        `Are you sure you want to delete ${selected.length} record(s)?`,
      )
    )
      return;
    setLoading((prev) => ({ ...prev, delete: true }));
    try {
      const idsToDelete = selected
        .map((idx) => rows[idx]?.id)
        .filter((id) => id != null);
      const results = await Promise.all(
        idsToDelete.map((id) => deleteInboundRoute(id)),
      );
      const failed = results.find((res) => !res?.response);
      if (failed) {
        showAlert(failed?.message || "Failed to delete one or more routes.");
      } else {
        showMessage("success", "Inbound route(s) deleted successfully.");
      }
      await fetchInboundRoutes();
      setSelected([]);
      setPage(1);
    } catch (err) {
      showAlert(err?.message || "Failed to delete route(s).");
    } finally {
      setLoading((prev) => ({ ...prev, delete: false }));
    }
  };

  const handleSave = async () => {
    const validationError = validateInboundRouteForm({
      name,
      destination,
      priority,
      extensionRange,
      destinationTarget,
      destinationChoices,
    });
    if (validationError) {
      showAlert(validationError);
      return;
    }

    const apiPayload = buildInboundRouteApiPayload({
      name: name.trim(),
      didPattern,
      callerIdPattern,
      distinctiveRingTone,
      enableT38,
      enableTimeCondition,
      destination,
      destinationTarget:
        destination === "Extension_Range" ? "" : destinationTarget,
      extensionRange:
        destination === "Extension_Range" ? extensionRange.trim() : "",
      enabled,
      priority,
      enableMobilityExtension,
      sendRingTone,
      memberTrunks: [...selectedTrunks],
    });

    setLoading((prev) => ({ ...prev, save: true }));
    try {
      const response =
        editId != null
          ? await updateInboundRoute(editId, apiPayload)
          : await createInboundRoute(apiPayload);
      if (!response?.response) {
        showAlert(response?.message || "Failed to save inbound route.");
        return;
      }
      showMessage(
        "success",
        editId != null
          ? "Inbound route updated successfully."
          : "Inbound route created successfully.",
      );
      await fetchInboundRoutes();
      handleCloseModal();
    } catch (err) {
      showAlert(err?.message || "Failed to save inbound route.");
    } finally {
      setLoading((prev) => ({ ...prev, save: false }));
    }
  };

  return {
    isCompact,
    rows,
    selected,
    showModal,
    loading,
    isInitialLoad,
    editId,
    name,
    setName,
    didPattern,
    setDidPattern,
    callerIdPattern,
    setCallerIdPattern,
    distinctiveRingTone,
    setDistinctiveRingTone,
    enableT38,
    setEnableT38,
    enableTimeCondition,
    setEnableTimeCondition,
    destination,
    setDestination,
    enabled,
    setEnabled,
    priority,
    setPriority,
    enableMobilityExtension,
    setEnableMobilityExtension,
    sendRingTone,
    setSendRingTone,
    destinationTarget,
    setDestinationTarget,
    extensionRange,
    setExtensionRange,
    selectedTrunks,
    setSelectedTrunks,
    itemsPerPage,
    page,
    setPage,
    totalPages,
    pagedRows,
    message,
    setMessage,
    destinationChoices,
    needsDestinationTarget,
    allTrunkOptions,
    allPageSelected,
    somePageSelected,
    getTrunkLabel,
    handleOpenAddModal,
    handleOpenEditModal,
    handleCloseModal,
    handleSelectRow,
    handleToggleAll,
    handleDelete,
    handleSave,
  };
}

import { useEffect, useMemo, useRef, useState } from "react";
import { useMediaQuery } from "@mui/material";
import {
  createOutboundRestriction,
  deleteOutboundRestriction,
  listIvrDestinations,
  listOutboundRestrictions,
  listOutboundRouteExtensions,
  updateOutboundRestriction,
} from "../../../../api/apiService";
import {
  buildOutboundRestrictionApiPayload,
  mapDestinationExtensionsFromApi,
  mapOutboundRouteExtensionsFromApi,
  mapRestrictionFromApi,
  normalizeOutboundRestrictionList,
} from "../utils/OutboundRestrictionsTransformers";
import { validateOutboundRestrictionForm } from "../utils/OutboundRestrictionsValidators";

const OUTBOUND_RESTRICTION_COMPACT_MQ = "(max-width: 768px)";

export function useOutboundRestrictionsPage() {
  const isCompact = useMediaQuery(OUTBOUND_RESTRICTION_COMPACT_MQ);
  const [rows, setRows] = useState([]);
  const [selected, setSelected] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [loading, setLoading] = useState({
    list: false,
    save: false,
    delete: false,
    extensions: false,
  });
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const hasLoadedExtensionsRef = useRef(false);

  const [editId, setEditId] = useState(null);
  const [name, setName] = useState("");
  const [timeLimit, setTimeLimit] = useState("");
  const [callsLimit, setCallsLimit] = useState("");
  const [autoCancelRestriction, setAutoCancelRestriction] = useState("No");
  const [enabled, setEnabled] = useState("Yes");
  const [availableExtensions, setAvailableExtensions] = useState([]);
  const [memberExtensions, setMemberExtensions] = useState([]);

  const [searchQuery, setSearchQuery] = useState("");
  const [searchFocused, setSearchFocused] = useState(false);

  const itemsPerPage = 20;
  const [page, setPage] = useState(1);

  const [message, setMessage] = useState({ type: "", text: "" });
  const showMessage = (type, text) => {
    setMessage({ type, text });
    setTimeout(() => setMessage({ type: "", text: "" }), 5000);
  };
  const showAlert = (text) => showMessage("error", text);

  const filteredRows = useMemo(() => {
    if (!searchQuery.trim()) return rows;
    const q = searchQuery.toLowerCase();
    return rows.filter((row) => {
      const extStr = (row.memberExtensions || []).join(" ").toLowerCase();
      return (
        (row.name || "").toLowerCase().includes(q) ||
        (row.timeLimit || "").toLowerCase().includes(q) ||
        (row.callsLimit || "").toLowerCase().includes(q) ||
        (row.autoCancelRestriction || "").toLowerCase().includes(q) ||
        (row.enabled || "").toLowerCase().includes(q) ||
        extStr.includes(q)
      );
    });
  }, [rows, searchQuery]);

  const loadDestinations = async () => {
    try {
      const data = await listIvrDestinations();
      setAvailableExtensions(mapDestinationExtensionsFromApi(data));
    } catch (err) {
      console.error(err);
    }
  };

  const totalPages = Math.max(1, Math.ceil(filteredRows.length / itemsPerPage));
  const pagedRows = filteredRows.slice(
    (page - 1) * itemsPerPage,
    page * itemsPerPage,
  );

  useEffect(() => {
    setPage((current) =>
      Math.min(
        Math.max(1, current),
        Math.max(1, Math.ceil(filteredRows.length / itemsPerPage)),
      ),
    );
  }, [filteredRows.length]);

  const fetchRestrictions = async () => {
    setLoading((prev) => ({ ...prev, list: true }));
    try {
      const res = await listOutboundRestrictions();
      if (!res?.response) {
        showAlert(res?.message || "Failed to load outbound restrictions.");
        setRows([]);
        return;
      }
      setRows(normalizeOutboundRestrictionList(res).map(mapRestrictionFromApi));
    } catch (err) {
      showAlert(err?.message || "Failed to load outbound restrictions.");
      setRows([]);
    } finally {
      setLoading((prev) => ({ ...prev, list: false }));
      setIsInitialLoad(false);
    }
  };

  const loadExtensions = async () => {
    setLoading((prev) => ({ ...prev, extensions: true }));
    try {
      const res = await listOutboundRouteExtensions();
      setAvailableExtensions(mapOutboundRouteExtensionsFromApi(res));
      hasLoadedExtensionsRef.current = true;
    } catch (err) {
      showAlert(err?.message || "Failed to load extensions.");
      setAvailableExtensions([]);
    } finally {
      setLoading((prev) => ({ ...prev, extensions: false }));
    }
  };

  useEffect(() => {
    fetchRestrictions();
    loadDestinations();
  }, []);

  const extensionLabelMap = useMemo(() => {
    const map = new Map();
    availableExtensions.forEach((item) =>
      map.set(item.extension, item.label || item.extension),
    );
    return map;
  }, [availableExtensions]);

  const getExtensionLabel = (ext) => extensionLabelMap.get(ext) || ext;

  const allExtensionOptions = useMemo(
    () =>
      availableExtensions.map(({ extension, label }) => ({
        value: extension,
        label: label || extension,
      })),
    [availableExtensions],
  );

  const resetForm = () => {
    setEditId(null);
    setName("");
    setTimeLimit("");
    setCallsLimit("");
    setAutoCancelRestriction("No");
    setEnabled("Yes");
    setMemberExtensions([]);
  };

  const handleOpenAddModal = async () => {
    resetForm();
    setShowModal(true);
    // if (!hasLoadedExtensionsRef.current) await loadExtensions();
  };

  const handleOpenEditModal = async (row) => {
    setEditId(row.id);
    setName(row.name || "");
    setTimeLimit(row.timeLimit || "");
    setCallsLimit(row.callsLimit || "");
    setAutoCancelRestriction(row.autoCancelRestriction || "No");
    setEnabled(row.enabled || "Yes");
    setMemberExtensions(
      Array.isArray(row.memberExtensions) ? row.memberExtensions : [],
    );
    setShowModal(true);
    // if (!hasLoadedExtensionsRef.current) await loadExtensions();
  };

  const handleCloseModal = () => {
    if (loading.save) return;
    setShowModal(false);
    resetForm();
  };

  const handleSelectRow = (idx) => {
    setSelected((prev) =>
      prev.includes(idx) ? prev.filter((i) => i !== idx) : [...prev, idx],
    );
  };

  const pageIndices = pagedRows.map((_, i) => (page - 1) * itemsPerPage + i);
  const allPageSelected =
    pageIndices.length > 0 && pageIndices.every((i) => selected.includes(i));
  const somePageSelected =
    pageIndices.some((i) => selected.includes(i)) && !allPageSelected;

  const handleToggleAll = () => {
    if (allPageSelected) {
      setSelected((prev) => prev.filter((i) => !pageIndices.includes(i)));
    } else {
      setSelected((prev) => Array.from(new Set([...prev, ...pageIndices])));
    }
  };

  const handleDelete = async () => {
    if (selected.length === 0) {
      showAlert("Please select at least one row to delete.");
      return;
    }
    if (
      !window.confirm(
        `Are you sure you want to delete ${selected.length} record(s)?`,
      )
    ) {
      return;
    }
    setLoading((prev) => ({ ...prev, delete: true }));
    try {
      const idsToDelete = selected
        .map((idx) => filteredRows[idx]?.id)
        .filter((id) => id != null);
      const results = await Promise.all(
        idsToDelete.map((id) => deleteOutboundRestriction(id)),
      );
      const failed = results.find((res) => !res?.response);
      if (failed) {
        showAlert(failed?.message || "Failed to delete one or more records.");
      } else {
        showMessage("success", "Outbound restriction(s) deleted successfully.");
      }
      await fetchRestrictions();
      setSelected([]);
      setPage(1);
    } catch (err) {
      showAlert(err?.message || "Failed to delete record(s).");
    } finally {
      setLoading((prev) => ({ ...prev, delete: false }));
    }
  };

  const handleSave = async () => {
    const validationError = validateOutboundRestrictionForm({
      name,
      memberExtensions,
    });
    if (validationError) {
      showAlert(validationError);
      return;
    }

    const apiPayload = buildOutboundRestrictionApiPayload({
      name,
      timeLimit,
      callsLimit,
      autoCancelRestriction,
      memberExtensions,
      enabled,
    });

    setLoading((prev) => ({ ...prev, save: true }));
    try {
      const response =
        editId != null
          ? await updateOutboundRestriction(editId, apiPayload)
          : await createOutboundRestriction(apiPayload);
      if (!response?.response) {
        showAlert(response?.message || "Failed to save outbound restriction.");
        return;
      }
      showMessage(
        "success",
        editId != null
          ? "Outbound restriction updated successfully."
          : "Outbound restriction created successfully.",
      );
      await fetchRestrictions();
      handleCloseModal();
    } catch (err) {
      showAlert(err?.message || "Failed to save outbound restriction.");
    } finally {
      setLoading((prev) => ({ ...prev, save: false }));
    }
  };

  const dataEmpty = !isInitialLoad && rows.length === 0;
  const searchEmpty =
    !isInitialLoad && rows.length > 0 && filteredRows.length === 0;

  return {
    isCompact,
    rows,
    selected,
    showModal,
    loading,
    isInitialLoad,
    editId,
    name,
    setName,
    timeLimit,
    setTimeLimit,
    callsLimit,
    setCallsLimit,
    autoCancelRestriction,
    setAutoCancelRestriction,
    enabled,
    setEnabled,
    memberExtensions,
    setMemberExtensions,
    searchQuery,
    setSearchQuery,
    searchFocused,
    setSearchFocused,
    itemsPerPage,
    page,
    setPage,
    totalPages,
    pagedRows,
    filteredRows,
    message,
    setMessage,
    allExtensionOptions,
    allPageSelected,
    somePageSelected,
    getExtensionLabel,
    handleOpenAddModal,
    handleOpenEditModal,
    handleCloseModal,
    handleSelectRow,
    handleToggleAll,
    handleDelete,
    handleSave,
    dataEmpty,
    searchEmpty,
  };
}

import { useEffect, useMemo, useRef, useState } from "react";
import { useMediaQuery } from "@mui/material";
import { createOutboundRoute, deleteOutboundRoute, fetchSipAccounts, listOutboundRoutes, listSipRegistrations, updateOutboundRoute } from "../../../../api/apiService";
import { OUTBOUND_ROUTE_DEFAULT_CALLER_CONVERSION, OUTBOUND_ROUTE_DEFAULT_DIAL_PATTERN } from "../../../../constants/OutboundRouteConstants";
import { buildOutboundRoutePayload, mapOutboundRouteFromApi, normalizeOutboundRouteList } from "../utils/OutboundRoutesTransformers";
import { validateOutboundRouteForm } from "../utils/OutboundRoutesValidators";

const OUTBOUND_ROUTE_COMPACT_MQ = "(max-width: 768px)";

export function useOutboundRoutesPage() {
  const isCompact = useMediaQuery(OUTBOUND_ROUTE_COMPACT_MQ);
  const [rows, setRows] = useState([]);
  const [selected, setSelected] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [loading, setLoading] = useState({
    list: false,
    save: false,
    delete: false,
    members: false,
    trunks: false,
  });
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const hasLoadedMembersRef = useRef(false);
  const hasLoadedTrunksRef = useRef(false);

  const [editId, setEditId] = useState(null);
  const [name, setName] = useState("");
  const [priority, setPriority] = useState("");
  const [description, setDescription] = useState("");
  const [nextRoute, setNextRoute] = useState(false);
  const [enabled, setEnabled] = useState("Yes");
  const [passwordType, setPasswordType] = useState("None");
  const [singlePin, setSinglePin] = useState("");
  const [rememoryHunt, setRememoryHunt] = useState("No");
  const [timeConditions, setTimeConditions] = useState([]);
  const [dialPatterns, setDialPatterns] = useState([
    { ...OUTBOUND_ROUTE_DEFAULT_DIAL_PATTERN },
  ]);
  const [callerConversion, setCallerConversion] = useState({
    ...OUTBOUND_ROUTE_DEFAULT_CALLER_CONVERSION,
  });

  const [availableExtensions, setAvailableExtensions] = useState([]);
  const [memberExtensions, setMemberExtensions] = useState([]);

  const [availableTrunks, setAvailableTrunks] = useState([]);
  const [memberTrunks, setMemberTrunks] = useState([]);

  const itemsPerPage = 20;
  const [page, setPage] = useState(1);
  const totalPages = Math.max(1, Math.ceil(rows.length / itemsPerPage));
  const pagedRows = rows.slice((page - 1) * itemsPerPage, page * itemsPerPage);

  useEffect(() => {
    setPage((current) =>
      Math.min(
        Math.max(1, current),
        Math.max(1, Math.ceil(rows.length / itemsPerPage)),
      ),
    );
  }, [rows]);

  const [message, setMessage] = useState({ type: "", text: "" });
  const showMessage = (type, text) => {
    setMessage({ type, text });
    setTimeout(() => setMessage({ type: "", text: "" }), 5000);
  };
  const showAlert = (text) => showMessage("error", text);

  const fetchOutboundRoutes = async () => {
    setLoading((prev) => ({ ...prev, list: true }));
    try {
      const res = await listOutboundRoutes();
      if (!res?.response) {
        showAlert(res?.message || "Failed to load outbound routes.");
        setRows([]);
        return;
      }
      setRows(normalizeOutboundRouteList(res).map(mapOutboundRouteFromApi));
    } catch (err) {
      showAlert(err?.message || "Failed to load outbound routes.");
      setRows([]);
    } finally {
      setLoading((prev) => ({ ...prev, list: false }));
      setIsInitialLoad(false);
    }
  };

  const loadExtensions = async () => {
    setLoading((prev) => ({ ...prev, members: true }));
    try {
      const res = await fetchSipAccounts();
      const list = normalizeOutboundRouteList(res)
        .map((item) => {
          const ext = item?.extension ?? item?.ext ?? item?.id ?? item;
          const display = item?.display_name ?? item?.name ?? "";
          return {
            id: String(ext ?? ""),
            label: display
              ? `${String(ext ?? "")}-${display}`
              : String(ext ?? ""),
          };
        })
        .filter((item) => item.id);
      setAvailableExtensions(list);
      hasLoadedMembersRef.current = true;
    } catch (err) {
      showAlert(err?.message || "Failed to load extension list.");
      setAvailableExtensions([]);
    } finally {
      setLoading((prev) => ({ ...prev, members: false }));
    }
  };

  const loadTrunks = async () => {
    setLoading((prev) => ({ ...prev, trunks: true }));
    try {
      const res = await listSipRegistrations();
      const raw = res?.message ?? res?.data ?? res;
      const list = Array.isArray(raw) ? raw : [];
      const trunks = list
        .map((t) => {
          const id = t?.trunkId || t?.trunk_id || t?.id || t;
          const name = t?.name || t?.trunk_name || "";
          const domain =
            t?.domain_id || t?.domain || t?.sip_server || t?.host || "";
          const label =
            name && domain
              ? `${name} : ${domain}`
              : name
                ? name
                : domain
                  ? domain
                  : String(id || "");
          return { id: String(id), label };
        })
        .filter((t) => t.id);
      setAvailableTrunks(trunks);
      hasLoadedTrunksRef.current = true;
    } catch (err) {
      showAlert(err?.message || "Failed to load trunk list.");
      setAvailableTrunks([]);
    } finally {
      setLoading((prev) => ({ ...prev, trunks: false }));
    }
  };

  const extensionLabelMap = useMemo(() => {
    const map = new Map();
    availableExtensions.forEach((item) => map.set(item.id, item.label));
    return map;
  }, [availableExtensions]);

  const trunkLabelMap = useMemo(() => {
    const map = new Map();
    availableTrunks.forEach((item) => map.set(item.id, item.label));
    return map;
  }, [availableTrunks]);

  const getExtensionLabel = (id) => extensionLabelMap.get(id) || id;
  const getTrunkLabel = (id) => trunkLabelMap.get(id) || id;

  const allExtensionOptions = useMemo(
    () => availableExtensions.map(({ id, label }) => ({ value: id, label: label || id })),
    [availableExtensions],
  );
  const allTrunkOptions = useMemo(
    () => availableTrunks.map(({ id, label }) => ({ value: id, label: label || id })),
    [availableTrunks],
  );

  const resetForm = () => {
    setEditId(null);
    setName("");
    setPriority("");
    setDescription("");
    setNextRoute(false);
    setEnabled("Yes");
    setPasswordType("None");
    setSinglePin("");
    setRememoryHunt("No");
    setTimeConditions([]);
    setDialPatterns([{ ...OUTBOUND_ROUTE_DEFAULT_DIAL_PATTERN, pattern: "^\\d*$" }]);
    setCallerConversion({ ...OUTBOUND_ROUTE_DEFAULT_CALLER_CONVERSION });
    setMemberExtensions([]);
    setMemberTrunks([]);
  };

  const ensureFormListsLoaded = async () => {
    const promises = [];
    if (!hasLoadedMembersRef.current) promises.push(loadExtensions());
    if (!hasLoadedTrunksRef.current) promises.push(loadTrunks());
    if (promises.length > 0) await Promise.allSettled(promises);
  };

  useEffect(() => {
    const load = async () => {
      await Promise.allSettled([loadExtensions(), loadTrunks()]);
      await fetchOutboundRoutes();
    };
    load();
  }, []);

  const handleOpenAddModal = async () => {
    resetForm();
    setShowModal(true);
    await ensureFormListsLoaded();
  };

  const handleOpenEditModal = async (row) => {
    setEditId(row.id);
    setName(row.name || "");
    setPriority(row.priority || "");
    setDescription(row.description || "");
    setNextRoute(!!row.nextRoute);
    setEnabled(row.enabled || "Yes");
    setPasswordType(row.passwordType || "None");
    setSinglePin(row.singlePin || "");
    setRememoryHunt(row.rememoryHunt || "No");
    setTimeConditions(
      Array.isArray(row.timeConditions) ? row.timeConditions : [],
    );
    setDialPatterns(
      Array.isArray(row.dialPatterns) && row.dialPatterns.length > 0
        ? row.dialPatterns
        : [{ ...OUTBOUND_ROUTE_DEFAULT_DIAL_PATTERN }],
    );
    setCallerConversion(
      row.callerConversion || { ...OUTBOUND_ROUTE_DEFAULT_CALLER_CONVERSION },
    );
    setMemberExtensions(
      Array.isArray(row.memberExtensions) ? row.memberExtensions : [],
    );
    setMemberTrunks(Array.isArray(row.memberTrunks) ? row.memberTrunks : []);
    setShowModal(true);
    await ensureFormListsLoaded();
  };

  const handleCloseModal = () => {
    if (loading.save) return;
    setShowModal(false);
    resetForm();
  };

  const handleCheckAll = () => setSelected(rows.map((_, i) => i));
  const handleUncheckAll = () => setSelected([]);
  const handleSelectRow = (idx) =>
    setSelected((prev) =>
      prev.includes(idx) ? prev.filter((i) => i !== idx) : [...prev, idx],
    );

  const handleDelete = async () => {
    if (selected.length === 0) {
      showAlert("Please select at least one row to delete.");
      return;
    }
    if (
      !window.confirm(
        `Are you sure you want to delete ${selected.length} record(s)?`,
      )
    )
      return;
    setLoading((prev) => ({ ...prev, delete: true }));
    try {
      const idsToDelete = selected
        .map((idx) => rows[idx]?.id)
        .filter((id) => id != null);
      const results = await Promise.all(
        idsToDelete.map((id) => deleteOutboundRoute(id)),
      );
      const failed = results.find((r) => !r?.response);
      if (failed)
        showAlert(failed?.message || "Failed to delete one or more routes.");
      else showMessage("success", "Outbound route(s) deleted successfully.");
      await fetchOutboundRoutes();
      setSelected([]);
      setPage(1);
    } catch (err) {
      showAlert(err?.message || "Failed to delete route(s).");
    } finally {
      setLoading((prev) => ({ ...prev, delete: false }));
    }
  };

  const handleSave = async () => {
    const form = { name, priority, description, nextRoute, enabled, passwordType, singlePin, rememoryHunt, timeConditions, dialPatterns, callerConversion, memberExtensions, memberTrunks };
    const error = validateOutboundRouteForm(form);
    if (error) { showAlert(error); return; }
    const apiPayload = buildOutboundRoutePayload(form);
    setLoading((prev) => ({ ...prev, save: true }));
    try {
      const res = editId != null ? await updateOutboundRoute(editId, apiPayload) : await createOutboundRoute(apiPayload);
      if (!res?.response) { showAlert(res?.message || "Failed to save outbound route."); return; }
      showMessage("success", editId != null ? "Outbound route updated successfully." : "Outbound route created successfully.");
      await fetchOutboundRoutes();
      handleCloseModal();
    } catch (err) {
      showAlert(err?.message || "Failed to save outbound route.");
    } finally {
      setLoading((prev) => ({ ...prev, save: false }));
    }
  };

  const toggleTimeCondition = (value) => {
    setTimeConditions((prev) => {
      if (value === "Holiday" && !prev.includes("All")) return prev;
      const exists = prev.includes(value);
      const next = exists
        ? prev.filter((item) => item !== value)
        : [...prev, value];
      if (value === "All" && exists) {
        return next.filter((item) => item !== "Holiday");
      }
      return next;
    });
  };

  const updateDialPattern = (index, key, value) => {
    setDialPatterns((prev) =>
      prev.map((item, i) => (i === index ? { ...item, [key]: value } : item)),
    );
  };

  const addDialPattern = () =>
    setDialPatterns((prev) => [
      ...prev,
      { ...OUTBOUND_ROUTE_DEFAULT_DIAL_PATTERN, pattern: "^\\d*$" },
    ]);
  const removeDialPatternAt = (index) =>
    setDialPatterns((prev) =>
      prev.length <= 1 ? prev : prev.filter((_, i) => i !== index),
    );

  const allRowsSelected =
    rows.length > 0 && rows.every((_, index) => selected.includes(index));
  const someRowsSelected =
    rows.some((_, index) => selected.includes(index)) && !allRowsSelected;


  return {
    isCompact, rows, selected, showModal, loading, isInitialLoad, editId, name, priority, description, nextRoute, enabled, passwordType, singlePin, rememoryHunt, timeConditions, dialPatterns, callerConversion, availableExtensions, memberExtensions, availableTrunks, memberTrunks, itemsPerPage, page, totalPages, pagedRows, message, allExtensionOptions, allTrunkOptions, allRowsSelected, someRowsSelected,
    setMessage, setName, setPriority, setDescription, setNextRoute, setEnabled, setPasswordType, setSinglePin, setRememoryHunt, setMemberExtensions, setMemberTrunks, setCallerConversion, setPage,
    getExtensionLabel, getTrunkLabel, handleOpenAddModal, handleOpenEditModal, handleCloseModal, handleCheckAll, handleUncheckAll, handleSelectRow, handleDelete, handleSave, toggleTimeCondition, updateDialPattern, addDialPattern, removeDialPatternAt,
  };
}

import { useEffect, useRef, useState } from "react";
import { useMediaQuery } from "@mui/material";
import {
  TIME_CONDITION_DAYS_OF_MONTH,
  TIME_CONDITION_DAYS_OF_WEEK,
  TIME_CONDITION_INITIAL_FORM,
  TIME_CONDITION_MONTHS,
} from "../../../../constants/TimeConditionConstants";
import {
  createTimeCondition,
  deleteAllTimeConditions,
  deleteTimeCondition,
  fetchTimeConditions,
  updateTimeCondition,
} from "../../../../api/apiService";
import {
  buildTimeConditionApiPayload,
  formFromRow,
  normalizeFromApi,
  normalizeTimeConditionList,
} from "../utils/TimeConditionTransformers";
import { validateTimeConditionForm } from "../utils/TimeConditionValidators";

const TIME_CONDITION_COMPACT_MQ = "(max-width: 768px)";

export function useTimeConditionPage() {
  const isCompact = useMediaQuery(TIME_CONDITION_COMPACT_MQ);
  const [rows, setRows] = useState([]);
  const [selected, setSelected] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [editId, setEditId] = useState(null);
  const [form, setForm] = useState({ ...TIME_CONDITION_INITIAL_FORM });
  const [loading, setLoading] = useState({
    fetch: false,
    save: false,
    delete: false,
  });
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const [toast, setToast] = useState({ msg: "", type: "" });
  const hasLoaded = useRef(false);

  const itemsPerPage = 20;
  const [page, setPage] = useState(1);
  const totalPages = Math.max(1, Math.ceil(rows.length / itemsPerPage));
  const pagedRows = rows.slice((page - 1) * itemsPerPage, page * itemsPerPage);

  const showToast = (msg, type = "success") => {
    setToast({ msg, type });
    setTimeout(() => setToast({ msg: "", type: "" }), 4000);
  };

  const loadRows = async () => {
    setLoading((p) => ({ ...p, fetch: true }));
    try {
      const res = await fetchTimeConditions();
      setRows(normalizeTimeConditionList(res).map(normalizeFromApi));
    } catch (e) {
      showToast(e?.message || "Failed to load time conditions", "error");
    } finally {
      setLoading((p) => ({ ...p, fetch: false }));
      setIsInitialLoad(false);
    }
  };

  useEffect(() => {
    if (!hasLoaded.current) {
      hasLoaded.current = true;
      loadRows();
    }
  }, []);

  const handleCheckAll = () => setSelected(rows.map((_, i) => i));
  const handleUncheckAll = () => setSelected([]);
  const handleSelectRow = (idx) =>
    setSelected((s) =>
      s.includes(idx) ? s.filter((i) => i !== idx) : [...s, idx],
    );

  const allRowsSelected =
    rows.length > 0 && rows.every((_, index) => selected.includes(index));
  const someRowsSelected =
    rows.some((_, index) => selected.includes(index)) && !allRowsSelected;

  const handleDelete = async () => {
    if (!selected.length) return;
    if (!window.confirm(`Delete ${selected.length} item(s)?`)) return;
    setLoading((p) => ({ ...p, delete: true }));
    try {
      const ids = selected.map((idx) => rows[idx].id);
      if (ids.length === 1) {
        await deleteTimeCondition(ids[0]);
      } else {
        await deleteAllTimeConditions(ids);
      }
      setSelected([]);
      await loadRows();
      showToast("Deleted successfully");
    } catch (e) {
      showToast(e?.message || "Delete failed", "error");
    } finally {
      setLoading((p) => ({ ...p, delete: false }));
    }
  };

  const openAdd = () => {
    setForm({
      ...TIME_CONDITION_INITIAL_FORM,
      timeRanges: [
        { startHour: "09", startMinute: "00", endHour: "18", endMinute: "00" },
      ],
    });
    setEditId(null);
    setShowModal(true);
  };

  const openEdit = (row) => {
    setForm(formFromRow(row));
    setEditId(row.id);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setEditId(null);
  };

  const allDayValues = TIME_CONDITION_DAYS_OF_WEEK.map((d) => d.value);
  const allMonthValues = TIME_CONDITION_MONTHS.map((m) => m.value);
  const allDomValues = TIME_CONDITION_DAYS_OF_MONTH.map(String);

  const toggleCheck = (key, value, allValues) => {
    setForm((prev) => {
      const list = prev[key];
      if (value === "__ALL__") {
        return {
          ...prev,
          [key]: list.length === allValues.length ? [] : [...allValues],
        };
      }
      return {
        ...prev,
        [key]: list.includes(value)
          ? list.filter((v) => v !== value)
          : [...list, value],
      };
    });
  };

  const handleDaysOfMonthToggle = (value) => {
    if (value === "__ALL__") {
      setForm((p) => ({
        ...p,
        daysOfMonth:
          p.daysOfMonth.length === allDomValues.length ? [] : allDomValues,
      }));
    } else {
      setForm((p) => {
        const cur = p.daysOfMonth.map(String);
        return {
          ...p,
          daysOfMonth: cur.includes(value)
            ? cur.filter((d) => d !== value)
            : [...cur, value],
        };
      });
    }
  };

  const addTimeRange = () =>
    setForm((p) => ({
      ...p,
      timeRanges: [
        ...p.timeRanges,
        { startHour: "00", startMinute: "00", endHour: "00", endMinute: "00" },
      ],
    }));

  const removeTimeRange = (idx) =>
    setForm((p) => ({
      ...p,
      timeRanges: p.timeRanges.filter((_, i) => i !== idx),
    }));

  const updateTimeRange = (idx, field, val) =>
    setForm((p) => {
      const tr = [...p.timeRanges];
      tr[idx] = { ...tr[idx], [field]: val };
      return { ...p, timeRanges: tr };
    });

  const handleSave = async () => {
    const validationError = validateTimeConditionForm(form);
    if (validationError) {
      showToast(validationError, "error");
      return;
    }

    setLoading((p) => ({ ...p, save: true }));
    try {
      const payload = buildTimeConditionApiPayload({ editId, form });

      const res =
        editId !== null
          ? await updateTimeCondition(payload)
          : await createTimeCondition(payload);

      if (res?.response === false) {
        showToast(res.message || "Save failed", "error");
        return;
      }
      showToast(
        editId !== null ? "Updated successfully" : "Created successfully",
      );
      closeModal();
      await loadRows();
    } catch (e) {
      showToast(e?.message || "Save failed", "error");
    } finally {
      setLoading((p) => ({ ...p, save: false }));
    }
  };

  return {
    isCompact,
    rows,
    selected,
    showModal,
    editId,
    form,
    setForm,
    loading,
    isInitialLoad,
    toast,
    setToast,
    itemsPerPage,
    page,
    setPage,
    totalPages,
    pagedRows,
    allRowsSelected,
    someRowsSelected,
    allDayValues,
    allMonthValues,
    allDomValues,
    handleCheckAll,
    handleUncheckAll,
    handleSelectRow,
    handleDelete,
    openAdd,
    openEdit,
    closeModal,
    toggleCheck,
    handleDaysOfMonthToggle,
    addTimeRange,
    removeTimeRange,
    updateTimeRange,
    handleSave,
  };
}

