  const label = (
    <span
      style={{
        fontSize: 13,
        fontWeight: 600,
        color: C.labelText,
        cursor: tooltip ? "help" : undefined,
        ...style,
      }}
    >
      {children}
    </span>
  );
  if (!tooltip) return label;
  return (
    <Tooltip title={formatIvrTooltipTitle(tooltip)} {...IVR_TOOLTIP_PROPS}>
      {label}
    </Tooltip>
  );
};

const IvrFieldRow = ({
  label,
  tooltipKey,
  children,
  required = false,
  alignTop = false,
  labelWidth = IVR_MODAL_LABEL_WIDTH,
