                    >
                      {/* Left Column */}
                      <div
                        style={{
                          display: "flex",
                          flexDirection: "column",
                          gap: 16,
                        }}
                      >
                  <IvrFieldRow label="Name" tooltipKey="name" required>
  <TextField
    size="small"
    fullWidth
    value={name}
    onChange={(e) => setName(e.target.value)}
    sx={ivrModalTextFieldFullSx}
  />
</IvrFieldRow>
                        <IvrFieldRow label="IVR Number" tooltipKey="ivr_number" required>
                          <TextField
                            size="small"
                            fullWidth
                            type="number"
                            value={ivrNumber}
                            onChange={(e) => setIvrNumber(e.target.value)}
                            sx={ivrModalTextFieldFullSx}
                          />
                        </IvrFieldRow>

                        <IvrFieldRow label="Greet Long" tooltipKey="greet_long" required>
                          <div
                            style={{
                              display: "flex",
                              alignItems: "center",
                              gap: 8,
                              width: "100%",
                            }}
                          >
                            <FormControl size="small" fullWidth>
                              <MuiSelect
                                value={greetLong}
                                onChange={(e) => setGreetLong(e.target.value)}
                                sx={ivrModalSelectSx}
                              >
                                {greetLongOptions.map((opt) => (
                                  <MenuItem
                                    key={opt}
                                    value={opt}
                                    sx={{ fontSize: 13 }}
                                  >
                                    {opt}
                                  </MenuItem>
                                ))}
                              </MuiSelect>
                            </FormControl>
                            <span
                              onClick={handleGoToVoicePrompts}
                              style={{
                                fontSize: 11,
                                color: C.accent,
                                cursor: "pointer",
                                textDecoration: "underline",
                              }}
                            >
                              Prompt
                            </span>
                          </div>
                        </IvrFieldRow>

                        <IvrFieldRow label="Greet Short" tooltipKey="greet_short" required>
                          <div
                            style={{
                              display: "flex",
                              alignItems: "center",
                              gap: 8,
                              width: "100%",
                            }}
                          >
                            <FormControl size="small" fullWidth>
                              <MuiSelect
                                value={greetShort}
                                onChange={(e) => setGreetShort(e.target.value)}
                                sx={ivrModalSelectSx}
                              >
                                {greetShortOptions.map((opt) => (
                                  <MenuItem
                                    key={opt}
                                    value={opt}
                                    sx={{ fontSize: 13 }}
                                  >
                                    {opt}
                                  </MenuItem>
                                ))}
                              </MuiSelect>
                            </FormControl>
                            <span
                              onClick={handleGoToVoicePrompts}
                              style={{
                                fontSize: 11,
                                color: C.accent,
                                cursor: "pointer",
                                textDecoration: "underline",
                              }}
                            >
                              Prompt
                            </span>
                          </div>
                        </IvrFieldRow>

                        <IvrFieldRow label="Response Timeout(ms)" tooltipKey="response_timeout" required>
                          <TextField
                            size="small"
                            fullWidth
                            type="number"
                            value={responseTimeout}
                            onChange={(e) => setResponseTimeout(e.target.value)}
                            sx={ivrModalTextFieldFullSx}
                          />
                        </IvrFieldRow>

                        <IvrFieldRow label="Password" tooltipKey="password" required>
                          <TextField
                            size="small"
                            fullWidth
                            type={showPassword ? "text" : "password"}
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            sx={ivrModalTextFieldFullSx}
                            InputProps={{
                              endAdornment: (
                                <InputAdornment position="end">
                                  <IconButton
                                    size="small"
                                    onClick={() =>
                                      setShowPassword(!showPassword)
                                    }
                                  >
                                    {showPassword ? (
                                      <VisibilityOff sx={{ fontSize: 16 }} />
                                    ) : (
                                      <Visibility sx={{ fontSize: 16 }} />
                                    )}
                                  </IconButton>
                                </InputAdornment>
                              ),
                            }}
                          />
                        </IvrFieldRow>

                        <IvrFieldRow label="Check Voicemail" tooltipKey="check_voicemail" required>
                          <FormControl size="small" fullWidth>
                            <MuiSelect
                              value={checkVoicemail}
                              onChange={(e) =>
                                setCheckVoicemail(e.target.value)
                              }
                              sx={ivrModalSelectSx}
                            >
                              {IVR_CHECK_VOICEMAIL_OPTIONS.map((opt) => (
                                <MenuItem
                                  key={opt}
                                  value={opt}
                                  sx={{ fontSize: 13 }}
                                >
                                  {opt}
                                </MenuItem>
                              ))}
                            </MuiSelect>
                          </FormControl>
                        </IvrFieldRow>

                        <IvrFieldRow
                          label="Direct Outbound"
                          tooltipKey="direct_outbound"
                          labelWidth={170}
                        >
                          <Checkbox
                            checked={directOutbound}
                            onChange={(e) =>
                              setDirectOutbound(e.target.checked)
                            }
                            size="small"
                            sx={ivrTableCheckboxSx}
                          />
                        </IvrFieldRow>
                      </div>

                      {/* Right Column */}
                      <div
                        style={{
                          display: "flex",
                          flexDirection: "column",
                          gap: 16,
                        }}
                      >
                        <IvrFieldRow label="Inter-Digit Timeout(ms)" tooltipKey="inter_digit_timeout" required>
                          <TextField
                            size="small"
                            fullWidth
                            type="number"
                            value={interDigitTimeout}
                            onChange={(e) =>
                              setInterDigitTimeout(e.target.value)
                            }
                            sx={ivrModalTextFieldFullSx}
                          />
                        </IvrFieldRow>

                        <IvrFieldRow label="Max Failures" tooltipKey="max_failures" required>
                          <TextField
                            size="small"
                            fullWidth
                            type="number"
                            value={maxFailures}
                            onChange={(e) => setMaxFailures(e.target.value)}
                            sx={ivrModalTextFieldFullSx}
                          />
                        </IvrFieldRow>

                        <IvrFieldRow label="Max Timeouts" tooltipKey="max_timeouts" required>
                          <TextField  
                            size="small"
                            fullWidth
                            type="number"
                            value={maxTimeouts}
                            onChange={(e) => setMaxTimeouts(e.target.value)}
                            sx={ivrModalTextFieldFullSx}
                          />
                        </IvrFieldRow>

                        <IvrFieldRow label="Digit Length" tooltipKey="digit_length" required>
                          <TextField
                            size="small"
                            fullWidth
                            type="number"
                            value={digitLength}
                            onChange={(e) => setDigitLength(e.target.value)}
                            sx={ivrModalTextFieldFullSx}
                          />
                        </IvrFieldRow>

                        <IvrFieldRow label="Enabled" tooltipKey="enabled" required>
                          <FormControl size="small" fullWidth>
                            <MuiSelect
                              value={enabled}
                              onChange={(e) => setEnabled(e.target.value)}
                              sx={ivrModalSelectSx}
                            >
                              {IVR_ENABLE_OPTIONS.map((opt) => (
                                <MenuItem
                                  key={opt}
                                  value={opt}
                                  sx={{ fontSize: 13 }}
                                >
                                  {opt}
                                </MenuItem>
                              ))}
                            </MuiSelect>
                          </FormControl>
                        </IvrFieldRow>

                        <IvrFieldRow label="Direct Extension" tooltipKey="direct_extension" required>
                          <FormControl size="small" fullWidth>
                            <MuiSelect
                              value={directExtension}
                              onChange={(e) =>
                                setDirectExtension(e.target.value)
                              }
                              sx={ivrModalSelectSx}
                            >
                              {IVR_DIRECT_EXTENSION_OPTIONS.map((opt) => (
                                <MenuItem
                                  key={opt}
                                  value={opt}
                                  sx={{ fontSize: 13 }}
                                >
                                  {opt}
                                </MenuItem>
                              ))}
                            </MuiSelect>
                          </FormControl>
                        </IvrFieldRow>

                        <IvrFieldRow label="FXO Flash Transfer" tooltipKey="fxo_flash_transfer" required>
                          <FormControl size="small" fullWidth>
                            <MuiSelect
                              value={fxoFlashTransfer}
                              onChange={(e) =>
                                setFxoFlashTransfer(e.target.value)
                              }
                              sx={ivrModalSelectSx}
                            >
                              {IVR_FXO_FLASH_TRANSFER_OPTIONS.map((opt) => (
                                <MenuItem
                                  key={opt}
                                  value={opt}
                                  sx={{ fontSize: 13 }}
                                >
                                  {opt}
                                </MenuItem>
                              ))}
                            </MuiSelect>
                          </FormControl>
                        </IvrFieldRow>
                      </div>
                    </div>

                    {/* Outbound Routes Section (Conditionally Rendered before Advanced) */}
                    {directOutbound && (
                      <div
                        style={{
                          marginTop: 24,
                          paddingTop: 16,
                       
                        }}
                      >
                        <div
                          style={{
                            display: "flex",
                            alignItems: "center",
                            gap: 12,
                            marginBottom: 12,
                          }}
                        >
                          <span
                            style={{
                              fontSize: 14,
                              fontWeight: 700,
                              color: C.labelText,
                            }}
                          >
                            Outbound Routes{" "}
                            <span style={{ color: C.errorRed }}>*</span>
                          </span>
                        </div>

                        <IvrCodecDualList
                          style={{ marginTop: 16 }}
                          allOptions={
                            loading.outboundRoutes ? [] : allOutboundRouteOptions
                          }
                          selected={selectedOutboundRouteIds}
                          onChange={setSelectedOutboundRouteIds}
                          getLabel={getOutboundRouteLabel}
                          emptyTextAvailable={
                            loading.outboundRoutes
                              ? "Loading routes..."
                              : "No routes available"
                          }
                          emptyTextSelected="No selected routes"
                        />
                      </div>
                    )}

                    {/* Advanced Divider */}
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        margin: "32px 0 20px 0",
                      }}
                    >
                        <span
                          style={{
                            fontSize: 12,
                            fontWeight: 700,
                            color: C.labelText,
                            textTransform: "uppercase",
                            letterSpacing: "0.04em",
                          }}
                        >
                          Advanced
                        </span>

                      <div
                        style={{
                          flex: 1,
                          height: 1,
                          background: C.cardBorder,
                          marginLeft: 12,
                        }}
                      />
                    </div>

                    {/* Advanced Section 2-Column Grid */}
                    <div
                      style={{
                        display: "grid",
                        gridTemplateColumns: "1fr 1fr", ...(isCompact ? { gridTemplateColumns: "1fr" } : {}),
                        gap: "16px 40px",
                      }}
                    >
                      {/* Advanced Left Column */}
                      <div
                        style={{
                          display: "flex",
                          flexDirection: "column",
                          gap: 16,
                        }}
                      >
                        <IvrFieldRow label="Invalid Sound" tooltipKey="invalid_sound" required>
                          <FormControl size="small" fullWidth>
                            <MuiSelect
                              value={invalidSound}
                              onChange={(e) => setInvalidSound(e.target.value)}
                              sx={ivrModalSelectSx}
                            >
                              {invalidSoundOptions.map((opt) => (
                                <MenuItem
                                  key={opt}
                                  value={opt}
                                  sx={{ fontSize: 13 }}
                                >
                                  {opt}
                                </MenuItem>
                              ))}
                            </MuiSelect>
                          </FormControl>
                        </IvrFieldRow>

                        <IvrFieldRow label="Exit Sound" tooltipKey="exit_sound" required>
                          <FormControl size="small" fullWidth>
                            <MuiSelect
                              value={exitSound}
                              onChange={(e) => setExitSound(e.target.value)}
                              sx={ivrModalSelectSx}
                            >
                              {exitSoundOptions.map((opt) => (
                                <MenuItem
                                  key={opt}
                                  value={opt}
                                  sx={{ fontSize: 13 }}
                                >
                                  {opt}
                                </MenuItem>
                              ))}
                            </MuiSelect>
                          </FormControl>
                        </IvrFieldRow>

                        <IvrFieldRow label="Exit Action" tooltipKey="exit_action" required>
                          <FormControl size="small" fullWidth>
                            <MuiSelect
                              value={exitActionType || ""}
                              displayEmpty
                              onChange={(e) => {
                                setExitActionType(e.target.value);
                                setExitActionValue("");
                              }}
                              renderValue={(value) =>
                                value
                                  ? formatActionLabel(value)
                                  : "Select action"
                              }
                              MenuProps={ivrModalSelectMenuProps}
                              sx={ivrModalSelectSx}
                            >
                              <MenuItem value="" sx={{ fontSize: 13 }}>
                                <em>Select action</em>
                              </MenuItem>
                              {actionTypeOptions.map((opt) => (
                                <MenuItem
                                  key={opt}
                                  value={opt}
                                  sx={{ fontSize: 13 }}
                                >
                                  {formatActionLabel(opt)}
                                </MenuItem>
                              ))}
                            </MuiSelect>
                          </FormControl>
                        </IvrFieldRow>
                      </div>

                      {/* Advanced Right Column */}
                      <div
                        style={{
                          display: "flex",
                          flexDirection: "column",
                          gap: 16,
                        }}
                      >
                        <IvrFieldRow label="Ring Back" tooltipKey="ring_back" alignTop>
                          <FormControl size="small" fullWidth>
                            <MuiSelect
                              value={ringBack}
                              onChange={(e) => setRingBack(e.target.value)}
                              MenuProps={ivrModalSelectMenuProps}
                              sx={ivrModalSelectSx}
                            >
                              {ringBack &&
                                !ringBackAllValues.includes(ringBack) && (
                                  <MenuItem
                                    value={ringBack}
                                    sx={{ fontSize: 13 }}
                                  >
                                    {ringBack}
                                  </MenuItem>
                                )}
                              {ringBackOptions.moh_categories.length > 0 && (
                                <ListSubheader
                                  disableSticky
                                  sx={{
                                    fontWeight: 700,
                                    fontSize: 12,
                                    lineHeight: "24px",
                                  }}
                                >
                                  Music on Hold
                                </ListSubheader>
                              )}
                              {ringBackOptions.moh_categories.map((opt) => (
                                <MenuItem
                                  key={`moh-${opt}`}
                                  value={opt}
                                  sx={{ pl: 3, fontSize: 13 }}
                                >
                                  {opt}
                                </MenuItem>
                              ))}
                              {ringBackOptions.custom_prompts.length > 0 && (
                                <ListSubheader
                                  disableSticky
                                  sx={{
                                    fontWeight: 700,
                                    fontSize: 12,
                                    lineHeight: "24px",
                                  }}
                                >
                                  Custom Prompt
                                </ListSubheader>
                              )}
                              {ringBackOptions.custom_prompts.map((opt) => (
                                <MenuItem
                                  key={`prompt-${opt}`}
                                  value={opt}
                                  sx={{ pl: 3, fontSize: 13 }}
                                >
                                  {opt}
                                </MenuItem>
                              ))}
                              {ringBackOptions.country_tones.length > 0 && (
                                <ListSubheader
                                  disableSticky
                                  sx={{
                                    fontWeight: 700,
                                    fontSize: 12,
                                    lineHeight: "24px",
                                  }}
                                >
                                  Ring Back
                                </ListSubheader>
                              )}
                              {ringBackOptions.country_tones.map((opt) => (
                                <MenuItem
                                  key={`tone-${opt}`}
                                  value={opt}
                                  sx={{ pl: 3, fontSize: 13 }}
                                >
                                  {opt}
                                </MenuItem>
                              ))}
                            </MuiSelect>
                          </FormControl>
                        </IvrFieldRow>

                        <IvrFieldRow label="Caller ID Name Prefix" tooltipKey="caller_id_name_prefix" required>
                          <TextField
                            size="small"
                            fullWidth
                            value={callerIdNamePrefix}
                            onChange={(e) =>
                              setCallerIdNamePrefix(e.target.value)
                            }
                            sx={ivrModalTextFieldFullSx}
                          />
                        </IvrFieldRow>

                        {exitActionType && (
                          <IvrFieldRow label="Destination" tooltipKey="exit_destination" required>
                            {renderDestinationSelect(
                              exitActionType,
                              exitActionValue,
                              setExitActionValue,
                            )}
                          </IvrFieldRow>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {/* ── KEY PRESS TAB ── */}
              {activeTab === "keypress" && (
                <div
                  style={{ display: "flex", flexDirection: "column", gap: 16 }}
                >
                  <div style={{ padding: 0 }}>
                  <div
                    style={{
                      display: "grid",
                      gridTemplateColumns: "100px 1fr 1fr",
                      gap: 16,
                      marginBottom: 12,
                      borderBottom: `1px solid ${C.cardBorder}`,
                      paddingBottom: 8,
                    }}
                  >
                    <span
                      style={{
                        fontSize: 13,
                        fontWeight: 700,
                        color: C.labelText,
                      }}
                    >
                      Option
                    </span>
                    <span
                      style={{
                        fontSize: 13,
                        fontWeight: 700,
                        color: C.labelText,
                      }}
                    >
                      Destination
                    </span>
                    <span
                      style={{
                        fontSize: 13,
                        fontWeight: 700,
                        color: C.labelText,
                      }}
                    >
                      Target
                    </span>
                  </div>
                  <div
                    style={{
                      fontSize: 13,
                      fontWeight: 700,
                      color: C.labelText,
                    }}
                  >
                    {KEYS.map((key) => (
                      <div
                        key={key}
                        style={{
                          display: "grid",
                          gridTemplateColumns: "100px 1fr 1fr",
                          gap: 16,
                          alignItems: "center",
                          borderBottom: `1px solid ${C.cardBorder}`,
                          paddingBottom: 12,
                          marginBottom: 12,
                        }}
                      >
                        <span
                          style={{
                            fontSize: 13,
                            fontWeight: 600,
                            color: C.labelText,
                          }}
                        >
                          Digit{" "}
                          <span
                            style={{
                              color: C.accent,
                              padding: "2px 6px",
                              background: "#f1f5f9",
                              borderRadius: 4,
                              marginLeft: 4,
                            }}
                          >
                            {key}
                          </span>
                        </span>
                        <FormControl size="small" fullWidth>
                          <MuiSelect
                            value={keyDestinations[key] || ""}
                            displayEmpty
                            onChange={(e) => {
                              const val = e.target.value;
                              handleKeyDestinationChange(key, val);
                              handleKeyDestinationValueChange(key, "");
                            }}
                            renderValue={(value) =>
                              value
                                ? formatActionLabel(value)
                                : "Select destination"
                            }
                            sx={{ fontSize: 13, background: "#fff" }}
                          >
                            <MenuItem value="" sx={{ fontSize: 13 }}>
                              <em>Select destination</em>
                            </MenuItem>
                            {keyActionTypeOptions.map((opt) => (
                              <MenuItem
                                key={opt}
                                value={opt}
                                sx={{ fontSize: 13 }}
                              >
                                {formatActionLabel(opt)}
                              </MenuItem>
                            ))}
                          </MuiSelect>
                        </FormControl>
                        <div>
                          {renderDestinationSelect(
                            keyDestinations[key],
                            keyDestinationValues[key],
                            (val) => handleKeyDestinationValueChange(key, val),
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </DialogContent>
        <DialogActions sx={{ p: 0, m: 0 }} style={addNewModalFooterStyle}>
          <Btn
            onClick={handleSave}
            disabled={loading.save}
            variant="primary"
            style={addNewModalFooterBtnStyle}
          >
            {loading.save ? (
              <>
                <CircularProgress size={14} style={{ color: "#fff" }} />
                Saving...
              </>
            ) : editId != null ? (
              "Update IVR"
            ) : (
              "Create IVR"
            )}
          </Btn>
          <Btn
            onClick={handleCloseModal}
            disabled={loading.save}
            variant="cancel"
            style={ivrModalCancelBtnStyle}
          >
            Cancel
          </Btn>
        </DialogActions>
      </Dialog>
    </div>
  );
};

export default IVRPage;

import React from "react";
import { Tooltip } from "@mui/material";
import {
  C,
  FOCUS_RING_SHADOW,
  OUTLINED_BORDER,
  OUTLINED_FOCUS,
  OUTLINED_HOVER,
} from "../../../../theme/pbxTokens";
import { BLOCKED_LIST_FIELD_TOOLTIPS } from "../../../../constants/BlockedListConstants";

export const addNewModalFooterStyle = {
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  gap: 12,
  width: "100%",
  margin: 0,
  padding: "16px 24px",
  boxSizing: "border-box",
  background: "#f8fafc",
  borderTop: `1px solid ${C.cardBorder}`,
  borderBottomLeftRadius: 4,
  borderBottomRightRadius: 4,
};

export const addNewModalFooterBtnStyle = {
  height: 30,
  padding: "6px 14px",
  fontSize: 12,
  borderRadius: 4,
  minWidth: 100,
};

export const blockedListModalCancelBtnStyle = {
  ...addNewModalFooterBtnStyle,
  background: "#cbd5e1",
  color: "#374151",
  border: "1px solid #cbd5e1",
  borderRadius: 4,
  boxShadow: "0 1px 2px rgba(15, 23, 42, 0.08)",
};

const blockedListOutlinedInputRootSx = {
  backgroundColor: "#fff",
  transition: "border-color 0.2s ease, box-shadow 0.2s ease",
  "& fieldset": {
    borderColor: OUTLINED_BORDER,
    transition: "border-color 0.2s ease, box-shadow 0.2s ease",
  },
  "&:hover fieldset": {
    borderColor: OUTLINED_HOVER,
  },
  "&.Mui-focused": {
    boxShadow: FOCUS_RING_SHADOW,
  },
  "&.Mui-focused fieldset": {
    borderColor: OUTLINED_FOCUS,
    borderWidth: "1px",
  },
  "&.Mui-focused:hover fieldset": {
    borderColor: OUTLINED_FOCUS,
    borderWidth: "1px",
  },
};

export const blockedListModalTextFieldFullSx = {
  width: "100%",
  "& .MuiOutlinedInput-root": {
    ...blockedListOutlinedInputRootSx,
    minHeight: 36,
    height: 36,
    fontSize: 13,
  },
  "& .MuiOutlinedInput-input": {
    padding: "7px 10px",
    fontSize: 13,
    boxSizing: "border-box",
    backgroundColor: "#fff",
  },
};

export const blockedListModalSelectSx = {
  fontSize: 13,
  backgroundColor: "#fff",
  width: "100%",
  minHeight: 36,
  height: 36,
  ...blockedListOutlinedInputRootSx,
  "& .MuiOutlinedInput-notchedOutline": {
    borderColor: OUTLINED_BORDER,
    transition: "border-color 0.2s ease, box-shadow 0.2s ease",
  },
  "&:hover .MuiOutlinedInput-notchedOutline": {
    borderColor: OUTLINED_HOVER,
  },
  "&.Mui-focused .MuiOutlinedInput-notchedOutline": {
    borderColor: OUTLINED_FOCUS,
    borderWidth: "1px",
  },
  "& .MuiSelect-select": {
    display: "flex",
    alignItems: "center",
    padding: "7px 32px 7px 10px !important",
    lineHeight: 1.35,
    boxSizing: "border-box",
    fontSize: 13,
    backgroundColor: "#fff",
  },
};

export const blockedListModalPaperSx = {
  width: 560,
  maxWidth: "95vw",
  margin: 24,
  maxHeight: "calc(100vh - 80px - 48px)",
  display: "flex",
  flexDirection: "column",
  p: 0,
  borderRadius: 2,
  overflow: "hidden",
  boxShadow:
    "0 10px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1)",
};

export const blockedListModalTitleStyle = {
  background: "#1e2d42",
  color: "#ffffff",
  fontWeight: 600,
  fontSize: 16,
  padding: "16px 24px",
  textAlign: "center",
  borderTopLeftRadius: 4,
  borderTopRightRadius: 4,
};

export const blockedListModalFormStyle = {
  display: "flex",
  flexDirection: "column",
  gap: 14,
  width: "100%",
  maxWidth: "100%",
  boxSizing: "border-box",
  overflow: "hidden",
  background: "#f8fafc",
  border: `1px solid ${C.cardBorder}`,
  borderRadius: 4,
  padding: 20,
};

const BLOCKED_LIST_TOOLTIP_PROPS = {
