};

const extensionGatedModalFieldSx = (
  enabled,
  baseSx = extensionModalSelectSx,
  enabledCursor = "pointer",
) => {
  const disabledBg = "#f1f5f9";
  const isTextFieldBase = Boolean(baseSx["& .MuiOutlinedInput-root"]);
  const outlinedRootSx = baseSx["& .MuiOutlinedInput-root"] || {};
  const outlinedInputSx = baseSx["& .MuiOutlinedInput-input"] || {};
  const selectSx = baseSx["& .MuiSelect-select"] || {};

  const disabledOutlineSx = !enabled
    ? {
        "&:hover fieldset": { borderColor: OUTLINED_BORDER },
        "&:hover .MuiOutlinedInput-notchedOutline": {
          borderColor: OUTLINED_BORDER,
        },
        "&.Mui-focused": { boxShadow: "none" },
      }
    : {};

  if (isTextFieldBase) {
    return {
      ...baseSx,
      backgroundColor: enabled ? "#fff" : disabledBg,
      cursor: enabled ? enabledCursor : "not-allowed",
      ...(!enabled && {
        "&:hover .MuiOutlinedInput-notchedOutline": {
          borderColor: OUTLINED_BORDER,
        },
      }),
      "& .MuiOutlinedInput-root": {
        ...outlinedRootSx,
        backgroundColor: enabled ? "#fff" : disabledBg,
        cursor: enabled ? enabledCursor : "not-allowed",
        ...disabledOutlineSx,
      },
      "& .MuiOutlinedInput-input, & .MuiInputBase-input": {
        ...outlinedInputSx,
        backgroundColor: enabled ? "#fff" : disabledBg,
        cursor: enabled ? enabledCursor : "not-allowed",
      },
      "&.Mui-disabled, & .MuiOutlinedInput-root.Mui-disabled": {
        cursor: "not-allowed",
        backgroundColor: disabledBg,
      },
    };
  }

  return {
    ...baseSx,
    backgroundColor: enabled ? "#fff" : disabledBg,
    cursor: enabled ? enabledCursor : "not-allowed",
    ...disabledOutlineSx,
    "& .MuiSelect-select": {
      ...selectSx,
      backgroundColor: enabled ? "#fff" : disabledBg,
      cursor: enabled ? enabledCursor : "not-allowed",
    },
    "&.Mui-disabled": {
      cursor: "not-allowed",
      backgroundColor: disabledBg,
    },
  };
};

// ── Tooltip label ──

const EXTENSION_FIELD_TOOLTIP_PROPS = {
  arrow: true,
  placement: "top",
  slotProps: {
    tooltip: {
      sx: {
        backgroundColor: "#fff",
        color: "#333",
        border: "1px solid #d1d5db",
        boxShadow: "0 2px 8px rgba(0,0,0,0.15)",
        fontSize: 13,
        lineHeight: 1.45,
        maxWidth: 500,
        padding: "10px 12px",
      },
    },
    arrow: {
      sx: {
        color: "#fff",
      },
    },
  },
};

const formatExtensionTooltipTitle = (text) => {
  if (!text) return "";
  const normalized = text
    .replace(/<br\s*\/?>\s*/gi, "\n")
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\r\n/g, "\n")
    .replace(/\n{2,}/g, "\n")
    .trim();
  if (!normalized.includes("\n")) return normalized;

  const lines = normalized.split("\n");
  return (
    <span style={{ display: "block", lineHeight: 1.45, margin: 0 }}>
      {lines.map((line, index) => (
        <React.Fragment key={index}>
          {index > 0 ? <br /> : null}
          {line}
        </React.Fragment>
      ))}
    </span>
  );
};

const ExtensionTooltipLabel = ({ tooltipKey, children, style = {} }) => {
  const tooltip = tooltipKey ? EXTENSION_FIELD_TOOLTIPS[tooltipKey] || "" : "";
  const labelNode = (
    <span
      style={{
        fontSize: 13,
        fontWeight: 600,
        color: C.labelText,
        cursor: tooltip ? "help" : undefined,
        ...style,
      }}
    >
      {children}
    </span>
  );

  if (!tooltip) return labelNode;

  return (
    <Tooltip
      title={formatExtensionTooltipTitle(tooltip)}
      {...EXTENSION_FIELD_TOOLTIP_PROPS}
    >
      {labelNode}
    </Tooltip>
  );
};

// ── FieldRow / ErrMsg ──

const FieldRow = ({
  label,
  children,
  wide = false,
  labelWidth = 130,
  tooltipKey,
}) => {
  const tooltip = tooltipKey ? EXTENSION_FIELD_TOOLTIPS[tooltipKey] || "" : "";
  const labelStyle = {
    fontSize: 13,
    color: C.labelText,
    fontWeight: 600,
    whiteSpace: "nowrap",
    textAlign: "left",
    width: labelWidth,
    flexShrink: 0,
    paddingTop: wide ? 4 : 0,
    cursor: tooltip ? "help" : undefined,
  };

  const labelNode = <label style={labelStyle}>{label}</label>;

  return (
    <div
      style={{
        display: "flex",
        alignItems: wide ? "flex-start" : "center",
        gap: 12,
        width: "100%",
      }}
    >
      {tooltip ? (
        <Tooltip
          title={formatExtensionTooltipTitle(tooltip)}
          {...EXTENSION_FIELD_TOOLTIP_PROPS}
        >
          {labelNode}
        </Tooltip>
      ) : (
        labelNode
      )}
      <div
        style={{
          flex: 1,
          minWidth: 0,
          width: "100%",
        }}
      >
        {children}
      </div>
    </div>
  );
};

const ErrMsg = ({ children }) => (
  <div style={{ color: "#dc2626", fontSize: 11, marginTop: 2 }}>{children}</div>
);

// ── SectionCard / AllowCodecsSectionHeading ──

const SectionCard = ({ title, children, isFirst = false }) => (
  <div style={{ marginBottom: 8 }}>
    <ExtensionModalSectionHeading title={title} isFirst={isFirst} />
    <div>{children}</div>
  </div>
);

const AllowCodecsSectionHeading = ({ tooltipKey, required = false }) => (
  <ExtensionModalSectionHeading
    margin="24px 0 24px 0"
    titleNode={
      <>
        <ExtensionTooltipLabel
          tooltipKey={tooltipKey}
          style={{ fontSize: 14, color: EXTENSION_MODAL_SECTION_HEADING_COLOR }}
        >
          Allow Codecs
        </ExtensionTooltipLabel>
        {required && <span style={{ color: C.errorRed }}> *</span>}
      </>
    }
  />
);

// ── Destination autocomplete ──

const extensionFilterOptions = createFilterOptions({
  limit: 50,
});

const DestinationAutocomplete = React.memo(function DestinationAutocomplete({
  value,
  onCommit,
  options,
  disabled,
  placeholder,
  sx,
}) {
  const [inputValue, setInputValue] = useState(value || "");

  useEffect(() => {
    setInputValue(value || "");
  }, [value]);

  return (
    <Autocomplete
      freeSolo
      size="small"
      disabled={disabled}
      options={options}
      filterOptions={extensionFilterOptions}
      inputValue={inputValue}
      onInputChange={(e, newValue, reason) => {
        if (reason === "input" || reason === "clear") {
          setInputValue(newValue);
        }
      }}
      onBlur={() => onCommit(inputValue)}
      onChange={(e, newValue) => {
        const v = newValue || "";
        setInputValue(v);
        onCommit(v);
      }}
      sx={sx}
      renderInput={(params) => (
        <TextField
          {...params}
          placeholder={placeholder}
          sx={{
            ...extensionModalTextFieldSx,
            "& .MuiOutlinedInput-input": {
              ...(extensionModalTextFieldSx["& .MuiOutlinedInput-input"] || {}),
              fontSize: 13,
            },
            "& .MuiInputBase-input::placeholder": {
              fontSize: 13,
              fontWeight: 300,
              opacity: 1,
            },
          }}
        />
      )}
    />
  );
});

export {
  extensionOutlinedInputRootSx,
  extensionModalTextFieldSx,
  extensionModalSelectSx,
  extensionGatedModalFieldSx,
  EXTENSION_FIELD_TOOLTIP_PROPS,
  formatExtensionTooltipTitle,
  ExtensionTooltipLabel,
  FieldRow,
  ErrMsg,
  SectionCard,
  AllowCodecsSectionHeading,
  DestinationAutocomplete,
};

import { useEffect, useMemo, useRef, useState } from "react";
import {
  createExtensionGroup,
  deleteExtensionGroup,
  fetchExtensionGroups,
  fetchSipAccounts,
  updateExtensionGroup,
} from "../../../../api/apiService";
import { attachExtGroupModalSmoothWheelScroll } from "../components/ExtensionGroupsTableHelpers";
import {
  buildExtensionGroupPayload,
  mapAvailableExtensionsResponse,
  mapExtensionGroupsResponse,
} from "../utils/ExtensionGroupsTransformers";
import { validateExtensionGroup } from "../utils/ExtensionGroupsValidators";

export const useExtensionGroupsPage = () => {
  const [groups, setGroups] = useState([]);
  const [loading, setLoading] = useState({
    fetch: false, delete: false, save: false, extensions: false,
  });
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const [message, setMessage] = useState({ type: "", text: "" });
  const [page, setPage] = useState(1);
  const [limit] = useState(20);
  const [selectedIds, setSelectedIds] = useState([]);
  const hasInitialLoadRef = useRef(false);
  const modalScrollRef = useRef(null);
  const [showModal, setShowModal] = useState(false);
  const [editGroupId, setEditGroupId] = useState(null);
  const [groupName, setGroupName] = useState("");
  const [availableExtensions, setAvailableExtensions] = useState([]);
  const [selectedExtensions, setSelectedExtensions] = useState([]);

  const showMessage = (type, text) => {
    setMessage({ type, text });
    setTimeout(() => setMessage({ type: "", text: "" }), 5000);
  };

  const loadGroups = async () => {
    setLoading((p) => ({ ...p, fetch: true }));
    setMessage({ type: "", text: "" });
    try {
      const res = await fetchExtensionGroups();
      setGroups(mapExtensionGroupsResponse(res));
    } catch (err) {
      showMessage("error", err?.message || "Failed to load extension groups.");
    } finally {
      setLoading((p) => ({ ...p, fetch: false }));
      setIsInitialLoad(false);
    }
  };

  useEffect(() => {
    if (!hasInitialLoadRef.current) {
      hasInitialLoadRef.current = true;
      loadGroups();
    }
  }, []);

  useEffect(() => {
    if (!showModal) return undefined;
    let detach = () => {};
    const frame = requestAnimationFrame(() => {
      if (modalScrollRef.current) {
        detach = attachExtGroupModalSmoothWheelScroll(modalScrollRef.current);
      }
    });
    return () => {
      cancelAnimationFrame(frame);
      detach();
    };
  }, [showModal]);

  const totalPages = Math.max(1, Math.ceil(groups.length / limit));
  const pagedGroups = groups.slice((page - 1) * limit, page * limit);
  const dataEmpty = groups.length === 0;
  const pageIds = pagedGroups.map((g) => g.id);
  const allPageSelected =
    pageIds.length > 0 && pageIds.every((id) => selectedIds.includes(id));
  const somePageSelected =
    pagedGroups.some((g) => selectedIds.includes(g.id)) && !allPageSelected;

  const handleToggleRow = (id) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id],
    );
  };
  const handleToggleAll = () => {
    if (!pageIds.length) return;
    setSelectedIds((prev) =>
      allPageSelected
        ? prev.filter((id) => !pageIds.includes(id))
        : Array.from(new Set([...prev, ...pageIds])),
    );
  };
  const handleDelete = async () => {
    if (!selectedIds.length) {
      showMessage("error", "Please select at least one record to delete.");
      return;
    }
    const msg = selectedIds.length === 1
      ? "Are you sure you want to delete this group?"
      : `Are you sure you want to delete ${selectedIds.length} groups?`;
    if (!window.confirm(msg)) return;
    setLoading((p) => ({ ...p, delete: true }));
    setMessage({ type: "", text: "" });
    const deleteCount = selectedIds.length;
    try {
      await Promise.all(selectedIds.map((id) => deleteExtensionGroup(id)));
      setSelectedIds([]);
      await loadGroups();
      showMessage("success", deleteCount === 1
        ? "Extension group deleted successfully."
        : `${deleteCount} extension groups deleted successfully.`);
    } catch (err) {
      showMessage("error", err?.message || "Failed to delete some groups.");
    } finally {
      setLoading((p) => ({ ...p, delete: false }));
    }
  };

  const openExtensionList = () => {
    setLoading((p) => ({ ...p, extensions: true }));
    fetchSipAccounts()
      .then((res) => setAvailableExtensions(mapAvailableExtensionsResponse(res)))
      .catch(() => {
        setAvailableExtensions([]);
        showMessage("error", "Failed to load available extensions for the modal.");
      })
      .finally(() => setLoading((p) => ({ ...p, extensions: false })));
  };
  const resetModalState = () => {
    setEditGroupId(null);
    setGroupName("");
    setSelectedExtensions([]);
  };
  const handleOpenAddModal = () => {
    resetModalState();
    setShowModal(true);
    openExtensionList();
  };
  const handleOpenEditModal = (group) => {
    setEditGroupId(group.id);
    setGroupName(group.name || "");
    setSelectedExtensions(Array.isArray(group.extensions) ? [...group.extensions] : []);
    setShowModal(true);
    openExtensionList();
  };
  const handleCloseModal = () => {
    setShowModal(false);
    resetModalState();
  };
  const getExtensionLabel = (extension) => {
    const found = availableExtensions.find((e) => e.extension === extension);
    if (!found) return String(extension);
    return found.name ? `${found.extension} — ${found.name}` : found.extension;
  };
  const allExtensionOptions = useMemo(() => availableExtensions.map(({ extension, name }) => ({
    value: extension, label: name ? `${extension} — ${name}` : extension,
  })), [availableExtensions]);
  const handleSaveGroup = async () => {
    const { name, error } = validateExtensionGroup(groupName, selectedExtensions);
    if (error) return showMessage("error", error);
    const payload = buildExtensionGroupPayload(name, selectedExtensions);
    setLoading((p) => ({ ...p, save: true }));
    setMessage({ type: "", text: "" });
    try {
      const isUpdate = editGroupId != null;
      if (isUpdate) {
        await updateExtensionGroup({ id: editGroupId, ...payload });
      } else {
        await createExtensionGroup(payload);
      }
      await loadGroups();
      handleCloseModal();
      showMessage("success", isUpdate
        ? "Extension group updated successfully."
        : "Extension group created successfully.");
    } catch (err) {
      showMessage("error", err?.message || "Failed to save group.");
    } finally {
      setLoading((p) => ({ ...p, save: false }));
    }
  };

  return {
    allExtensionOptions, allPageSelected, availableExtensions, dataEmpty,
    editGroupId, getExtensionLabel, groupName, groups, handleCloseModal,
    handleDelete, handleOpenAddModal, handleOpenEditModal, handleSaveGroup,
    handleToggleAll, handleToggleRow, isInitialLoad, limit, loading,
    message, modalScrollRef, page, pagedGroups, selectedExtensions,
    selectedIds, setGroupName, setMessage, setPage, setSelectedExtensions,
    showModal, somePageSelected, totalPages,
  };
};

