export const FeatureCodeSectionHeading = ({
  title,
  isFirst = false,
  isCompact = false,
}) => {
  const isLaptopNarrow = useMediaQuery(FEATURE_CODE_LAPTOP_NARROW_MQ);
  const tightenSpacing = isLaptopNarrow || isCompact;
  return (
    <div
      style={{
        margin: isFirst
          ? tightenSpacing
            ? "20px 0 24px 0"
            : "16px 0 24px 0"
          : "28px 0 24px 0",
        position: "relative",
        width: "100%",
      }}
    >
      <div style={{ borderTop: `1px solid ${C.divider}` }} />
