  alignItems: "center",
  gap: 12,
  width: "100%",
};

const centralizedManageFieldControlStyle = {
  flex: 1,
  minWidth: 0,
  width: "100%",
  maxWidth: 280,
};

const centralizedManageFixedAlertSx = {
  position: "fixed",
