      return "Please enter a valid IP address (e.g., 192.168.1.1)";
    }
    const parts = value.split(".");
    for (let part of parts) {
      const num = parseInt(part);
      if (num < 0 || num > 255) {
        return "IP address parts must be between 0 and 255";
      }
    }
    return "";
