      );

      // Configure firewall for SSH
      if (form.sshPort) {
        commands.push(
          `firewall-cmd --permanent --add-port=${form.sshPort}/tcp 2>/dev/null || iptables -A INPUT -p tcp --dport ${form.sshPort} -j ACCEPT 2>/dev/null || true`,
