        }

        // Add warning if system time was changed
        const systemTimeChanged = form.modifyTime && form.systemTime;
        if (systemTimeChanged) {
          const selectedDate = new Date(form.systemTime);
          const currentDate = new Date();
          if (selectedDate > currentDate) {
            message += `\n\n⚠️ Note: If you are logged out, please log back in.\nSystem time changes can affect authentication.`;
          }
        }

        showToast(
          message.trim(),
          failedCommands.length > 0 ? "warning" : "success",
        );

        // If system time was changed, reload page to update navbar immediately
        if (systemTimeChanged) {
          console.log(
            "🔄 System time changed - reloading page to update navbar...",
          );
          setTimeout(() => {
            window.location.reload();
          }, 1500);
        } else {
          // Refresh data after save; keep current form if server reload fails
          await fetchManagementData({ preserveFormOnError: true });
        }
      } else {
        throw new Error(response.message || "Failed to save settings");
      }
    } catch (error) {
      console.error("Error saving management parameters:", error);

      let errorMessage = "Failed to save management settings.";

      if (error.code === "ECONNABORTED" || error.message?.includes("timeout")) {
        errorMessage =
          "Save operation timed out. Please check your connection and try again.";
      } else if (error.response?.status === 400) {
        errorMessage =
          "Invalid configuration. Please check your settings and try again.";
      } else if (error.response?.status >= 500) {
        errorMessage =
          "Server error during save. Please try again later or contact support.";
      } else if (
        error.message?.includes("Network Error") ||
        error.message?.includes("Failed to fetch")
      ) {
        errorMessage =
          "Network connection failed during save. Please check your connection.";
      } else if (error.message) {
        errorMessage = error.message;
      }

      setError(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const handleReset = async () => {
    try {
      setLoading(true);
      setError("");
      setFieldErrors({});

      console.log("Resetting management parameters...");
      const resetResponse = await resetManagementParameters();

      if (resetResponse.response === true) {
        console.log("Reset successful, fetching default values...");
        // After successful reset, fetch the default values
        await fetchManagementData();
        showToast("Management parameters reset successfully.", "success");
      } else {
        throw new Error(resetResponse.message || "Reset operation failed");
      }
    } catch (error) {
      console.error("Error resetting management parameters:", error);

      let errorMessage = "Failed to reset management settings.";

      if (error.code === "ECONNABORTED" || error.message?.includes("timeout")) {
        errorMessage =
          "Reset operation timed out. Please check your connection and try again.";
      } else if (error.response?.status >= 500) {
        errorMessage =
          "Server error during reset. Please try again later or contact support.";
      } else if (
        error.message?.includes("Network Error") ||
        error.message?.includes("Failed to fetch")
      ) {
        errorMessage =
          "Network connection failed during reset. Please check your connection.";
      } else if (error.message) {
        errorMessage = error.message;
      }

      setError(errorMessage);

      // Fallback to initial form values
      setForm(MANAGEMENT_INITIAL_FORM);
      setFormKey((k) => k + 1);
    } finally {
      setLoading(false);
    }
  };

  // Helper to render System Time row with Modify checkbox and date/time input inline
  const renderSystemTimeInline = (field, nextField) => (
    <ManagementFieldRow
      label={field.label}
      tooltipKey={field.name}
      labelColWidth={labelColWidth}
    >
      <div className="flex items-center gap-2 w-full min-w-0">
        <div className="flex items-center gap-2 flex-shrink-0">
          <Checkbox
            name={nextField.name}
            size="small"
            checked={!!form[nextField.name]}
            onChange={handleCheckboxChange(nextField.name)}
            sx={checkboxSx}
          />
          <Tooltip
            title={MANAGEMENT_FIELD_TOOLTIPS.modifyTime}
            {...tooltipProps}
          >
            <span style={{ fontSize: 12, fontWeight: 600, color: C.labelText }}>
              {nextField.label}
            </span>
          </Tooltip>
        </div>
        <input
          type="datetime-local"
          name={field.name}
          className="management-system-time-input"
          value={form[field.name] ? form[field.name].replace(" ", "T") : ""}
          onChange={handleChange}
          readOnly={!form[nextField.name]}
          style={{
            ...(form[nextField.name] ? inputStyle : disabledInputStyle),
            flex: 1,
            minWidth: 0,
            maxWidth: "100%",
            width: "auto",
            borderRadius: FIELD_RADIUS,
            borderColor: fieldErrors[field.name] ? C.errorRed : C.cardBorder,
          }}
          onFocus={
            form[nextField.name] ? inputInteraction.onFocus : undefined
          }
          onBlur={form[nextField.name] ? inputInteraction.onBlur : undefined}
          onMouseEnter={
            form[nextField.name] ? inputInteraction.onMouseEnter : undefined
          }
          onMouseLeave={
            form[nextField.name] ? inputInteraction.onMouseLeave : undefined
          }
          step="1"
        />
      </div>
      {fieldErrors[field.name] && (
        <div style={{ fontSize: 11, color: C.errorRed, marginTop: 4 }}>
          {fieldErrors[field.name]}
        </div>
      )}
    </ManagementFieldRow>
  );

  const renderManagementSection = (section, isFirst) => (
    <React.Fragment key={section.section}>
      <SectionHeading title={section.section} isFirst={isFirst} />

      <div style={managementFieldGroupStyle}>
        {section.fields.map((field, fieldIdx) => {
          if (
            field.conditional &&
            form[field.conditional] !== field.conditionalValue
          ) {
            if (
              Array.isArray(field.conditionalValue) &&
              !field.conditionalValue.includes(form[field.conditional])
            ) {
              return null;
            }
            if (!Array.isArray(field.conditionalValue)) {
              return null;
            }
          }
          if (Array.isArray(field.conditionalAll)) {
            const allOk = field.conditionalAll.every(
              (c) => form[c.name] === c.value,
            );
            if (!allOk) return null;
          }

          if (
            field.name === "systemTime" &&
            section.fields[fieldIdx + 1] &&
            section.fields[fieldIdx + 1].name === "modifyTime"
          ) {
            return renderSystemTimeInline(
              field,
              section.fields[fieldIdx + 1],
            );
          }
          if (
            field.name === "modifyTime" &&
            section.fields[fieldIdx - 1] &&
            section.fields[fieldIdx - 1].name === "systemTime"
          ) {
            return null;
          }

          return (
            <ManagementFieldRow
              key={section.section + field.name}
              label={field.label}
              tooltipKey={field.name}
              labelColWidth={labelColWidth}
            >
                {field.type === "text" && (
                  <div className="flex flex-col gap-1 w-full min-w-0">
                    <input
                      type={
                        field.name === "webPort" ||
                        field.name === "webTimeout" ||
                        field.name === "sshPort" ||
                        field.name === "synchronizingCycle"
                          ? "number"
                          : "text"
                      }
                      name={field.name}
                      value={form[field.name]}
                      onChange={handleChange}
                      style={{
                        ...inputStyle,
                        borderColor: fieldErrors[field.name]
                          ? C.errorRed
                          : C.cardBorder,
                      }}
                      onFocus={inputInteraction.onFocus}
                      onBlur={inputInteraction.onBlur}
                      onMouseEnter={inputInteraction.onMouseEnter}
                      onMouseLeave={inputInteraction.onMouseLeave}
                      min={
                        field.name === "webPort" ||
                        field.name === "webTimeout" ||
                        field.name === "sshPort" ||
                        field.name === "synchronizingCycle"
                          ? 1
                          : undefined
                      }
                      max={
                        field.name === "webTimeout"
                          ? 3600
                          : field.name === "synchronizingCycle"
                            ? 86400
                            : field.name === "webPort" ||
                                field.name === "sshPort"
                              ? 65535
                              : undefined
                      }
                    />
                    {(field.name === "webWhitelist" ||
                      field.name === "sshWhitelist" ||
                      field.name === "ftpWhitelist" ||
                      field.name === "telnetWhitelist") && (
                      <span style={{ fontSize: 11, color: C.mutedText }}>
                        {MANAGEMENT_HINT_WHITELIST_DOT}
                      </span>
                    )}
                    {field.name === "webIpAddress" && (
                      <span style={{ fontSize: 11, color: C.mutedText }}>
                        {MANAGEMENT_HINT_WEB_IP_COMMA}
                      </span>
                    )}
                    {field.unit && (
                      <span style={{ fontSize: 11, color: C.mutedText }}>
                        {field.unit}
                      </span>
                    )}
                    {fieldErrors[field.name] && (
                      <span style={{ fontSize: 11, color: C.errorRed }}>
                        {fieldErrors[field.name]}
                      </span>
                    )}
                  </div>
                )}

                {field.type === "textarea" && (
                  <div className="flex flex-col gap-1 w-full min-w-0">
                    <textarea
                      name={field.name}
                      value={form[field.name]}
                      onChange={handleChange}
                      style={{
                        ...inputStyle,
                        minHeight: 60,
                        resize: "vertical",
                        borderColor: fieldErrors[field.name]
                          ? C.errorRed
                          : C.cardBorder,
                      }}
                      onFocus={inputInteraction.onFocus}
                      onBlur={inputInteraction.onBlur}
                      onMouseEnter={inputInteraction.onMouseEnter}
                      onMouseLeave={inputInteraction.onMouseLeave}
                    />
                    {fieldErrors[field.name] && (
                      <span style={{ fontSize: 11, color: C.errorRed }}>
                        {fieldErrors[field.name]}
                      </span>
                    )}
                  </div>
                )}

                {field.type === "select" && (
                  <div className="flex flex-col gap-1 w-full min-w-0">
                    <select
                      name={field.name}
                      value={form[field.name]}
                      onChange={handleChange}
                      style={{
                        ...selectStyle,
                        borderColor: fieldErrors[field.name]
                          ? C.errorRed
                          : C.cardBorder,
                      }}
                      onFocus={inputInteraction.onFocus}
                      onBlur={inputInteraction.onBlur}
                      onMouseEnter={inputInteraction.onMouseEnter}
                      onMouseLeave={inputInteraction.onMouseLeave}
                    >
                      {(() => {
                        const options =
                          field.name === "captureRtpInterface"
                            ? [
                                {
                                  value: "lan1",
                                  label: lanIps.lan1
                                    ? `LAN1: ${lanIps.lan1}`
                                    : "LAN 1",
                                },
                                {
                                  value: "lan2",
                                  label: lanIps.lan2
                                    ? `LAN2: ${lanIps.lan2}`
                                    : "LAN 2",
                                },
                              ]
                            : field.options;
                        return options.map((opt) => (
                          <option key={opt.value} value={opt.value}>
                            {opt.label}
                          </option>
                        ));
                      })()}
                    </select>
                    {fieldErrors[field.name] && (
                      <span style={{ fontSize: 11, color: C.errorRed }}>
                        {fieldErrors[field.name]}
                      </span>
                    )}
                  </div>
                )}

                {field.type === "radio" && (
                  <div className="flex flex-wrap items-center gap-4">
                    {field.options.map((opt) => (
                      <label
                        key={opt}
                        className="flex items-center gap-1 cursor-pointer"
                      >
                        <input
                          type="radio"
                          name={field.name}
                          value={opt}
                          checked={form[field.name] === opt}
                          onChange={handleChange}
                          style={{ accentColor: OUTLINED_FOCUS }}
                        />
                        <span style={{ fontSize: 13, color: C.labelText }}>
                          {opt}
                        </span>
                      </label>
                    ))}
                  </div>
                )}

                {field.type === "checkbox" && (
                  <div className="flex items-center min-h-[32px]">
                    <Checkbox
                      name={field.name}
                      size="small"
                      checked={!!form[field.name]}
                      onChange={handleCheckboxChange(field.name)}
                      sx={checkboxSx}
                    />
                  </div>
                )}
            </ManagementFieldRow>
          );
        })}
      </div>
    </React.Fragment>
  );

  const leftSections = MANAGEMENT_SECTIONS.filter((s) =>
    MANAGEMENT_LEFT_SECTION_SET.has(s.section),
  );
  const rightSections = MANAGEMENT_SECTIONS.filter(
    (s) => !MANAGEMENT_LEFT_SECTION_SET.has(s.section),
  );

  return (
    <ManagementPageShell isCompact={isCompact}>
      <ManagementScrollbarStyles />
      {error && (
        <Alert
          severity="error"
          onClose={() => setError("")}
          sx={managementFixedAlertSx}
        >
          {typeof error === "string" ? error : JSON.stringify(error)}
        </Alert>
      )}

      {toast.msg && (
        <Alert
          severity={toast.type}
          onClose={() => setToast({ msg: "", type: "success" })}
          sx={{
            ...managementFixedAlertSx,
            top: error ? 88 : 20,
            whiteSpace: "pre-line",
          }}
        >
          {toast.msg}
        </Alert>
      )}

      <ManagementBreadcrumb />

      <div style={managementTableContainerStyle}>
          <div style={managementHeaderStyle}>
            <span>{MANAGEMENT_CARD_TITLE}</span>
          </div>

          <div style={{ padding: 0, boxSizing: "border-box" }}>
          {loading ? (
            <div
              className="flex items-center justify-center w-full"
              style={{ minHeight: 400, padding: "48px 32px" }}
            >
              <div className="text-center">
                <CircularProgress size={40} sx={{ color: C.accent }} />
                <div
                  style={{
                    marginTop: 12,
                    fontSize: 13,
                    color: C.mutedText,
                    fontWeight: 500,
                  }}
                >
                  {MANAGEMENT_LOADING_TEXT}
                </div>
              </div>
            </div>
          ) : (
            <>
              <form
                id="management-form"
                key={formKey}
                onSubmit={handleSave}
                className="flex flex-col gap-2"
              >
                <div
                  className="settings-dashboard-grid"
                  style={managementDashboardGridStyle(isCompact)}
                >
                  <div style={managementDashboardColumnStyle(isCompact)}>
                    <div style={managementDashboardFieldsStackStyle}>
                      {leftSections.map((section, idx) =>
                        renderManagementSection(section, idx === 0),
                      )}
                    </div>
                  </div>

                  {!isCompact && (
                    <div
                      className="settings-dashboard-divider"
                      style={managementDashboardDividerCellStyle}
                      aria-hidden="true"
                    >
                      <div style={managementDashboardDividerLineStyle} />
                    </div>
                  )}

                  <div style={managementDashboardColumnStyle(isCompact)}>
                    <div style={managementDashboardFieldsStackStyle}>
                      {rightSections.map((section, idx) =>
                        renderManagementSection(section, idx === 0),
                      )}
                    </div>
                  </div>
                </div>
              </form>

              <div style={advancedFormInlineFooterStyle}>
                <Btn
                  variant="primary"
                  type="submit"
                  form="management-form"
                  disabled={loading}
                  style={advancedFormBtnStyle}
                >
                  {MANAGEMENT_BTN_SAVE}
                </Btn>
                <Btn
                  variant="cancel"
                  type="button"
                  onClick={handleReset}
                  disabled={loading}
                  style={advancedFormBtnStyle}
                >
                  {MANAGEMENT_BTN_RESET}
                </Btn>
              </div>
            </>
          )}
          </div>
        </div>
    </ManagementPageShell>
  );
};

export default Management;

