const FieldRow = ({ name, label, children }) => {
  const tooltip = PING_TEST_FIELD_TOOLTIPS[name];
  const labelNode = (
    <label
      style={{
        fontSize: 13,
        fontWeight: 600,
        color: C.labelText,
        width: "100%",
        lineHeight: 1.4,
        wordBreak: "break-word",
