          height: 32,
          padding: "0 8px",
          boxSizing: "border-box",
        },
      }}
      sx={modalTextFieldSx}
    />
  );

  const renderSelect = (value, onChange, options) => (
    <Select
      value={value}
      onChange={(e) => onChange(e.target.value)}
      size="small"
      fullWidth
      variant="outlined"
      sx={modalSelectSx}
