const TRACERT_TEST_LABEL_COL_WIDTH = 188;
const TRACERT_TEST_FIELD_COL_GAP = 16;
const TRACERT_TEST_FORM_PAD_X = 28;

const C = {
  cardBg: "#ffffff",
  cardBorder: "#d8dde5",
  cardShadow:
    "0 0 14px rgba(0, 0, 0, 0.18), 0 0 5px rgba(0, 0, 0, 0.10)",
