  width: TRACERT_TEST_LABEL_COL_WIDTH,
  minWidth: TRACERT_TEST_LABEL_COL_WIDTH,
  maxWidth: TRACERT_TEST_LABEL_COL_WIDTH,
  paddingTop: 9,
};

const tracertFieldControlWrapStyle = {
  flex: "1 1 auto",
  minWidth: 0,
  width: "100%",
};

const tracertFooterBtnStyle = {
  height: 30,
  padding: "6px 14px",
