const TracertPageShell = ({ children }) => (
  <>
    <TracertScrollbarStyles />
    <div
      className={TRACERT_TEST_SCROLL_CLASS}
      style={tracertPageWrapStyle}
      data-native-scroll
    >
      <div style={tracertPageInnerStyle}>{children}</div>
    </div>
