);

const TracertBreadcrumb = () => (
  <div
    style={{
      fontSize: 12,
      color: "#94a3b8",
      marginBottom: 16,
      fontWeight: 400,
      display: "flex",
      alignItems: "center",
      gap: 4,
      flexWrap: "wrap",
      flexShrink: 0,
    }}
  >
    <span>{TRACERT_TEST_PAGE_BREADCRUMB_ROOT}</span>
    <span>&gt;</span>
    <span>{TRACERT_TEST_PAGE_BREADCRUMB_SECTION}</span>
    <span>&gt;</span>
    <span style={{ color: "#1e293b", fontWeight: 600 }}>
      {TRACERT_TEST_PAGE_TITLE}
    </span>
  </div>
);

function isValidIp(ip) {
  return /^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/.test(
    ip,
  );
}

function isValidJumps(val) {
  const num = Number(val);
  return Number.isInteger(num) && num >= 1 && num <= 255;
}

const TRACERTTest = () => {
  const isCompact = useMediaQuery(TRACERT_TEST_COMPACT_MQ);
  const outputRef = useRef(null);
  const [sourceIp, setSourceIp] = useState("");
  const [destIp, setDestIp] = useState("");
  const [maxJumps, setMaxJumps] = useState("");
  const [info, setInfo] = useState("");
  const [error, setError] = useState(false);
  const [loading, setLoading] = useState(false);
  const [toast, setToast] = useState({ msg: "", type: "success" });
  const intervalRef = useRef(null);
  const [sourceIpError, setSourceIpError] = useState("");
  const [destIpError, setDestIpError] = useState("");
  const [jumpsError, setJumpsError] = useState("");
  const [sourceOptions, setSourceOptions] = useState([]);
  const [loadingSource, setLoadingSource] = useState(true);

  useEffect(() => {
    if (!outputRef.current || !info) return;
    outputRef.current.scrollTop = outputRef.current.scrollHeight;
  }, [info]);

  const showToast = (msg, type = "success") => {
    setToast({ msg, type });
    setTimeout(() => setToast({ msg: "", type: "success" }), 3500);
  };

  useEffect(() => {
    const loadSourceOptions = async () => {
      try {
        setLoadingSource(true);
        const netData = await fetchNetwork();
        const allIfaces = netData?.data?.interfaces || [];

        const lanIfaces = allIfaces.filter((i) => {
          const kn = (i.interface || "").toLowerCase();
          return /^eth\d+$/.test(kn) || /^enp\d+s\d+/.test(kn);
        });

        const options = lanIfaces
          .filter((i) => i.ipAddress)
          .map((iface, idx) => ({
            value: iface.ipAddress,
            label: `LAN ${idx + 1}:${iface.ipAddress}`,
          }));

        const primaryKernel = lanIfaces[0]?.interface || "eth0";
        for (const iface of allIfaces) {
          const kn = (iface.interface || "").toString();
          if (
            kn.startsWith(`${primaryKernel}.`) &&
            /\.\d+$/.test(kn) &&
            iface.ipAddress
          ) {
            const vlanId = kn.split(".")[1] || "";
            options.push({
              value: iface.ipAddress,
              label: `VLAN ${vlanId}:${iface.ipAddress}`,
            });
          }
        }

        const lanIfaceSet = new Set(lanIfaces.map((i) => i.interface));
        for (const iface of allIfaces) {
          const kn = (iface.interface || "").toLowerCase();
          if (
            iface.ipAddress &&
            !lanIfaceSet.has(iface.interface) &&
            kn !== "lo" &&
            !/^eth\d+\.\d+$/.test(kn)
          ) {
            options.push({
              value: iface.ipAddress,
              label: `VPN (${iface.interface}):${iface.ipAddress}`,
            });
          }
        }

        if (options.length > 0) {
          setSourceOptions(options);
          setSourceIp(options[0].value);
        } else {
          setSourceOptions(TRACERT_SOURCE_OPTIONS);
          setSourceIp(TRACERT_SOURCE_OPTIONS[0]?.value || "");
        }
      } catch (err) {
        console.error("Error fetching network interfaces:", err);
        setSourceOptions(TRACERT_SOURCE_OPTIONS);
        setSourceIp(TRACERT_SOURCE_OPTIONS[0]?.value || "");
      } finally {
        setLoadingSource(false);
      }
    };

    loadSourceOptions();
  }, []);

  const startTracert = async () => {
    setSourceIpError("");
    setDestIpError("");
    setJumpsError("");
    let valid = true;
    if (!isValidIp(sourceIp)) {
      setSourceIpError(TRACERT_TEST_ERR_INVALID_SOURCE_IP);
      valid = false;
    }
    if (!isValidIp(destIp)) {
      setDestIpError(TRACERT_TEST_ERR_INVALID_DEST_IP);
      valid = false;
    }
    if (maxJumps && !isValidJumps(maxJumps)) {
      setJumpsError(TRACERT_TEST_ERR_INVALID_JUMPS);
      valid = false;
    }
    if (!valid) {
      showToast(TRACERT_TEST_ERR_FIX_BEFORE_START, "error");
      return;
    }
    setLoading(true);
    if (!maxJumps) {
      if (!intervalRef.current) {
        const success = await handleTracert();
        if (success) {
          intervalRef.current = setInterval(() => {
            handleTracert();
          }, 2000);
          showToast(TRACERT_TEST_TOAST_CONTINUOUS_STARTED, "success");
        } else {
          setLoading(false);
        }
      } else {
        showToast(TRACERT_TEST_TOAST_ALREADY_RUNNING, "warning");
        setLoading(false);
      }
    } else {
      showToast(TRACERT_TEST_TOAST_STARTED, "info");
      const success = await handleTracert();
      setLoading(false);
      if (success) {
        showToast(TRACERT_TEST_TOAST_COMPLETED, "success");
      }
    }
  };

  const stopTracertInterval = () => {
    const wasRunning = !!intervalRef.current || loading;
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
    setLoading(false);
    if (wasRunning) {
      showToast(TRACERT_TEST_TOAST_STOPPED, "success");
    } else {
      showToast(TRACERT_TEST_TOAST_NOT_RUNNING, "warning");
    }
  };

  const stopTracertOnError = () => {
    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
    setLoading(false);
  };

  const handleTracert = async () => {
    setError(false);
    try {
      const Apiresponse = await postTracerttest({
        destIp,
        maxJumps,
        sourceIp,
      });
      console.log("Tracert API Response:", Apiresponse);

      if (Apiresponse.response) {
        if (maxJumps) {
          setInfo(Apiresponse.responseData);
        } else {
          setInfo((prev) =>
            prev
              ? prev + "\n" + Apiresponse.responseData
              : Apiresponse.responseData,
          );
        }
        return true;
      }

      setInfo((prev) =>
        prev
          ? prev + "\n" + (Apiresponse.message || TRACERT_TEST_TOAST_SERVER_ERROR)
          : Apiresponse.message || TRACERT_TEST_TOAST_SERVER_ERROR,
      );
      showToast(Apiresponse.message || TRACERT_TEST_TOAST_SERVER_ERROR, "error");
      stopTracertOnError();
      return false;
    } catch (err) {
      console.error("Tracert API Error:", err);
      showToast(TRACERT_TEST_TOAST_CONNECTION_ERROR, "error");
      setError(true);
      stopTracertOnError();
      return false;
    }
  };

  const clearOutput = () => {
    setInfo("");
  };

  return (
    <TracertPageShell>
      {toast.msg && (
        <Alert
          severity={toast.type}
          onClose={() => setToast({ msg: "", type: "success" })}
          sx={tracertFixedAlertSx}
        >
          {toast.msg}
        </Alert>
      )}

      <TracertBreadcrumb />

      <div>
        <div style={tracertTableContainerStyle}>
          <div style={tracertHeaderStyle}>
            <span>{TRACERT_TEST_CARD_TITLE}</span>
          </div>

          <div style={tracertBodyStyle}>
            <div style={tracertConfigPanelStyle}>
              <div style={tracertConfigHeaderStyle}>
                <PanelTitle title={TRACERT_TEST_SECTION_CONFIG} />
                <div style={tracertConfigActionsStyle}>
                  <Btn
                    variant="cancel"
                    onClick={stopTracertInterval}
                    disabled={!loading}
                    style={tracertFooterBtnStyle}
                  >
                    {TRACERT_BUTTONS.end}
                  </Btn>
                  <Btn
                    variant="primary"
                    onClick={startTracert}
                    disabled={loading || !destIp.trim()}
                    style={tracertFooterBtnStyle}
                  >
                    {loading ? (
                      <span
                        style={{
                          display: "inline-flex",
                          alignItems: "center",
                          gap: 8,
                        }}
                      >
                        <CircularProgress size={12} color="inherit" />
                        {TRACERT_BUTTONS.loading}
                      </span>
                    ) : (
                      TRACERT_BUTTONS.start
                    )}
                  </Btn>
                </div>
              </div>

              <div style={tracertConfigBodyStyle}>
                <div style={tracertFieldsGridStyle(isCompact)}>
                  <div style={tracertFieldsColumnStyle}>
                    <FieldRow name="sourceIp" label={TRACERT_LABELS.sourceIp}>
                      <select
                        style={selectStyle}
                        value={sourceIp}
                        onChange={(e) => {
                          setSourceIp(e.target.value);
                          setInfo("");
                          setSourceIpError("");
                        }}
                        disabled={loadingSource}
                        {...inputInteraction}
                      >
                        {loadingSource ? (
                          <option value="">{TRACERT_TEST_SOURCE_LOADING}</option>
                        ) : (
                          sourceOptions.map((opt) => (
                            <option key={opt.value} value={opt.value}>
                              {opt.label}
                            </option>
                          ))
                        )}
                      </select>
                      {sourceIpError ? (
                        <div style={tracertFieldErrorStyle}>{sourceIpError}</div>
                      ) : null}
                    </FieldRow>

                    <FieldRow name="destIp" label={TRACERT_LABELS.destIp}>
                      <input
                        type="text"
                        style={inputStyle}
                        value={destIp}
                        onChange={(e) => {
                          setDestIp(e.target.value);
                          setInfo("");
                          setDestIpError("");
                        }}
                        placeholder="e.g. 8.8.8.8"
                        {...inputInteraction}
                      />
                      {destIpError ? (
                        <div style={tracertFieldErrorStyle}>{destIpError}</div>
                      ) : null}
                    </FieldRow>
                  </div>

                  <div style={tracertFieldsColumnStyle}>
                    <FieldRow name="maxJumps" label={TRACERT_LABELS.maxJumps}>
                      <input
                        type="number"
                        style={inputStyle}
                        value={maxJumps}
                        onChange={(e) => {
                          setMaxJumps(e.target.value);
                          setInfo("");
                          setJumpsError("");
                        }}
                        placeholder="30"
                        {...inputInteraction}
                      />
                      {jumpsError ? (
                        <div style={tracertFieldErrorStyle}>{jumpsError}</div>
                      ) : null}
                    </FieldRow>
                  </div>
                </div>
              </div>
            </div>

            <div style={tracertOutputPanelStyle}>
              <div style={tracertOutputHeaderStyle}>
                <span
                  style={{
                    fontSize: 14,
                    fontWeight: 600,
                    color: C.sectionHeading,
                  }}
                >
                  {TRACERT_TEST_SECTION_OUTPUT}
                </span>
                <Btn
                  variant="cancel"
                  onClick={clearOutput}
                  disabled={!info || loading}
                  style={tracertClearBtnStyle}
                >
                  {TRACERT_TEST_BTN_CLEAR}
                </Btn>
              </div>
              <div style={tracertOutputBodyStyle}>
                <textarea
                  ref={outputRef}
                  className={TRACERT_TEST_SCROLL_CLASS}
                  style={tracertOutputTextareaStyle}
                  value={info}
                  readOnly
                  tabIndex={-1}
                  placeholder={TRACERT_TEST_OUTPUT_PLACEHOLDER}
                  onFocus={(e) => e.target.blur()}
                />
              </div>
            </div>
          </div>
        </div>
      </div>
    </TracertPageShell>
  );
};

export default TRACERTTest;

import React, { useState, useEffect } from 'react';
import {
  VPN_ACCOUNT_TABLE_COLUMNS,
  VPN_ACCOUNT_FIELDS,
  VPN_ACCOUNT_INITIAL_FORM
} from '../../../constants/VpnAccountConstants';
import EditDocumentIcon from '@mui/icons-material/EditDocument';
import { Button, TextField, Dialog, DialogTitle, DialogContent, DialogActions } from '@mui/material';

const localStorageKey = 'vpnAccounts';

const grayButtonSx = {
  background: 'linear-gradient(to bottom, #e3e7ef 0%, #bfc6d1 100%)',
  color: '#222',
  fontWeight: 600,
  fontSize: 15,
  borderRadius: '4px',
  minWidth: 110,
  boxShadow: '0 1px 2px rgba(0,0,0,0.10)',
  textTransform: 'none',
  px: 2.25,
  py: 1,
  padding: '4px 18px',
  border: '1px solid #bbb',
  '&:hover': {
    background: 'linear-gradient(to bottom, #bfc6d1 0%, #e3e7ef 100%)',
    color: '#222',
  },
};
const blueButtonSx = {
  background: 'linear-gradient(to bottom, #3bb6f5 0%, #0e8fd6 100%)',
  color: '#fff',
  fontWeight: 600,
  fontSize: 16,
  borderRadius: '4px',
  minWidth: 120,
  boxShadow: '0 2px 6px #0002',
  textTransform: 'none',
  px: 3,
  py: 1.5,
  padding: '6px 28px',
  border: '1px solid #0e8fd6',
  '&:hover': {
    background: 'linear-gradient(to bottom, #0e8fd6 0%, #3bb6f5 100%)',
    color: '#fff',
  },
};

const VpnAccount = () => {
  const [accounts, setAccounts] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [form, setForm] = useState(VPN_ACCOUNT_INITIAL_FORM);
  const [editIndex, setEditIndex] = useState(null);
  const [checked, setChecked] = useState([]);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    const saved = localStorage.getItem(localStorageKey);
    if (saved) setAccounts(JSON.parse(saved));
  }, []);

  useEffect(() => {
    setChecked([]);
  }, [accounts.length]);

  const handleAddNew = () => {
    setForm(VPN_ACCOUNT_INITIAL_FORM);
    setEditIndex(null);
    setShowModal(true);
  };

  const handleEdit = (idx) => {
    setForm(accounts[idx]);
    setEditIndex(idx);
    setShowModal(true);
  };

  const handleModalChange = (e) => {
    const { name, value, type } = e.target;
    setForm((prev) => ({
      ...prev,
      [name]: type === 'number' ? Number(value) : value,
    }));
  };

  const handleModalSave = (e) => {
    e.preventDefault();
    const newErrors = {};
    if (!form.username) newErrors.username = 'Username is required.';
    if (!form.password) newErrors.password = 'Password is required.';
    setErrors(newErrors);
    if (Object.keys(newErrors).length > 0) return;
    let newAccounts;
    if (editIndex !== null) {
      newAccounts = accounts.map((acc, idx) => idx === editIndex ? form : acc);
    } else {
      newAccounts = [...accounts, form];
    }
    setAccounts(newAccounts);
    localStorage.setItem(localStorageKey, JSON.stringify(newAccounts));
    setShowModal(false);
    setEditIndex(null);
    setErrors({});
  };

  const handleModalClose = () => {
    setShowModal(false);
  };

  const isAllChecked = accounts.length > 0 && checked.length === accounts.length;
  const isIndeterminate = checked.length > 0 && checked.length < accounts.length;

  const handleCheck = (idx) => {
    setChecked((prev) =>
      prev.includes(idx) ? prev.filter((i) => i !== idx) : [...prev, idx]
    );
  };

  const handleCheckAll = () => {
    setChecked(accounts.map((_, idx) => idx));
  };

  const handleUncheckAll = () => {
    setChecked([]);
  };

  const handleInverse = () => {
    setChecked(accounts.map((_, idx) => (checked.includes(idx) ? null : idx)).filter((i) => i !== null));
  };

  const handleDelete = () => {
    const newAccounts = accounts.filter((_, idx) => !checked.includes(idx));
    setAccounts(newAccounts);
    localStorage.setItem(localStorageKey, JSON.stringify(newAccounts));
    setChecked([]);
  };

  const handleClearAll = () => {
    setAccounts([]);
    localStorage.removeItem(localStorageKey);
    setChecked([]);
  };

  return (
    <div className="bg-gray-50 min-h-[calc(100vh-80px)] py-10 flex flex-col items-center">
      {accounts.length === 0 ? (
        <>
          <div className="text-gray-800 font-semibold text-2xl mt-8 mb-4">No Available Information!</div>
          <Button
            variant="contained"
            sx={blueButtonSx}
            onClick={handleAddNew}
          >
            Add New
          </Button>
        </>
      ) : (
        <div className="w-full max-w-4xl mx-auto">
          <div className="bg-white border-2 border-gray-400 rounded-t-xl shadow">
            <div className="w-full bg-gradient-to-b from-[#b3e0ff] via-[#6ec1f7] to-[#3b8fd6] h-10 flex items-center justify-center font-semibold text-lg text-black shadow mb-0 border-b-2 border-[#b3e0ff] rounded-t-xl">
              VPN Account
            </div>
            <div className="w-full overflow-x-auto">
              <table className="min-w-full border-collapse table-auto">
                <thead>
                  <tr>
                    <th className="bg-white text-gray-800 font-semibold text-sm border border-gray-300 px-2 py-1 whitespace-nowrap text-center">Check</th>
                    {VPN_ACCOUNT_TABLE_COLUMNS.map((col) => (
                      <th key={col.key} className="bg-white text-gray-800 font-semibold text-sm border border-gray-300 px-2 py-1 whitespace-nowrap text-center">{col.label}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {accounts.map((row, idx) => (
                    <tr key={idx}>
                      <td className="border border-gray-300 px-2 py-1 text-center">
                        <input
                          type="checkbox"
                          className="w-5 h-5"
                          checked={checked.includes(idx)}
                          onChange={() => handleCheck(idx)}
                        />
                      </td>
                      {VPN_ACCOUNT_TABLE_COLUMNS.map((col) => (
                        col.key === 'modify' ? (
                          <td key={col.key} className="border border-gray-300 px-2 py-1 text-center"><EditDocumentIcon style={{ cursor: 'pointer', color: '#0e8fd6', display: 'block', margin: '0 auto' }} onClick={() => handleEdit(idx)} /></td>
                        ) : (
                          <td key={col.key} className="border border-gray-300 px-2 py-1 text-center">{row[col.key]}</td>
                        )
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
          <div className="bg-[#e3e7ef] rounded-b-xl flex flex-col sm:flex-row justify-between items-center gap-2 mt-0 px-2 py-4" style={{ borderTopLeftRadius: 0, borderTopRightRadius: 0 }}>
            <div className="flex flex-wrap gap-2 mb-2 sm:mb-0">
              <Button variant="contained" sx={grayButtonSx} onClick={handleCheckAll}>Check All</Button>
              <Button variant="contained" sx={grayButtonSx} onClick={handleUncheckAll}>Uncheck All</Button>
              <Button variant="contained" sx={grayButtonSx} onClick={handleInverse}>Inverse</Button>
              <Button variant="contained" sx={grayButtonSx} onClick={handleDelete}>Delete</Button>
              <Button variant="contained" sx={grayButtonSx} onClick={handleClearAll}>Clear All</Button>
            </div>
            <Button
              variant="contained"
              sx={blueButtonSx}
              onClick={handleAddNew}
            >
              Add New
            </Button>
          </div>
        </div>
      )}
      <Dialog open={showModal} onClose={handleModalClose} maxWidth="xs" fullWidth>
        <DialogTitle className="bg-gradient-to-b from-gray-800 to-gray-600 text-white text-center font-semibold p-3 text-base">VPN Account</DialogTitle>
        <DialogContent className="bg-[#e6eaf0] flex flex-col gap-2 py-4">
          {VPN_ACCOUNT_FIELDS.map((field, i) => (
            <div key={field.name} className={`flex flex-col sm:flex-row items-center gap-2 mb-2 w-full max-w-xs mx-auto${i === 0 ? ' mt-4' : ''}`}>
              <div className="font-medium text-base text-gray-800 w-full sm:w-1/2 text-right sm:pr-4">{field.label}</div>
              <div className="w-full">
                <TextField
                  type={field.type}
                  name={field.name}
                  value={form[field.name]}
                  min={field.min}
                  onChange={handleModalChange}
                  size="small"
                  fullWidth
                  variant="outlined"
                  required
                  error={!!errors[field.name]}
                  helperText={errors[field.name] || ''}
                />
              </div>
            </div>
          ))}
        </DialogContent>
        <DialogActions className="flex justify-center gap-6 pb-4">
          <Button variant="contained" sx={blueButtonSx} onClick={handleModalSave}>Save</Button>
          <Button variant="contained" sx={blueButtonSx} onClick={handleModalClose}>Close</Button>
        </DialogActions>
      </Dialog>
    </div>
  );
};

