          "success",
          "OpenVPN configuration file uploaded successfully!",
        );
        setSelectedFile(null);
        setForm((prev) => ({ ...prev, vpnCertName: "No file chosen" }));

        // Auto-start VPN after a successful upload
        try {
          setLoading((prev) => ({ ...prev, start: true }));
