                } else if (
                  statusLower.includes("stopped") ||
                  statusLower.includes("offline") ||
                  statusLower.includes("disconnected")
                ) {
                  setSeStatus("Stopped");
                } else if (
                  statusLower.includes("connecting") ||
                  statusLower.includes("retrying")
