    seForm, setSeForm, authMethod, setAuthMethod, seCertFile, setSeCertFile, seKeyFile, setSeKeyFile, seStatus, setSeStatus, seAccounts, setSeAccounts, seLogs, setSeLogs, isProfileCreated, setIsProfileCreated,
