// ConfirmDialog removed in favor of window.confirm

const AccountManage = () => {
  const { user: currentUser, canWrite, showReadOnlyToast } = useAuth();
  const [accounts, setAccounts] = useState([]);
  const [selected, setSelected] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState(ACCOUNT_MANAGE_INITIAL_FORM);
  const [editIdx, setEditIdx] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [toast, setToast] = useState(ACCOUNT_MANAGE_DEFAULT_TOAST);

  const showToast = (msg, type = "success") => {
    setToast({ msg, type });
    setTimeout(
      () => setToast(ACCOUNT_MANAGE_DEFAULT_TOAST),
      ACCOUNT_MANAGE_TOAST_DURATION_MS,
    );
  };

  // Auto-hide error after 5 seconds
  useEffect(() => {
    if (error) {
      const timer = setTimeout(
        () => setError(null),
        ACCOUNT_MANAGE_ERROR_HIDE_MS,
      );
      return () => clearTimeout(timer);
    }
  }, [error]);

  // Fetch all users on component mount
  useEffect(() => {
    fetchAllUsers();
  }, []);

  // API Functions
  const fetchAllUsers = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetchAccountManageGetAll();

      if (response && response.response === true && response.data) {
        const usersWithAdminFlag = response.data.map((user) => ({
          ...user,
          isAdmin: user.username?.toLowerCase() === "admin",
        }));

        setAccounts(usersWithAdminFlag);
      } else {
        throw new Error(response?.message || "Failed to fetch users");
      }
    } catch (error) {
      console.error("Error fetching users:", error);

      // Handle different types of errors
      if (error.code === "ECONNABORTED" || error.message?.includes("timeout")) {
        setError(ACCOUNT_MANAGE_MESSAGES.loadTimeout);
      } else if (error.response?.status === 404) {
        setError(ACCOUNT_MANAGE_MESSAGES.loadNotFound);
      } else if (error.response?.status >= 500) {
        setError(ACCOUNT_MANAGE_MESSAGES.loadServerError);
      } else if (
        error.message?.includes("Network Error") ||
        error.message?.includes("Failed to fetch")
      ) {
        setError(ACCOUNT_MANAGE_MESSAGES.loadNetworkError);
      } else {
        setError(error.message || ACCOUNT_MANAGE_MESSAGES.loadFailed);
      }

      setAccounts([]);
    } finally {
      setLoading(false);
    }
  };

  const saveUser = async (userData) => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetchAccountManageRegister(userData);

      if (response && response.response === true) {
        // Refresh the user list after successful save
        await fetchAllUsers();
        showToast(ACCOUNT_MANAGE_MESSAGES.saveSuccess);
        return true;
      } else {
        throw new Error(response?.message || "Failed to save user");
      }
    } catch (error) {
      console.error("Error saving user:", error);

      let errorMessage = ACCOUNT_MANAGE_MESSAGES.saveFailed;

      if (error.code === "ECONNABORTED" || error.message?.includes("timeout")) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.saveTimeout;
      } else if (error.response?.status === 400) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.saveInvalid;
      } else if (error.response?.status >= 500) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.saveServerError;
      } else if (
        error.message?.includes("Network Error") ||
        error.message?.includes("Failed to fetch")
      ) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.saveNetworkError;
      } else if (error.message) {
        errorMessage = error.message;
      }

      setError(errorMessage);
      return false;
    } finally {
      setLoading(false);
    }
  };

  const updateUser = async (userData) => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetchAccountManageUpdate(userData);

      if (response && response.response === true) {
        // Refresh the user list after successful update
        await fetchAllUsers();
        showToast(ACCOUNT_MANAGE_MESSAGES.updateSuccess);
        return true;
      } else {
        throw new Error(response?.message || "Failed to update user");
      }
    } catch (error) {
      console.error("Error updating user:", error);

      let errorMessage = ACCOUNT_MANAGE_MESSAGES.updateFailed;

      if (error.code === "ECONNABORTED" || error.message?.includes("timeout")) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.updateTimeout;
      } else if (error.response?.status === 400) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.updateInvalid;
      } else if (error.response?.status >= 500) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.updateServerError;
      } else if (
        error.message?.includes("Network Error") ||
        error.message?.includes("Failed to fetch")
      ) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.updateNetworkError;
      } else if (error.message) {
        errorMessage = error.message;
      }

      setError(errorMessage);
      return false;
    } finally {
      setLoading(false);
    }
  };

  const deleteUser = async (userData) => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetchAccountManageDelete(userData);

      if (response && response.response === true) {
        await fetchAllUsers();
        const skipped = response.data?.skipped ?? [];
        if (skipped.length > 0) {
          showToast(
            ACCOUNT_MANAGE_MESSAGES.deleteSkipped(
              skipped.map((u) => u.username),
            ),
            "warning",
          );
        } else {
          showToast(ACCOUNT_MANAGE_MESSAGES.deleteSuccess);
        }
        return true;
      } else {
        throw new Error(response?.message || "Failed to delete user");
      }
    } catch (error) {
      console.error("Error deleting user:", error);

      let errorMessage = ACCOUNT_MANAGE_MESSAGES.deleteFailed;

      if (error.code === "ECONNABORTED" || error.message?.includes("timeout")) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.deleteTimeout;
      } else if (error.response?.status === 400) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.deleteInvalid;
      } else if (error.response?.status >= 500) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.deleteServerError;
      } else if (
        error.message?.includes("Network Error") ||
        error.message?.includes("Failed to fetch")
      ) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.deleteNetworkError;
      } else if (error.message) {
        errorMessage = error.message;
      }

      setError(errorMessage);
      return false;
    } finally {
      setLoading(false);
    }
  };

  const deleteAllUsers = async () => {
    try {
      setLoading(true);
      setError(null);

      // Send all current users data for deletion (excluding current user)
      const allUsersData = accounts
        .filter((user) => !user.isAdmin)
        .map((user) => ({ id: user.id, username: user.username }));

      const response = await fetchAccountManageDelete({ users: allUsersData });

      if (response && response.response === true) {
        setAccounts([]);
        setSelected([]);
        showToast(ACCOUNT_MANAGE_MESSAGES.clearAllSuccess);
        return true;
      } else {
        throw new Error(response?.message || "Failed to clear all users");
      }
    } catch (error) {
      console.error("Error clearing all users:", error);

      let errorMessage = ACCOUNT_MANAGE_MESSAGES.clearAllFailed;

      if (error.code === "ECONNABORTED" || error.message?.includes("timeout")) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.clearAllTimeout;
      } else if (error.response?.status === 400) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.clearAllInvalid;
      } else if (error.response?.status >= 500) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.clearAllServerError;
      } else if (
        error.message?.includes("Network Error") ||
        error.message?.includes("Failed to fetch")
      ) {
        errorMessage = ACCOUNT_MANAGE_MESSAGES.clearAllNetworkError;
      } else if (error.message) {
        errorMessage = error.message;
      }

      setError(errorMessage);
      return false;
    } finally {
      setLoading(false);
    }
  };

  // Create combined accounts list with current user at the top
  const combinedAccounts = accounts;

  // Table row selection logic
  const handleSelectRow = (idx) => {
    setSelected((sel) =>
      sel.includes(idx) ? sel.filter((i) => i !== idx) : [...sel, idx],
    );
  };
  const pageSelectableIndices = combinedAccounts
    .map((_, idx) => idx)
    .filter((idx) => !combinedAccounts[idx].isAdmin);

  const allPageSelected =
    pageSelectableIndices.length > 0 &&
    pageSelectableIndices.every((idx) => selected.includes(idx));

  const somePageSelected =
    pageSelectableIndices.some((idx) => selected.includes(idx)) &&
    !allPageSelected;

  const handleToggleAll = () => {
    if (!pageSelectableIndices.length) return;
    setSelected((prev) =>
      allPageSelected
        ? prev.filter((id) => !pageSelectableIndices.includes(id))
        : Array.from(new Set([...prev, ...pageSelectableIndices])),
    );
  };

  const handleInverse = () => {
    const selectableIndices = combinedAccounts
      .map((_, idx) => idx)
      .filter((idx) => !combinedAccounts[idx].isAdmin);
    setSelected(selectableIndices.filter((i) => !selected.includes(i)));
  };

  const handleDelete = async () => {
    if (selected.length === 0) {
      setError(ACCOUNT_MANAGE_MESSAGES.deleteSelectRequired);
      return;
    }

    const selectedUsers = selected
      .map((idx) => combinedAccounts[idx])
      .filter((user) => !user.isAdmin)
      .map((user) => ({ id: user.id, username: user.username }));

    if (selectedUsers.length === 0) {
      showToast(ACCOUNT_MANAGE_MESSAGES.adminCannotDelete, "error");
      return;
    }

    const isConfirmed = window.confirm(
      ACCOUNT_MANAGE_MESSAGES.deleteConfirm(selectedUsers.length),
    );
    if (isConfirmed) {
      const success = await deleteUser({ users: selectedUsers });
      if (success) {
        setSelected([]);
      }
    }
  };

  const handleClearAll = async () => {
    if (accounts.length === 0) {
      setError(ACCOUNT_MANAGE_MESSAGES.clearAllEmpty);
      return;
    }

    const isConfirmed = window.confirm(ACCOUNT_MANAGE_MESSAGES.clearAllConfirm);
    if (isConfirmed) {
      await deleteAllUsers();
    }
  };

  // Modal logic
  const handleOpenModal = (item = null, idx = null) => {
    if (item) {
      // Don't allow editing current user
      if (item.isCurrentUser) {
        setError(ACCOUNT_MANAGE_MESSAGES.cannotEditCurrentUser);
        return;
      }

      setFormData({
        index: idx + 1,
        userName: item.username,
        password: "",
        authority: item.authority ?? "Read",
      });
      setEditIdx(idx);
    } else {
      // For new user, show next index number but don't set actual ID
      const nextIndex = combinedAccounts.length + 1;
      setFormData({ ...ACCOUNT_MANAGE_INITIAL_FORM, index: nextIndex });
      setEditIdx(null);
    }
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setError(null);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSave = async () => {
    // Validate form data
    if (!formData.userName.trim() || !formData.password.trim()) {
      setError(ACCOUNT_MANAGE_MESSAGES.formRequired);
      return;
    }

    const userData = {
      username: formData.userName.trim(),
      password: formData.password,
      authority: formData.authority,
    };

    let success = false;
    if (editIdx !== null) {
      // Update existing user
      success = await updateUser(userData);
    } else {
      // Create new user
      success = await saveUser(userData);
    }

    if (success) {
      setIsModalOpen(false);
      setError(null);
    }
  };

  return (
    <div style={AccountManagePageWrapStyle} data-native-scroll>
      <div style={AccountManagePageInnerStyle}>
        {/* ── Breadcrumb ── */}
        <div
          style={{
            fontSize: 12,
            color: C.mutedText,
            marginBottom: 16,
            fontWeight: 400,
            display: "flex",
            alignItems: "center",
            gap: 4,
            flexWrap: "wrap",
          }}
        >
          <span>{ACCOUNT_MANAGE_BREADCRUMB[0]}</span>
          <span>&gt;</span>
          <span>{ACCOUNT_MANAGE_BREADCRUMB[1]}</span>
          <span>&gt;</span>
          <span style={{ color: C.strongText, fontWeight: 600 }}>
            {ACCOUNT_MANAGE_BREADCRUMB[2]}
          </span>
        </div>

        {toast.msg && (
          <Alert
            severity={toast.type}
            onClose={() => setToast(ACCOUNT_MANAGE_DEFAULT_TOAST)}
            sx={{
              position: "fixed",
              top: 20,
              right: 20,
              zIndex: 9999,
              minWidth: 300,
              boxShadow: 3,
            }}
          >
            {toast.msg}
          </Alert>
        )}

        {/* Error Message */}
        {error && (
          <Alert
            severity="error"
            onClose={() => setError(null)}
            sx={{
              position: "fixed",
              top: 20,
              right: 20,
              zIndex: 9999,
              minWidth: 300,
              boxShadow: 3,
            }}
          >
            {error}
          </Alert>
        )}

        {/* Loading Indicator */}
        {loading && (
          <div
            style={{
              background: "#eff6ff",
              color: "#1d4ed8",
              padding: "16px",
              marginBottom: "16px",
              borderRadius: "8px",
              border: "1px solid #bfdbfe",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: "16px",
            }}
          >
            <svg
              style={{
                animation: "spin 1s linear infinite",
                width: "20px",
                height: "20px",
                marginRight: "12px",
                color: "#1d4ed8",
              }}
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
            >
              <circle
                style={{ opacity: "0.25" }}
                cx="12"
                cy="12"
                r="10"
                stroke="currentColor"
                strokeWidth="4"
              ></circle>
              <path
                style={{ opacity: "0.75" }}
                fill="currentColor"
                d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
              ></path>
            </svg>
            <span style={{ fontWeight: "500" }}>
              {ACCOUNT_MANAGE_MESSAGES.loading}
            </span>
          </div>
        )}

        {/* Table */}
        <div
          style={{
            ...tableContainerStyle,
            background: C.cardBg,
            border: `1px solid ${C.cardBorder}`,
            borderRadius: CARD_RADIUS,
          }}
        >
          <div style={blueBarStyle}>
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                flexWrap: "wrap",
              }}
            >
              <span>{ACCOUNT_MANAGE_CARD_TITLE}</span>
              {selected.length > 0 && (
                <span
                  style={{
                    background: "#eff6ff",
                    color: C.accent,
                    fontSize: 11,
                    fontWeight: 700,
                    padding: "5px 12px",
                    borderRadius: 999,
                    border: `1px solid ${C.accent}`,
                  }}
                >
                  {ACCOUNT_MANAGE_MESSAGES.selectedCount(selected.length)}
                </span>
              )}
            </div>
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                flexWrap: "wrap",
              }}
            >
              <Btn
                variant={ACCOUNT_MANAGE_BUTTON_VARIANTS.CANCEL}
                onClick={handleInverse}
                disabled={loading}
                style={ACCOUNT_MANAGE_TOOLBAR_CANCEL_BUTTON_STYLE}
              >
                {ACCOUNT_MANAGE_BUTTON_LABELS.INVERSE}
              </Btn>
              <Btn
                variant={ACCOUNT_MANAGE_BUTTON_VARIANTS.CANCEL}
                onClick={handleClearAll}
                disabled={loading || accounts.length === 0}
                style={ACCOUNT_MANAGE_TOOLBAR_CANCEL_BUTTON_STYLE}
              >
                {ACCOUNT_MANAGE_BUTTON_LABELS.CLEAR_ALL}
              </Btn>
              <Btn
                variant={ACCOUNT_MANAGE_BUTTON_VARIANTS.CANCEL}
                onClick={() => {
                  if (!canWrite) {
                    showReadOnlyToast();
                    return;
                  }
                  handleDelete();
                }}
                disabled={loading || selected.length === 0}
                style={ACCOUNT_MANAGE_TOOLBAR_CANCEL_BUTTON_STYLE}
              >
                <DeleteOutlineOutlinedIcon sx={{ fontSize: 16 }} />
                {ACCOUNT_MANAGE_BUTTON_LABELS.DELETE}
              </Btn>
              <Btn
                variant={ACCOUNT_MANAGE_BUTTON_VARIANTS.PRIMARY}
                onClick={() => {
                  if (!canWrite) {
                    showReadOnlyToast();
                    return;
                  }
                  handleOpenModal();
                }}
                disabled={loading}
                style={ACCOUNT_MANAGE_TOOLBAR_PRIMARY_BUTTON_STYLE}
              >
                {ACCOUNT_MANAGE_BUTTON_LABELS.ADD_NEW}
              </Btn>
            </div>
          </div>
          <div style={{ overflowX: "auto", width: "100%" }}>
            <table
              style={{
                width: "100%",
                minWidth: 600,
                borderCollapse: "separate",
                borderSpacing: 0,
              }}
            >
              <thead>
                <tr>
                  {ACCOUNT_MANAGE_TABLE_COLUMNS.map((col, colIdx) => {
                    const isFirst = colIdx === 0;
                    const isLast =
                      colIdx === ACCOUNT_MANAGE_TABLE_COLUMNS.length - 1;
                    return (
                      <TH
                        key={col.key}
                        style={{
                          position: "sticky",
                          top: 0,
                          zIndex: 10,
                          ...(isFirst
                            ? { width: 40, padding: 0, borderLeft: "none" }
                            : {}),
                          ...(isLast ? { width: 70, borderRight: "none" } : {}),
                        }}
                      >
                        {col.key === "choose" ? (
                          <Checkbox
                            size="small"
                            checked={allPageSelected}
                            indeterminate={somePageSelected}
                            onChange={handleToggleAll}
                            sx={checkboxSx}
                          />
                        ) : (
                          col.label
                        )}
                      </TH>
                    );
                  })}
                </tr>
              </thead>
              <tbody>
                {combinedAccounts.length === 0 ? (
                  <tr>
                    <td
                      colSpan={ACCOUNT_MANAGE_TABLE_COLUMNS.length}
                      style={{
                        ...tdStyle,
                        padding: "32px 14px",
                        borderRight: "none",
                        borderLeft: "none",
                        borderBottom: "none",
                        color: C.labelText,
                        fontWeight: 600,
                      }}
                    >
                      {loading
                        ? ACCOUNT_MANAGE_MESSAGES.loadingTable
                        : ACCOUNT_MANAGE_MESSAGES.noData}
                    </td>
                  </tr>
                ) : (
                  combinedAccounts.map((item, idx) => {
                    const realIdx = idx;
                    const isSelected = selected.includes(realIdx);
                    const isLastRow = idx === combinedAccounts.length - 1;
                    const rowBg = isSelected
                      ? "#f0f9ff"
                      : idx % 2 === 1
                        ? "#f8fafc"
                        : "#ffffff";
                    const lastRowCellStyle = isLastRow
                      ? { borderBottom: "none" }
                      : {};
                    return (
                      <tr
                        key={realIdx}
                        style={{
                          background: rowBg,
                          transition: "background 0.15s ease",
                        }}
                        onMouseEnter={(e) => {
                          if (!isSelected)
                            e.currentTarget.style.background = "#f1f5f9";
                        }}
                        onMouseLeave={(e) => {
                          if (!isSelected)
                            e.currentTarget.style.background = rowBg;
                        }}
                      >
                        {/* Choose */}
                        <td
                          style={{
                            ...tdStyle,
                            background: rowBg,
                            borderLeft: "none",
                            width: 40,
                            ...lastRowCellStyle,
                          }}
                        >
                          {!item.isAdmin && (
                            <Checkbox
                              size="small"
                              checked={isSelected}
                              onChange={() => handleSelectRow(realIdx)}
                              sx={checkboxSx}
                            />
                          )}
                        </td>
                        {/* Id */}
                        <td
                          style={{
                            ...tdStyle,
                            background: rowBg,
                            color: C.mutedText,
                            fontWeight: 500,
                            ...lastRowCellStyle,
                          }}
                        >
                          {realIdx + 1}
                        </td>
                        {/* Username */}
                        <td
                          style={{
                            ...tdStyle,
                            background: rowBg,
                            fontWeight: 500,
                            textAlign: "left",
                            ...lastRowCellStyle,
                          }}
                        >
                          {item.username}
                        </td>
                        {/* Authority */}
                        <td
                          style={{
                            ...tdStyle,
                            background: rowBg,
                            fontWeight: 500,
                            ...lastRowCellStyle,
                          }}
                        >
                          {item.authority ?? "-"}
                        </td>
                        {/* Modify */}
                        <td
                          style={{
                            ...tdStyle,
                            background: rowBg,
                            borderRight: "none",
                            ...lastRowCellStyle,
                          }}
                        >
                          <div
                            style={{
                              display: "flex",
                              justifyContent: "center",
                            }}
                          >
                            <EditDocumentIcon
                              titleAccess="Edit"
                              style={{
                                cursor: canWrite ? "pointer" : "not-allowed",
                                color: ACCOUNT_MANAGE_ICON_COLORS.EDIT,
                                fontSize: 22,
                                opacity: canWrite ? 0.7 : 0.3,
                                transition: "opacity 0.15s ease",
                              }}
                              onClick={() => {
                                if (!canWrite) {
                                  showReadOnlyToast();
                                  return;
                                }
                                if (item.isAdmin) {
                                  showToast(
                                    ACCOUNT_MANAGE_MESSAGES.cannotModifyAdmin,
                                    "error",
                                  );
                                  return;
                                }
                                handleOpenModal(item, realIdx);
                              }}
                              onMouseEnter={(e) => {
                                if (canWrite) {
                                  e.currentTarget.style.opacity = "1";
                                }
                              }}
                              onMouseLeave={(e) => {
                                if (canWrite) {
                                  e.currentTarget.style.opacity = "0.7";
                                }
                              }}
                            />
                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
          {combinedAccounts.length > 0 && (
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                padding: "7px 14px",
                background: "#ffffff",
                borderTop: `1px solid ${C.cardBorder}`,
                borderBottomLeftRadius: CARD_RADIUS,
                borderBottomRightRadius: CARD_RADIUS,
              }}
            >
              <span style={{ fontSize: 11, color: C.mutedText }}>
                {ACCOUNT_MANAGE_MESSAGES.showingRecords(
                  combinedAccounts.length,
                )}
              </span>
            </div>
          )}
        </div>
        {/* Table Buttons (removed as they are now in the top bar) */}
        <div style={{ padding: 0 }} />
      </div>
      {/* Modal */}
      {isModalOpen && (
        <div
          style={modalOverlayStyle}
          onClick={() => {
            if (!loading) handleCloseModal();
          }}
        >
          <div style={modalStyle} onClick={(e) => e.stopPropagation()}>
            <div style={modalHeaderStyle}>{ACCOUNT_MANAGE_MODAL_TITLE}</div>
            <div style={modalBodyStyle}>
              <div style={addHostFormPanelStyle}>
                {ACCOUNT_MANAGE_MODAL_FIELDS.map((field) => (
                  <div key={field.name} style={modalRowStyle}>
                    <Tooltip
                      title={ACCOUNT_MANAGE_TOOLTIPS[field.name] || ""}
                      {...tooltipProps}
                    >
                      <label style={modalLabelStyle}>{field.label}:</label>
                    </Tooltip>
                    {field.type === "select" ? (
                      <select
                        name={field.name}
                        value={formData[field.name]}
                        onChange={handleInputChange}
                        style={{
                          ...modalInputStyle,
                          ...(field.disabled
                            ? {
                                backgroundColor: "#f1f5f9",
                                color: "#94a3b8",
                                cursor: "not-allowed",
                              }
                            : {}),
                        }}
                        disabled={field.disabled}
                        {...(field.disabled ? {} : inputInteraction)}
                      >
                        {field.options.map((opt) => (
                          <option key={opt.value} value={opt.value}>
                            {opt.label}
                          </option>
                        ))}
                      </select>
                    ) : (
                      <input
                        type={field.type}
                        name={field.name}
                        value={formData[field.name]}
                        onChange={handleInputChange}
                        style={{
                          ...modalInputStyle,
                          ...(field.disabled
                            ? {
                                backgroundColor: "#f1f5f9",
                                color: "#94a3b8",
                                cursor: "not-allowed",
                              }
                            : {}),
                        }}
                        disabled={field.disabled}
                        {...(field.disabled ? {} : inputInteraction)}
                      />
                    )}
                  </div>
                ))}
              </div>
            </div>
            <div style={modalFooterStyle}>
              <Btn
                variant={ACCOUNT_MANAGE_BUTTON_VARIANTS.PRIMARY}
                onClick={handleSave}
                disabled={loading}
                style={ACCOUNT_MANAGE_BUTTON_STYLE}
              >
                {loading
                  ? ACCOUNT_MANAGE_BUTTON_LABELS.SAVING
                  : ACCOUNT_MANAGE_BUTTON_LABELS.SAVE}
              </Btn>
              <Btn
                variant={ACCOUNT_MANAGE_BUTTON_VARIANTS.CANCEL}
                onClick={handleCloseModal}
                disabled={loading}
                style={ACCOUNT_MANAGE_BUTTON_STYLE}
              >
                {ACCOUNT_MANAGE_BUTTON_LABELS.CLOSE}
              </Btn>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AccountManage;

import React from "react";
import { CircularProgress, useMediaQuery } from "@mui/material";
import { C } from "../../../theme/pbxTokens";
import {
  PBX_MONITOR_BREADCRUMB_SEGMENTS,
  PBX_MONITOR_STAT_LABELS,
  PBX_MONITOR_TAB_LABELS,
  PBX_MONITOR_TAB_VALUES,
} from "../../../constants/PbxMonitorConstants";
import {
  Btn,
  ExtensionTableListEmptyState as TableListEmptyState,
  ExtensionTableListLoading as TableListLoading,
  TH,
  extensionPageInnerStyle as pbxPageInnerStyle,
  extensionPageWrapStyle as pbxPageWrapStyle,
} from "../../../components/common";
import { usePbxMonitorPage } from "./hooks/usePbxMonitorPage";
import {
  PageBreadcrumb,
  PbxMonitorToolbarSearchBar,
  StatCard,
  StatusBadge,
  TD,
  TypePill,
} from "./components/PbxMonitorFormFields";
import {
  PBX_MONITOR_COMPACT_MQ,
  PBX_MONITOR_EXTENSION_TABLE_MIN_WIDTH,
  PBX_MONITOR_TRUNK_ACCENT,
  PBX_MONITOR_TRUNK_TABLE_MIN_WIDTH,
  pbxMonitorCancelBtnStyle,
  pbxMonitorCardHeaderStyle,
  pbxMonitorCardStyle,
  pbxMonitorFooterStyle,
  pbxMonitorHeaderLeftStyle,
  pbxMonitorHeaderToolbarStyle,
  tableStyle,
  tableWrapStyle,
} from "./components/PbxMonitorTableHelpers";

const PbxMonitor = () => {
  const isCompact = useMediaQuery(PBX_MONITOR_COMPACT_MQ);
  const vm = usePbxMonitorPage();
  const {
    activeTab,
    setActiveTab,
    hasLoaded,
    extensionRows,
    trunkRows,
    lastUpdated,
    searchQuery,
    setSearchQuery,
    isRefreshing,
    loadData,
    extRegistered,
    extUnregistered,
    trkRegistered,
    filteredExtensions,
    filteredTrunks,
    tableRows,
    searchPlaceholder,
    emptyMessage,
    recordLabel,
    getStatus,
  } = vm;

  return (
    <div style={{ ...pbxPageWrapStyle, ...(isCompact ? { padding: 8 } : {}) }}>
      <div style={pbxPageInnerStyle}>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 12,
            marginBottom: 16,
            flexWrap: "wrap",
            ...(isCompact
              ? { flexDirection: "column", alignItems: "flex-start", gap: 6 }
              : {}),
          }}
        >
          <PageBreadcrumb
            segments={PBX_MONITOR_BREADCRUMB_SEGMENTS}
            style={{ marginBottom: 0 }}
          />
          {lastUpdated && (
            <span
              style={{
                fontSize: 11,
                color: C.mutedText,
                flexShrink: 0,
                ...(isCompact ? { marginLeft: 0 } : { marginLeft: "auto" }),
              }}
            >
              Updated {lastUpdated.toLocaleTimeString()}
            </span>
          )}
        </div>

        {/* Stats */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: isCompact
              ? "repeat(2, minmax(0, 1fr))"
              : "repeat(auto-fit, minmax(160px, 1fr))",
            gap: isCompact ? 10 : 16,
            marginBottom: 12,
            width: "100%",
          }}
        >
          <StatCard
            label={PBX_MONITOR_STAT_LABELS.totalExtensions}
            value={extensionRows.length}
            accent={C.accent}
            ready={hasLoaded}
          />
          <StatCard
            label={PBX_MONITOR_STAT_LABELS.registered}
            value={extRegistered}
            accent={C.successGreen}
            ready={hasLoaded}
          />
          <StatCard
            label={PBX_MONITOR_STAT_LABELS.unregistered}
            value={extUnregistered}
            accent={C.errorRed}
            ready={hasLoaded}
          />
          <StatCard
            label={PBX_MONITOR_STAT_LABELS.registeredTrunks}
            value={trkRegistered}
            accent={PBX_MONITOR_TRUNK_ACCENT}
            ready={hasLoaded}
          />
        </div>

        <div style={pbxMonitorCardStyle}>
          <div
            style={{
              ...pbxMonitorCardHeaderStyle,
              ...(isCompact
                ? {
                    flexDirection: "column",
                    alignItems: "stretch",
                    padding: "10px 12px",
                  }
                : {}),
            }}
          >
            <div
              style={{
                ...pbxMonitorHeaderLeftStyle,
                ...(isCompact ? { width: "100%" } : {}),
              }}
            >
              <Btn
                type="button"
                variant={
                  activeTab === PBX_MONITOR_TAB_VALUES.extension
                    ? "tabActive"
                    : "tabInactive"
                }
                onClick={() => setActiveTab(PBX_MONITOR_TAB_VALUES.extension)}
                style={{ height: 30, borderRadius: 4 }}
              >
                {PBX_MONITOR_TAB_LABELS.extension}
              </Btn>
              <Btn
                type="button"
                variant={
                  activeTab === PBX_MONITOR_TAB_VALUES.trunk
                    ? "tabActive"
                    : "tabInactive"
                }
                onClick={() => setActiveTab(PBX_MONITOR_TAB_VALUES.trunk)}
                style={{ height: 30, borderRadius: 4 }}
              >
                {PBX_MONITOR_TAB_LABELS.trunk}
              </Btn>
            </div>

            <div
              style={{
                ...pbxMonitorHeaderToolbarStyle,
                ...(isCompact
                  ? {
                      width: "100%",
                      marginLeft: 0,
                      justifyContent: "stretch",
                    }
                  : {}),
              }}
            >
              <PbxMonitorToolbarSearchBar
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder={searchPlaceholder}
                fitPlaceholder={!isCompact}
                fullWidth={isCompact}
              />
              <Btn
                variant="cancel"
                onClick={() => loadData(false)}
                disabled={isRefreshing}
                style={pbxMonitorCancelBtnStyle}
              >
                {isRefreshing ? (
                  <>
                    <CircularProgress size={11} style={{ color: "#374151" }} />
                    Refreshing...
                  </>
                ) : (
                  "Refresh"
                )}
              </Btn>
            </div>
          </div>

          {!hasLoaded && isRefreshing ? (
            <TableListLoading />
          ) : hasLoaded && tableRows.length === 0 ? (
            <TableListEmptyState message={emptyMessage} showButton={false} />
          ) : (
            <div style={tableWrapStyle}>
              {activeTab === PBX_MONITOR_TAB_VALUES.extension ? (
                <table
                  style={{
                    ...tableStyle,
                    ...(isCompact
                      ? { minWidth: PBX_MONITOR_EXTENSION_TABLE_MIN_WIDTH }
                      : {}),
                  }}
                >
                  <thead>
                    <tr>
                      <TH>Status</TH>
                      <TH>Extension</TH>
                      <TH>Name</TH>
                      <TH>Type</TH>
                      <TH style={{ borderRight: "none" }}>IP & Port</TH>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredExtensions.map((row, idx) => {
                      const status = getStatus(row.status);
                      const rowBg = idx % 2 === 1 ? "#f8fafc" : "#ffffff";
                      const isLastRow = idx === filteredExtensions.length - 1;
                      const lastRowCellStyle = isLastRow
                        ? { borderBottom: "none" }
                        : {};

                      return (
                        <tr
                          key={row.extension}
                          style={{
                            background: rowBg,
                            transition: "background 0.15s ease",
                          }}
                          onMouseEnter={(e) => {
                            e.currentTarget.style.background = "#f8fafc";
                          }}
                          onMouseLeave={(e) => {
                            e.currentTarget.style.background = rowBg;
                          }}
                        >
                          <TD
                            align="center"
                            bg={rowBg}
                            style={lastRowCellStyle}
                          >
                            <div
                              style={{
                                display: "flex",
                                justifyContent: "center",
                              }}
                            >
                              <StatusBadge
                                tone={status.tone}
                                text={status.text}
                              />
                            </div>
                          </TD>
                          <TD
                            align="center"
                            bg={rowBg}
                            style={lastRowCellStyle}
                          >
                            {row.extension}
                          </TD>
                          <TD
                            align="center"
                            bg={rowBg}
                            style={lastRowCellStyle}
                          >
                            {row.name}
                          </TD>
                          <TD
                            align="center"
                            bg={rowBg}
                            style={lastRowCellStyle}
                          >
                            <TypePill text="SIP" />
                          </TD>
                          <TD
                            mono
                            bg={rowBg}
                            style={{
                              ...lastRowCellStyle,
                              borderRight: "none",
                            }}
                          >
                            {row.ip_port}
                          </TD>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              ) : (
                <table
                  style={{
                    ...tableStyle,
                    ...(isCompact
                      ? { minWidth: PBX_MONITOR_TRUNK_TABLE_MIN_WIDTH }
                      : {}),
                  }}
                >
                  <thead>
                    <tr>
                      <TH>Status</TH>
                      <TH>Trunk Name</TH>
                      <TH>Type</TH>
                      <TH style={{ borderRight: "none" }}>Host</TH>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredTrunks.map((row, idx) => {
                      const status = getStatus(row.status);
                      const rowBg = idx % 2 === 1 ? "#f8fafc" : "#ffffff";
                      const isLastRow = idx === filteredTrunks.length - 1;
                      const lastRowCellStyle = isLastRow
                        ? { borderBottom: "none" }
                        : {};

                      return (
                        <tr
                          key={row.id}
                          style={{
                            background: rowBg,
                            transition: "background 0.15s ease",
                          }}
                          onMouseEnter={(e) => {
                            e.currentTarget.style.background = "#f8fafc";
                          }}
                          onMouseLeave={(e) => {
                            e.currentTarget.style.background = rowBg;
                          }}
                        >
                          <TD
                            align="center"
                            bg={rowBg}
                            style={lastRowCellStyle}
                          >
                            <div
                              style={{
                                display: "flex",
                                justifyContent: "center",
                              }}
                            >
                              <StatusBadge
                                tone={status.tone}
                                text={status.text}
                              />
                            </div>
                          </TD>
                          <TD
                            align="center"
                            bg={rowBg}
                            style={lastRowCellStyle}
                          >
                            {row.trunk_name}
                          </TD>
                          <TD
                            align="center"
                            bg={rowBg}
                            style={lastRowCellStyle}
                          >
                            <TypePill text={row.type || "SIP"} />
                          </TD>
                          <TD
                            mono
                            bg={rowBg}
                            style={{
                              ...lastRowCellStyle,
                              borderRight: "none",
                            }}
                          >
                            {row.host_ip_port}
                          </TD>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              )}
            </div>
          )}

          {hasLoaded && tableRows.length > 0 && (
            <div style={pbxMonitorFooterStyle}>
              <span style={{ fontSize: 11, color: C.mutedText }}>
                Showing {tableRows.length} {recordLabel}
              </span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default PbxMonitor;

import React, { useLayoutEffect, useRef, useState } from "react";
import { CircularProgress, useMediaQuery } from "@mui/material";
import { Btn, TH } from "../../../../components/common";
import {
  C,
  FOCUS_RING_SHADOW,
  OUTLINED_BORDER,
  OUTLINED_FOCUS,
  OUTLINED_HOVER,
} from "../../../../theme/pbxTokens";
import { ACTIVE_CALL_QUEUE_AGENT_SEARCH_PLACEHOLDER, ACTIVE_CALL_QUEUE_BREADCRUMB_SEGMENTS, ACTIVE_CALL_QUEUE_COMPACT_MQ, ACTIVE_CALL_QUEUE_EMPTY_MESSAGE, ACTIVE_CALL_QUEUE_LIST_HEADING, ACTIVE_CALL_QUEUE_STATS_BREADCRUMB_SEGMENTS, ACTIVE_CALL_QUEUE_STATS_BTN_LABEL, ACTIVE_CALL_QUEUE_STATS_TABLE_MIN_WIDTH, ACTIVE_CALL_QUEUE_TAB_LABELS, ACTIVE_CALL_QUEUE_TAB_VALUES } from "../../../../constants/ActiveCallQueueConstants";
import { useActiveCallQueueStatsPage } from "../hooks/useActiveCallQueueStatsPage";
import { normalizeActiveCallQueue } from "../utils/ActiveCallQueueTransformers";

const PageBreadcrumb = ({ segments, style }) => (
  <div
    style={{
      fontSize: 12,
      color: "#94a3b8",
      marginBottom: 16,
      fontWeight: 400,
      display: "flex",
      alignItems: "center",
      gap: 4,
      flexWrap: "wrap",
      ...style,
    }}
  >
    {segments.map((label, index) => (
      <React.Fragment key={`${label}-${index}`}>
        {index > 0 ? <span>&gt;</span> : null}
        <span
          style={
            index === segments.length - 1
              ? { color: "#1e293b", fontWeight: 600 }
              : undefined
          }
        >
          {label}
        </span>
      </React.Fragment>
    ))}
  </div>
);
const pbxPageWrapStyle = {
  backgroundColor: C.pageBg,
  minHeight: "calc(100vh - 80px)",
  padding: 16,
  boxSizing: "border-box",
};

const pbxPageInnerStyle = {
  width: "100%",
  maxWidth: "100%",
  margin: "0 auto",
};

const TableListLoading = () => (
  <div
    style={{
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      padding: 48,
    }}
  >
    <CircularProgress size={28} style={{ color: C.accent }} />
  </div>
);

const TableListEmptyState = ({
  message,
  onAddNew,
  buttonLabel = "+ Add New",
  showButton = true,
}) => (
  <div
    style={{
      display: "flex",
      flexDirection: "column",
      alignItems: "center",
      justifyContent: "center",
      minHeight: 240,
      padding: 24,
