              <Btn
                type="button"
                variant={
                  activeTab === ACTIVE_CALL_QUEUE_TAB_VALUES.queue
                    ? "tabActive"
                    : "tabInactive"
                }
                onClick={() => setActiveTab(ACTIVE_CALL_QUEUE_TAB_VALUES.queue)}
